window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0051", [{"word":"evaluation","ipa_uk":"/ˌiːvæljuˈeɪʃn/","ipa_us":"/ˌiːvæljuˈeɪʃən/","definition_zh":"评估；评价；鉴定；（数学）求值","definition_en":"the act of judging the value, quality, or importance of something against a standard","core_image":"一张评分表摊在桌上：左边是标准，右边是待评的对象，笔尖停在两者之间的差距上。","scene":"期末评审会上，老师把学生的作品集与评分标准逐条对照。At the end of term the teacher sets the portfolio against the marking criteria and writes a grade: that is an evaluation.","sceneCN":"这里 evaluation 是「按标准评定价值或水平」（第 1 个义项：按某一标准判断某物的价值、质量或重要性）；句意：期末评审会上，老师把作品集对照评分标准逐条评定并写下等级，这就是评估。","pos":[{"tag":"n.","zh":"评估；评价；鉴定；评估结果；（数学）求值"}],"collocations":[{"phrase":"a fair evaluation","zh":"公正的评估"},{"phrase":"performance evaluation","zh":"绩效评估"},{"phrase":"program evaluation","zh":"项目评估"},{"phrase":"evaluation criteria","zh":"评估标准"},{"phrase":"clinical evaluation","zh":"临床评估"},{"phrase":"a preliminary evaluation","zh":"初步评估"}],"forms":[{"label":"复数（名词）","form":"evaluations"}],"derivatives":[{"word":"evaluate","pos":"v.","zh":"评估；评价；求值"},{"word":"evaluative","pos":"adj.","zh":"评价性的；带评判意味的"},{"word":"evaluator","pos":"n.","zh":"评估者；评审员"},{"word":"self-evaluation","pos":"n.","zh":"自我评估"}],"senses":[{"no":"01","title":"Judging against a standard","titleCN":"评估：把对象放到标准旁边","definition":"the act of judging the value, quality, or importance of something by comparing it with a standard","definitionCN":"按某一标准判断某物的价值、质量或重要性","example":"The committee carried out a careful evaluation of the proposal.","exampleCN":"委员会对该提案进行了仔细评估。","why":"Evaluation begins when a standard is placed beside a case. The act is the comparison itself, not the object being compared.","whyCN":"评估始于把标准放到案例旁边；真正发生的事情是“比较”，而不是被比较的对象。"},{"no":"02","title":"The assessment produced","titleCN":"评估结果：写下来的鉴定结论","definition":"the assessment or judgement that results from such a comparison","definitionCN":"比较之后得出的评估结论或鉴定意见","example":"The report contains a positive evaluation of the new system.","exampleCN":"报告对新系统给出了正面评价。","why":"Once the comparison is finished, the judgement is written down and becomes a thing others can read, quote, and act on.","whyCN":"比较一旦完成，判断就被写下来，成为别人可以阅读、引用并据此行动的“东西”。"},{"no":"03","title":"Academic grading","titleCN":"学业评价：把学习成果换算成等级","definition":"the process of judging a student's work against learning goals","definitionCN":"对照学习目标评定学生学业表现的过程","example":"Course evaluation combines essays, tests, and class participation.","exampleCN":"课程评价综合了论文、测验和课堂参与。","why":"Schoolwork is measured against stated learning goals, so the same act of comparison produces a grade rather than a price.","whyCN":"学业对照的是明示的学习目标，因此同一种比较产生的是等级，而不是价格。"},{"no":"04","title":"Program review","titleCN":"项目评估：拿目标对照实际结果","definition":"a systematic review of whether a program, policy, or project achieved its aims","definitionCN":"系统审查项目、政策或计划是否达成既定目标","example":"The program evaluation compared costs with measured outcomes.","exampleCN":"项目评估把成本与实测结果作了比较。","why":"A program is compared with its stated aims and its measured results; the gap between the two is the finding.","whyCN":"项目被放在“声称的目标”与“实测的结果”之间；两者的差距就是评估发现。"},{"no":"05","title":"Clinical assessment","titleCN":"临床评估：把症状放进正常范围","definition":"a medical judgement of a patient's condition based on symptoms and tests","definitionCN":"依据症状与检查结果对病人状况作出的医学判断","example":"The patient was sent for a cardiac evaluation before surgery.","exampleCN":"病人在手术前被送去做心脏评估。","why":"Doctors compare symptoms and test values with normal ranges; the evaluation decides whether the body is inside or outside those ranges.","whyCN":"医生把症状与检验数值放进正常范围里比较；评估决定身体是在范围内还是范围外。"},{"no":"06","title":"Mathematical evaluation","titleCN":"数学求值：按运算规则算出唯一结果","definition":"the process of calculating the value of an expression or function","definitionCN":"计算表达式或函数的值","example":"Evaluation of the expression gives a single numerical answer.","exampleCN":"对该表达式求值会得到一个数值答案。","why":"In algebra the standard is the rules of operation. Applying them step by step leaves exactly one value, so evaluation here means execution, not opinion.","whyCN":"代数里的标准是运算规则；逐步套用之后只剩一个值，所以这里的 evaluation 是“执行计算”，不是“发表意见”。"},{"no":"07","title":"Staff appraisal","titleCN":"绩效评估：把工作表现对照岗位要求","definition":"a formal judgement of an employee's performance against job expectations","definitionCN":"对照岗位要求对员工工作表现作出的正式评定","example":"Annual evaluation determines promotion and salary review.","exampleCN":"年度考核决定晋升与调薪评审。","why":"An employee is measured against job expectations, and the result is attached to pay, promotion, and training decisions.","whyCN":"员工被对照岗位期待来衡量，而结果会挂到薪酬、晋升和培训决定上。"},{"no":"08","title":"Value judgement","titleCN":"价值判断：评价“值得”而非“多少钱”","definition":"a judgement about worth, merit, or significance rather than price","definitionCN":"关于价值、优点或意义的判断，而非价格高低的判断","example":"A value evaluation asks what a thing is worth, not merely what it costs.","exampleCN":"价值评价问的是某物值多少“意义”，而不只是值多少钱。","why":"Here the standard is not a number but a notion of worth, so the comparison becomes philosophical: what makes something matter at all.","whyCN":"这里的标准不是数字，而是“值得”的观念；比较由此变成哲学问题：是什么让某物重要。"}],"etymology":{"intro":{"en":"Evaluation reaches English through French. The core is Latin valere, to be worth, which also gives value, valid, and prevail.","cn":"evaluation 经由法语进入英语。核心是拉丁语 valere“有价值、有价值”，它也给出 value、valid、prevail。"},"items":[{"era":"LATIN valere","en":"Valere meant to be worth, to be strong, or to have power. The worth sense survives in value and valuation, while the strength sense survives in valid and prevail.","cn":"valere 意为“值、强壮、有力量”。‘值’义留在 value 与 valuation 中，‘力量’义留在 valid 与 prevail 中。"},{"era":"LATIN valor","en":"A noun of worth or value, also courage. English valor keeps only the courage sense, while value took over the worth sense through French.","cn":"表示“价值”的名词，也可指勇气。英语 valor 只保留勇气义；‘价值’义则由法语 value 接管。"},{"era":"FRENCH value / valoir","en":"Old French valoir meant to be worth, and the noun value named the worth itself. English borrowed both value and valour from this line.","cn":"古法语 valoir 意为“值”，名词 value 指“价值本身”。英语的 value 与 valour 都来自这条线。"},{"era":"FRENCH évaluer","en":"French built évaluer by adding the prefix é- (from Latin ex-) to value: to bring out the value, hence to assess. The verb is attested later than the noun value.","cn":"法语在 value 前加 é-（来自拉丁 ex-）造出 évaluer：把价值‘取出来’，因而表示‘估定价值’。该动词的书面记录晚于名词 value。"},{"era":"ENGLISH 19c","en":"English adopted evaluation in the 19th century from French évaluation. It first served administration and education, where a formal standard had to be applied to a case.","cn":"英语在 19 世纪从法语 évaluation 借入 evaluation，最先用于行政与教育：那里必须先有正式标准，再套到具体案例上。"},{"era":"MODERN ENGLISH","en":"The 20th century added program evaluation, clinical evaluation, and machine evaluation. Computing then borrowed the word for calculating an expression, where the standard is a rule rather than a value judgement.","cn":"20 世纪增加了项目评估、临床评估与机器评估；计算领域随后借该词表示‘对表达式求值’，那里的标准是规则，而不是价值判断。"}]},"similar":{"note":{"en":"The first group is the immediate word family around evaluate; the second compares the main kinds of judging, each with a different standard and a different output.","cn":"第一组是 evaluate 周围的直接词族；第二组比较几种主要的‘评判’，各自的标准与产出都不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"evaluate","ipa":"/ɪˈvæljueɪt/","tag":"verb","definition":"to judge something against a standard. It is the action behind evaluation, and it can also mean to calculate a value.","definitionCN":"按标准判断某物。它是 evaluation 背后的动作，也可指计算一个值。"},{"word":"evaluative","ipa":"/ˌiːvæljuˈeɪtɪv/","tag":"adjective","definition":"expressing or involving a judgement of value. An evaluative comment says good or bad; a descriptive one does not.","definitionCN":"表达或涉及价值判断的。评价性评论会说好或坏，描述性评论则不会。"},{"word":"evaluator","ipa":"/ˌiːvæljuˈeɪtə/","tag":"person noun","definition":"the person or system that performs an evaluation. It names the judge, not the judgement.","definitionCN":"执行评估的人或系统；指评判者，而非评判本身。"},{"word":"valuation","ipa":"/ˌvæljuˈeɪʃn/","tag":"price-related noun","definition":"the act of deciding how much something is worth, especially in money. It is the financial cousin of evaluation.","definitionCN":"决定某物值多少，尤指金钱上的估价；是 evaluation 的财务表亲。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assessment","ipa":"/əˈsesmənt/","tag":"general judgement","definition":"a judgement of quality, ability, or risk. It is the broadest partner and often replaces evaluation in education and medicine.","definitionCN":"对质量、能力或风险的判断；是最宽泛的伙伴，在教育与医学中常替代 evaluation。"},{"word":"appraisal","ipa":"/əˈpraɪzl/","tag":"valued judgement","definition":"a judgement of worth, often of property or staff performance. It stresses the price or merit assigned.","definitionCN":"对价值的判断，常用于房产或员工绩效；强调被赋予的价格或功绩。"},{"word":"estimation","ipa":"/ˌestɪˈmeɪʃn/","tag":"approximate judgement","definition":"a rough calculation or opinion. It accepts uncertainty where evaluation claims a method.","definitionCN":"粗略的计算或看法；允许不确定，而 evaluation 声称有方法。"},{"word":"valuation","ipa":"/ˌvæljuˈeɪʃn/","tag":"monetary worth","definition":"the setting of a monetary value, especially by an expert. It answers how much money, not how good.","definitionCN":"尤指由专家设定金钱价值；回答‘值多少钱’，而不是‘有多好’。"},{"word":"rating","ipa":"/ˈreɪtɪŋ/","tag":"scored judgement","definition":"a grade or score on a scale. It is the output of an evaluation reduced to a number or letter.","definitionCN":"量表上的等级或分数；是评估结果被压缩成数字或字母。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: value plus the French action prefix é-. The image is bringing the worth of something out where it can be compared.","cn":"只用真实成分：value 加法语动作前缀 é-。意象是把某物的价值‘取出来’，放到可以比较的地方。"},"normal":[{"en":"E- is out, value is worth: evaluation brings the worth out for comparison.","cn":"e- 是向外，value 是价值：evaluation 就是把价值取出来做比较。"},{"en":"Value, valid, prevail, evaluation: one Latin root valere, three different survivals.","cn":"value、valid、prevail、evaluation：同一个拉丁词根 valere，三种不同的存活方式。"},{"en":"A rubric is evaluation made visible: criterion on the left, work on the right.","cn":"评分量规就是看得见的 evaluation：左边标准，右边作品。"},{"en":"In a hospital, evaluation is the normal range drawn beside your test result.","cn":"在医院里，evaluation 就是画在检验结果旁边的那个正常范围。"},{"en":"In algebra, evaluation is substitution plus arithmetic: the standard is the rule.","cn":"在代数里，evaluation 就是代入加运算：标准就是规则。"}],"abstract":[{"en":"Nothing can be evaluated without a standard; the standard is the hidden half of every judgement.","cn":"没有标准就无法评估；标准是每一次判断隐藏的另一半。"},{"en":"Evaluation turns a vague impression of good into something that can be compared and disputed.","cn":"评估把模糊的‘好’变成可比较、可争论的东西。"},{"en":"Every evaluation chooses what deserves to be measured, and that choice is itself a value judgement.","cn":"每次评估都在选择什么值得被衡量，而这个选择本身就是价值判断。"}]},"examples":[{"en":"A blind evaluation of the two treatments removed the doctors' expectations from the result.","cn":"对两种治疗做盲法评估，把医生的预期从结果中剔除了。"},{"en":"The evaluation found that the bridge would cost more to repair than to replace.","cn":"评估发现这座桥的维修成本高于重建成本。"},{"en":"Her evaluation of the poem was less about technique than about what it made her remember.","cn":"她对这首诗的评价，与其说关于技巧，不如说关于它唤起了什么记忆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"e-valuation：先问 value（值多少），再做 valuation（估价）——evaluation 就是评估。","word":"evaluation"},"root":"源自法语 évaluer / évaluation，核心是拉丁语 valere（值、强壮、有力量）：把某物的‘价值’取出来，与标准对照，因而表示评估。","sensesIntro":{"en":"Eight senses of evaluation, one act: a standard is set beside a case and a judgement is produced. The standard may be a rubric, a program goal, a normal range, an algebraic rule, a job description, or a notion of worth.","cn":"evaluation 的八个义项都围绕同一个动作：把标准放到案例旁边，产出一个判断。标准可以是评分量规、项目目标、正常范围、代数规则、岗位说明，或‘值得’的观念。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rubric on the left, a piece of work on the right, and a pen marking the gap.","cn":"核心意象：左边评分量规，右边作品，笔尖标出两者的差距。"},"chain":["LATIN VALERE = TO BE WORTH","FRENCH VALUE = WORTH","FRENCH ÉVALUER = TO ASSESS WORTH","EVALUATION = THE ACT OF ASSESSING","A STANDARD IS APPLIED TO A CASE","ANY FORMAL APPRAISAL, INCLUDING NUMBERS"],"branches":[{"senses":"01 · 08","en":"JUDGING WORTH: a general appraisal and a philosophical value judgement both ask what something is worth.","cn":"判断价值：一般评估与哲学价值判断，都在问某物值多少。"},{"senses":"02","en":"THE WRITTEN RESULT: the comparison hardens into a report that others can use.","cn":"写下的结果：比较固化成分报告，供他人使用。"},{"senses":"03 · 07","en":"JUDGING PEOPLE: student work and employee performance are both measured against stated expectations.","cn":"评判人：学生学业与员工绩效，都被对照明示的期待来衡量。"},{"senses":"04 · 05","en":"JUDGING SYSTEMS AND BODIES: a program is checked against its aims, a patient against normal ranges.","cn":"评判系统与身体：项目对照目标，病人对照正常范围。"},{"senses":"06","en":"JUDGING BY RULE: mathematical evaluation applies fixed operations until one value remains.","cn":"按规则判定：数学求值套用固定运算，直到只剩一个值。"}]},"affixes":{"intro":{"en":"Evaluation is value plus the French action prefix é- and the Latin noun suffix -ation. English extends the family with -ate, -ive, -or, and -ity.","cn":"evaluation 由 value、法语动作前缀 é- 与拉丁名词后缀 -ation 构成；英语再用 -ate、-ive、-or、-ity 扩展词族。"},"latinIntro":{"en":"The Latin base is valere to be worth or be strong, with the noun valor and the adjective validus. The French verb évaluer is a later Romance formation on value.","cn":"拉丁词基是 valere“值、强壮”，名词 valor，形容词 validus。法语动词 évaluer 则是在 value 上较晚形成的罗曼语派生。"},"items":[{"word":"value","structure":"Old French value < Latin valere (be worth)","meaning":"worth, importance, or monetary price","meaningCN":"价值；重要性；金钱上的价格","example":"The value of the land rose after the road opened.","exampleCN":"公路开通后，这块地的价值上涨了。"},{"word":"evaluate","structure":"é- (out) + value + -ate (verb)","meaning":"to assess the value or quality of something","meaningCN":"评估某物的价值或质量（-ate 构成动词）","example":"Researchers evaluate each model on the same data.","exampleCN":"研究者用同一批数据评估每个模型。"},{"word":"evaluative","structure":"evaluate + -ive (adjective)","meaning":"expressing a judgement of value","meaningCN":"表达价值判断的（-ive 构成形容词）","example":"The sentence is evaluative rather than purely factual.","exampleCN":"这个句子是评价性的，而非纯事实性的。"},{"word":"evaluator","structure":"evaluate + -or (agent noun)","meaning":"one who evaluates","meaningCN":"评估者（-or 构成施动者名词）","example":"An outside evaluator reviewed the department.","exampleCN":"一位外部评估者审查了该部门。"},{"word":"valuation","structure":"value + -ation (action noun)","meaning":"the act of setting a value, especially a price","meaningCN":"设定价值的行为，尤指估价（-ation 构成动作名词）","example":"The valuation of the company was higher than its debts.","exampleCN":"该公司的估值高于其债务。"},{"word":"valid","structure":"Latin validus (strong) < valere","meaning":"legally or logically sound","meaningCN":"法律上或逻辑上有效的；源自‘有力量’","example":"The argument is valid even if its premise is false.","exampleCN":"即使前提为假，这个论证在形式上仍然有效。"},{"word":"validity","structure":"valid + -ity (quality noun)","meaning":"the quality of being sound or well founded","meaningCN":"有效性；成立的程度（-ity 构成性质名词）","example":"The study's validity depends on how the sample was chosen.","exampleCN":"该研究的有效性取决于样本如何选取。"},{"word":"equivalence","structure":"aequi- (equal) + valere (be worth) + -ence","meaning":"the state of having equal value","meaningCN":"等值；等价状态（aequi-‘相等’+ valere‘值’）","example":"The two certificates have equivalence in this country.","exampleCN":"这两种证书在本国具有同等效力。"},{"word":"prevalent","structure":"prae- (before, beyond) + valere (have power) + -ent","meaning":"widespread or dominant","meaningCN":"盛行的；占优势的（prae-‘在前、超过’+ valere‘有力量’）","example":"The belief was prevalent among sailors of that era.","exampleCN":"这种看法在那个时代的水手中很盛行。"},{"word":"valor","structure":"Latin valor (worth, courage)","meaning":"bravery, especially in battle","meaningCN":"英勇，尤指战场上的勇气；本义为‘价值’","example":"The medal was awarded for valor under fire.","exampleCN":"这枚勋章因炮火下的英勇行为而授予。"}],"latinEntries":[{"word":"valere","structure":"Latin verb","meaning":"to be worth, be strong, have power","meaningCN":"值；强壮；有力量"},{"word":"valor","structure":"Latin noun","meaning":"worth, value; courage","meaningCN":"价值；勇气"},{"word":"validus","structure":"Latin adjective","meaning":"strong, sound, effective","meaningCN":"强壮的；健全的；有效的"}]}},{"word":"evolutionary","ipa_uk":"/ɪˌvɒljuːˈʃənəri/","ipa_us":"/ɪˌvɑːljuːˈʃənəri/","definition_zh":"进化的；演化的；渐进发展的；进化论的","definition_en":"relating to evolution, or changing gradually by small steps over time","core_image":"一棵不断分叉的树：每根枝条都比上一段多出一点差异，越往后分得越细。","scene":"生物课上，老师把不同鸟喙的标本排成一排。In the biology class the teacher lines up specimens of different beaks and explains the evolutionary change in shape.","sceneCN":"这里 evolutionary 是「与生物进化有关的」（第 1 个义项：与物种经过世代发生改变的生物过程有关）；句意：生物课上，老师把不同鸟喙的标本排成一排，讲解喙形的进化变化。","pos":[{"tag":"adj.","zh":"进化的；演化的；渐进发展的；进化论的"}],"collocations":[{"phrase":"evolutionary change","zh":"进化上的变化"},{"phrase":"evolutionary biology","zh":"进化生物学"},{"phrase":"an evolutionary advantage","zh":"进化优势"},{"phrase":"evolutionary theory","zh":"进化理论"},{"phrase":"an evolutionary process","zh":"渐进演化的过程"},{"phrase":"evolutionary pressure","zh":"进化选择压力"}],"forms":[{"label":"原级（形容词）","form":"evolutionary"},{"label":"比较级（用 more）","form":"more evolutionary"},{"label":"最高级（用 most）","form":"most evolutionary"},{"label":"副词形式","form":"evolutionarily"}],"derivatives":[{"word":"evolution","pos":"n.","zh":"进化；演化；逐步演变"},{"word":"evolve","pos":"v.","zh":"进化；逐步发展"},{"word":"evolutionist","pos":"n.","zh":"进化论者"},{"word":"evolutionarily","pos":"adv.","zh":"从进化角度看；在演化上"}],"senses":[{"no":"01","title":"Biological evolution","titleCN":"生物进化的：物种一代代改变","definition":"relating to the biological process by which species change over generations","definitionCN":"与物种经过世代发生改变的生物过程有关的","example":"Evolutionary change in beak size followed the arrival of a new seed supply.","exampleCN":"鸟喙大小的进化变化发生在新种子来源出现之后。","why":"The word points to a lineage across generations. A single bird does not evolve; the population does, as inherited traits shift.","whyCN":"这个词指向跨世代的谱系。单只鸟不会进化，进化的是种群，因为可遗传的性状在移动。"},{"no":"02","title":"Gradual development","titleCN":"渐进发展的：制度与观念慢慢展开","definition":"developing gradually through small cumulative steps rather than sudden design","definitionCN":"通过小的累积步骤逐渐发展，而非突然设计出来的","example":"The development of writing was a slow evolutionary process rather than a single invention.","exampleCN":"文字的发展是一个缓慢演进的过程，而不是一次单独的发明。","why":"The same shape is applied outside biology: small changes accumulate until the later form looks unlike the earlier one.","whyCN":"同一个形状被用到生物学之外：小的改变不断累积，直到后来的形态看上去已不像早先的形态。"},{"no":"03","title":"Evolutionary theory","titleCN":"进化论的：解释性状为何存在的框架","definition":"belonging to the explanatory framework of evolutionary theory","definitionCN":"属于进化论解释框架的","example":"An evolutionary explanation asks how a trait improved survival or reproduction.","exampleCN":"进化论的解释会问某个性状如何提高了生存或繁殖。","why":"Here the adjective names a way of explaining, not a thing changing: it asks what selective advantage could account for a feature.","whyCN":"这里的形容词命名的是一种解释方式，而不是正在变化的事物：它问什么样的选择优势能解释某个特征。"},{"no":"04","title":"Evolutionary computation","titleCN":"进化计算的：用变异与选择搜索答案","definition":"relating to algorithms that improve candidate solutions by variation and selection","definitionCN":"与通过变异和选择改进候选解的算法有关的","example":"An evolutionary algorithm improves candidates over many generations.","exampleCN":"进化算法经过许多代改进候选解。","why":"The computer copies the logic of descent with modification: generate variants, keep the better ones, repeat.","whyCN":"计算机复制了‘带修改的传承’这一逻辑：生成变体、保留更好的、重复。"},{"no":"05","title":"Evolutionary psychology","titleCN":"进化心理学的：把行为放回祖先环境","definition":"linking behaviour and mind to selection pressures in ancestral environments","definitionCN":"把行为与心智联系到祖先环境中的选择压力","example":"Evolutionary psychology links behaviour to ancestral selection pressures.","exampleCN":"进化心理学把行为联系到祖先的选择压力。","why":"The adjective marks a cross-disciplinary use: mental traits are treated as adaptations, not as arbitrary cultural habits.","whyCN":"这个形容词标记一种跨学科用法：心理特征被当作适应，而不是任意的文化习惯。"},{"no":"06","title":"Adaptive, stepwise strategy","titleCN":"渐进适应的：每季度小改一点","definition":"proceeding by small adaptive adjustments rather than a single overhaul","definitionCN":"通过小的适应性调整推进，而非一次性大改","example":"The firm took an evolutionary approach, testing small changes each quarter.","exampleCN":"公司采取渐进演化的方式，每季度测试一些小改动。","why":"In management the metaphor is strategic: keep what works, vary what might, and let the market select.","whyCN":"在管理语境里这是一个战略比喻：保留有效的，变化可能有效的，让市场来做选择。"},{"no":"07","title":"Phylogenetic","titleCN":"系统发育的：按亲缘关系画出谱系","definition":"relating to the branching ancestry of groups of organisms","definitionCN":"与生物类群的分支祖先关系有关的","example":"The evolutionary tree places birds within the dinosaur lineage.","exampleCN":"进化树把鸟类放在恐龙谱系之内。","why":"This sense is about the shape of the family tree, not about a single trait's advantage. It names relationships, not pressures.","whyCN":"这个义项关注的是‘家谱的形状’，不是单个性状的优势；它命名关系，而不是压力。"},{"no":"08","title":"Mutual long-term adaptation","titleCN":"共同演化的：双方互为环境","definition":"describing a long-term relationship in which each side adapts to changes in the other","definitionCN":"描述双方都适应对方变化的长期关系","example":"The arms race had an evolutionary character, with each side adapting to the other.","exampleCN":"这场军备竞赛带有演化性质，双方都在适应对方。","why":"Two systems can become each other's selection environment, so change on one side rewrites the pressures on the other.","whyCN":"两个系统可以互为对方的选择环境，因此一方的变化会改写另一方承受的压力。"}],"etymology":{"intro":{"en":"Evolutionary is evolution plus the adjective suffix -ary. The base is Latin evolvere, to roll out or unroll, built from ex- out and volvere to roll.","cn":"evolutionary 是 evolution 加形容词后缀 -ary。词基是拉丁 evolvere‘滚出、展开’，由 ex-‘向外’与 volvere‘滚’构成。"},"items":[{"era":"LATIN volvere","en":"Volvere meant to roll, turn over, or wrap up. It is behind revolve, involve, devolve, and volume, where a scroll is something rolled.","cn":"volvere 意为滚、翻转、卷起。revolve、involve、devolve 与 volume 都来自它，其中 volume 本指卷起来的卷轴。"},{"era":"LATIN evolvere","en":"Ex- out plus volvere roll produced evolvere: to roll out, unroll, and hence to disclose or develop what was folded inside.","cn":"ex-‘向外’加 volvere‘滚’构成 evolvere：滚出来、展开，因而引申为把折叠在里面的东西显露、发展出来。"},{"era":"LATIN evolutio","en":"An unrolling, especially of a book scroll. The noun described a physical act of opening before it described any natural process.","cn":"展开，尤指展开书卷。这个名词先描述物理上的‘打开’，之后才描述自然过程。"},{"era":"ENGLISH 17c","en":"English borrowed evolution in the 17th century for an unfolding or a series of developments. The word still carried the image of a scroll opening.","cn":"英语在 17 世纪借入 evolution，表示‘展开’或‘一连串发展’，仍带着卷轴打开的意象。"},{"era":"ENGLISH 19c","en":"Darwin's work fixed the biological sense: descent with modification through natural selection. The adjective evolutionary followed in the same century.","cn":"达尔文的工作固定了生物学义项：通过自然选择发生的‘带修改的传承’。形容词 evolutionary 也在同一世纪出现。"},{"era":"MODERN ENGLISH","en":"The 20th century extended the adjective to algorithms, psychology, management, and cosmology, wherever small variations are retained or discarded over time.","cn":"20 世纪把这个形容词扩展到算法、心理学、管理与宇宙学：凡是小变异随时间被保留或淘汰的地方都能用。"}]},"similar":{"note":{"en":"The first group shares the evolution stem; the second compares adjectives for change over time, each with a different mechanism and time scale.","cn":"第一组共享 evolution 词干；第二组比较表示‘随时间变化’的形容词，各自机制与时间尺度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"evolution","ipa":"/ɪˈvɒljuːʃn/","tag":"noun","definition":"the process of gradual change, especially in species. It names the process; evolutionary describes what belongs to it.","definitionCN":"逐渐变化的过程，尤指物种进化；它命名过程，evolutionary 则描述‘属于该过程的’。"},{"word":"evolve","ipa":"/ɪˈvɒlv/","tag":"verb","definition":"to change gradually over time. It is the action that produces an evolution.","definitionCN":"随时间逐渐改变；是产生 evolution 的动作。"},{"word":"evolutionist","ipa":"/ɪˌvɒljuːˈʃənɪst/","tag":"person noun","definition":"a person who accepts or studies evolutionary theory. It labels a position, not a process.","definitionCN":"接受或研究进化论的人；标记一种立场，而不是过程。"},{"word":"evolutionarily","ipa":"/ɪˌvɒljuːˈʃənərəli/","tag":"adverb","definition":"from the point of view of evolution. It turns the adjective into a standpoint.","definitionCN":"从进化角度；把形容词变成一种观察立场。"}]},{"heading":"NEAR MEANING","entries":[{"word":"developmental","ipa":"/ˌdiːveləpˈmentl/","tag":"growth over a lifetime","definition":"relating to growth or progress, especially of an individual organism. It usually covers one lifetime, not generations.","definitionCN":"与成长或进展有关的，尤指单个生物体；通常覆盖一生，而不是世代。"},{"word":"gradual","ipa":"/ˈɡreɪdʒuəl/","tag":"slow and stepwise","definition":"happening slowly in small steps. It describes the pace and says nothing about selection or inheritance.","definitionCN":"以小的步骤缓慢发生；描述速度，不涉及选择或遗传。"},{"word":"adaptive","ipa":"/əˈdæptɪv/","tag":"fitted to conditions","definition":"able to adjust to new conditions. It names the result or capacity, while evolutionary names the historical process.","definitionCN":"能适应新条件的；它命名结果或能力，evolutionary 则命名历史过程。"},{"word":"phylogenetic","ipa":"/ˌfaɪlədʒəˈnetɪk/","tag":"lineage relations","definition":"relating to the branching relationships among groups. It is the technical term for one part of evolutionary study.","definitionCN":"与类群之间的分支关系有关的；是进化研究中某一部分的术语。"},{"word":"incremental","ipa":"/ˌɪŋkrəˈmentl/","tag":"small additions","definition":"increasing by small amounts. It counts steps without implying that anything is selected or inherited.","definitionCN":"以小的增量增加；只计算步骤，不暗示被选择或遗传。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out, volvere roll, -ary adjective. The word pictures a scroll being rolled open, one turn at a time.","cn":"只用真实成分：ex-‘向外’、volvere‘滚’、-ary 形容词后缀。这个词画的是卷轴被一圈圈滚开。"},"normal":[{"en":"Ex- out, volvere roll: evolution is the scroll of life unrolling.","cn":"ex- 向外，volvere 滚：evolution 就是生命卷轴慢慢展开。"},{"en":"Revolve, involve, devolve, volume, evolution: one rolling root, many directions.","cn":"revolve、involve、devolve、volume、evolution：同一个‘滚’词根，滚向不同方向。"},{"en":"Darwin's finches: the beak is a small edit that later generations keep.","cn":"达尔文的雀：鸟喙是一处小修改，后来的世代把它保留下来。"},{"en":"An evolutionary tree is a family tree drawn by survival.","cn":"进化树是一棵由‘存活’画出来的家谱。"},{"en":"Evolutionary algorithms breed solutions the way farmers breed plants.","cn":"进化算法培育解，就像农民培育作物。"}],"abstract":[{"en":"Evolution has no target; it is a record of what happened to work in past environments.","cn":"演化没有目标；它只是‘在过去的环境里什么曾奏效’的记录。"},{"en":"Small differences matter only because they are copied; copying is the engine of the metaphor.","cn":"小差异之所以重要，只因为它被复制；复制是这个比喻的发动机。"},{"en":"Every adaptation answers an old question, which is why it can fail in a new world.","cn":"每个适应都在回答一个旧问题，所以它可能在新世界里失效。"}]},"examples":[{"en":"Evolutionary biologists often study island populations because isolation sharpens the signal.","cn":"进化生物学家常研究岛屿种群，因为隔离会让信号更清晰。"},{"en":"The software's evolutionary path is visible in its old menus, which survive as fossils.","cn":"这款软件的演化路径在旧菜单里可见，它们像化石一样保留下来。"},{"en":"An evolutionary perspective cannot tell you what is good; only what has persisted.","cn":"进化视角不能告诉你什么是好的，只能告诉你什么被延续下来了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一窝六人”里有老有小，代代不同——evolutionary 就是一代代演化出来的。","word":"evolutionary"},"root":"源自拉丁 evolvere（ex-‘向外’+ volvere‘滚’，即‘展开’）与 evolutio‘展开’，经英语 evolution 加 -ary 构成；核心是‘卷轴慢慢滚开’的渐进变化。","sensesIntro":{"en":"Eight senses of evolutionary, all built on one shape: something unfolds by small retained differences. Biology supplies the model; theory, computing, psychology, management, and mutual arms races borrow it.","cn":"evolutionary 的八个义项都基于同一个形状：某物通过被保留的小差异慢慢展开。生物学提供模型，理论、计算、心理学、管理与军备竞赛则借用它。"},"semanticMap":{"core":{"en":"CORE IMAGE: a branching tree in which each twig carries a small inherited difference.","cn":"核心意象：一棵分叉的树，每根小枝都带着一处被继承的小差异。"},"chain":["LATIN volvere = TO ROLL","EX- + VOLVERE = TO ROLL OUT, UNROLL","EVOLUTIO = AN UNROLLING","EVOLUTION = GRADUAL UNFOLDING","DESCENT WITH RETAINED MODIFICATION","ANY SYSTEM CHANGING BY SMALL STEPS"],"branches":[{"senses":"01 · 07","en":"THE LIVING LINEAGE: species change across generations, and the family tree records the branching.","cn":"活的谱系：物种跨世代改变，家谱记录分叉。"},{"senses":"02 · 06","en":"THE UNFOLDING PROCESS: institutions and strategies also develop by keeping small successful changes.","cn":"展开的过程：制度与策略也通过保留小的成功改动而发展。"},{"senses":"03 · 05","en":"THE EXPLANATORY LENS: theory and psychology ask what advantage a trait once conferred.","cn":"解释的透镜：理论与心理学追问某个性状曾带来什么优势。"},{"senses":"04","en":"THE COMPUTED ANALOGUE: algorithms imitate variation plus selection.","cn":"计算中的类比：算法模仿变异加选择。"},{"senses":"08","en":"THE MUTUAL LOOP: two systems become each other's selection pressure.","cn":"相互的回路：两个系统成为彼此的选择压力。"}]},"affixes":{"intro":{"en":"Evolutionary is evolution plus -ary, an adjective suffix of Latin origin. The stem itself is ex- plus volvere, so the whole family turns on the image of rolling open.","cn":"evolutionary 是 evolution 加 -ary（拉丁来源的形容词后缀）。词干本身是 ex- 加 volvere，所以整个词族都围绕‘滚开’的意象。"},"latinIntro":{"en":"The real Latin chain is volvere, evolvere, and evolutio. The same volvere also produces revolution, involvement, and volume; none of these is a separate invention.","cn":"真实的拉丁链条是 volvere、evolvere、evolutio。同一个 volvere 还产生 revolution、involvement 与 volume，它们都不是另造的。"},"items":[{"word":"evolution","structure":"e- (out) + volvere (roll) + -tion (action noun)","meaning":"the process of gradual change, especially in species","meaningCN":"逐渐变化的过程，尤指物种进化","example":"Evolution proceeds through variation and selection.","exampleCN":"进化通过变异与选择推进。"},{"word":"evolve","structure":"e- + volvere (verb)","meaning":"to develop gradually","meaningCN":"逐渐发展；演化","example":"The species evolved thicker fur in the cold.","exampleCN":"该物种在寒冷中演化出更厚的毛。"},{"word":"evolutionist","structure":"evolution + -ist (person noun)","meaning":"a supporter or student of evolutionary theory","meaningCN":"进化论者；研究进化的人（-ist 构成人物名词）","example":"The debate pitted an evolutionist against a creationist.","exampleCN":"辩论让一位进化论者与一位神创论者对阵。"},{"word":"evolutionism","structure":"evolution + -ism (doctrine noun)","meaning":"the doctrine that species develop by evolution","meaningCN":"主张物种通过进化发展的学说（-ism 构成主义名词）","example":"Evolutionism was once a controversial label.","exampleCN":"进化主义曾是一个有争议的标签。"},{"word":"evolutionary","structure":"evolution + -ary (relational adjective)","meaning":"relating to evolution","meaningCN":"与进化有关的（-ary 构成关系形容词）","example":"Evolutionary theory explains the distribution of traits.","exampleCN":"进化理论解释性状的分布。"},{"word":"evolutionarily","structure":"evolutionary + -ly (adverb)","meaning":"from an evolutionary point of view","meaningCN":"从进化角度看（-ly 构成副词）","example":"The trait is evolutionarily costly but socially useful.","exampleCN":"这个性状在进化上代价高，却在社交上有用。"},{"word":"revolve","structure":"re- (back, again) + volvere (roll)","meaning":"to turn around a centre","meaningCN":"绕中心旋转（re-‘回、再’+ volvere‘滚’）","example":"The moon revolves around the earth.","exampleCN":"月球绕地球旋转。"},{"word":"involve","structure":"in- (in) + volvere (roll)","meaning":"to include or draw in","meaningCN":"包含；把……卷入（in-‘在内’+ volvere‘滚’）","example":"The job involves frequent travel.","exampleCN":"这份工作涉及频繁出差。"},{"word":"devolve","structure":"de- (down) + volvere (roll)","meaning":"to pass power down, or to worsen","meaningCN":"下放（权力）；恶化（de-‘向下’+ volvere‘滚’）","example":"The agency devolved control to local offices.","exampleCN":"该机构把控制权下放给地方办事处。"},{"word":"volume","structure":"Latin volumen (a rolled scroll) < volvere","meaning":"a book, or the amount of space occupied","meaningCN":"卷册；体积；音量；源自‘卷起的卷轴’","example":"The library holds forty volumes of letters.","exampleCN":"图书馆藏有四十卷书信。"}],"latinEntries":[{"word":"volvere","structure":"Latin verb","meaning":"to roll, turn, or wrap up","meaningCN":"滚；转动；卷起"},{"word":"evolvere","structure":"ex- (out) + volvere (roll)","meaning":"to roll out, unroll, develop","meaningCN":"滚出；展开；发展"},{"word":"evolutio","structure":"evolvere + -io (action noun)","meaning":"an unrolling, a development","meaningCN":"展开；发展"}]}},{"word":"evolution","ipa_uk":"/ɪˈvɒljuːʃn/","ipa_us":"/ɪˈvɑːljuːʃən/","definition_zh":"进化；演化；逐步演变；（天体的）演化；（军事）机动","definition_en":"gradual change over time, especially the biological process by which species develop from earlier forms","core_image":"一卷画轴被慢慢推开：先出现的图案还在，后面又叠上新的图案，整幅画越来越复杂。","scene":"博物馆里，一排马类化石从脚趾多到脚趾少。In the museum a row of horse fossils runs from many toes to few, and the guide calls it the record of evolution.","sceneCN":"这里 evolution 是「生物在世代间的演化」（第 1 个义项：物种经过世代发生变化、由早期形态分化而来）；句意：博物馆里，一排马类化石从多趾到少趾，讲解员称这是演化的记录。","pos":[{"tag":"n.","zh":"进化；演化；逐步演变；（天体）演化；（舞蹈）动作编排；（军事）机动"}],"collocations":[{"phrase":"biological evolution","zh":"生物进化"},{"phrase":"the evolution of language","zh":"语言的演变"},{"phrase":"human evolution","zh":"人类进化"},{"phrase":"evolution by natural selection","zh":"自然选择驱动的进化"},{"phrase":"stellar evolution","zh":"恒星演化"},{"phrase":"a gradual evolution","zh":"逐渐的演变"}],"forms":[{"label":"复数（名词）","form":"evolutions"}],"derivatives":[{"word":"evolve","pos":"v.","zh":"进化；逐步发展"},{"word":"evolutionary","pos":"adj.","zh":"进化的；演化的"},{"word":"evolutionist","pos":"n.","zh":"进化论者"},{"word":"evolutionarily","pos":"adv.","zh":"从进化角度"}],"senses":[{"no":"01","title":"Biological evolution","titleCN":"生物进化：物种从早期形态变来","definition":"the biological process by which species change over generations and diversify from earlier forms","definitionCN":"物种经过世代发生变化、由早期形态分化而来的生物过程","example":"The evolution of the horse can be traced through fossil teeth.","exampleCN":"马的进化可以通过化石牙齿追溯。","why":"The noun names a process measured in generations. One organism does not undergo evolution; a lineage does, as inherited variation is sorted by survival.","whyCN":"这个名词命名的是以‘世代’为单位的过程。单个生物不经历进化，经历进化的是谱系，因为可遗传的变异被生存筛选。"},{"no":"02","title":"Gradual unfolding","titleCN":"逐步演变：事物一点点展开","definition":"the gradual development of something into a more complex or different form","definitionCN":"某物逐渐发展成更复杂或不同的形态","example":"The evolution of the novel took three centuries.","exampleCN":"小说的演变经历了三个世纪。","why":"The word keeps its original image of unrolling: what was folded inside comes out stage by stage, without a designer forcing each step.","whyCN":"这个词保留了‘展开’的原意象：折叠在里面的东西一阶段一阶段地显露，并没有设计者强行推动每一步。"},{"no":"03","title":"The theory of evolution","titleCN":"进化论：解释多样性的一套理论","definition":"the scientific theory explaining the diversity of life through descent with modification","definitionCN":"通过‘带修改的传承’解释生命多样性的科学理论","example":"The theory of evolution predicts that closely related species share traits.","exampleCN":"进化论预测亲缘关系近的物种共享性状。","why":"Here evolution names a body of explanation rather than a process in the world. The theory is the map; the process is the territory.","whyCN":"这里的 evolution 命名的是解释体系，而不是世界中的过程。理论是地图，过程是地形。"},{"no":"04","title":"Stellar evolution","titleCN":"恒星演化：星体一生的阶段变化","definition":"the sequence of stages through which a star passes during its lifetime","definitionCN":"恒星一生所经历的阶段序列","example":"Stellar evolution ends differently for small and massive stars.","exampleCN":"小质量恒星与大质量恒星的演化结局不同。","why":"Astronomy borrowed the biological word for any long, irreversible sequence of internal change. No selection is involved; gravity and nuclear fusion drive it.","whyCN":"天文学借用了生物学词汇，指任何漫长、不可逆的内部变化序列。这里没有选择，驱动者是引力与核聚变。"},{"no":"05","title":"State evolution","titleCN":"状态演化：系统随时间连续变化","definition":"the change of a physical or mathematical system's state over time","definitionCN":"物理或数学系统的状态随时间的变化","example":"The equation describes the evolution of the wave over time.","exampleCN":"该方程描述波随时间的演化。","why":"In physics and mathematics the word becomes technical: a state at one moment determines the state at the next, and the whole path is the evolution.","whyCN":"在物理与数学里这个词变成术语：此刻的状态决定下一刻的状态，整条路径就是 evolution。"},{"no":"06","title":"Product and technology evolution","titleCN":"产品迭代：一代代版本累积改进","definition":"the successive improvement of a product or technology across versions","definitionCN":"产品或技术跨越多个版本逐步改进","example":"The evolution of the phone moved the camera from a novelty to the main feature.","exampleCN":"手机的演变把摄像头从新奇配件变成了主要功能。","why":"Markets act as a selection environment: versions that sell are kept and copied, versions that fail disappear.","whyCN":"市场充当选择环境：卖得好的版本被保留、被复制，失败的版本消失。"},{"no":"07","title":"Military manoeuvre","titleCN":"军事机动：部队按计划变换队形","definition":"a planned movement or series of movements of troops or ships","definitionCN":"部队或舰艇按计划进行的一次或一系列移动","example":"The general ordered an evolution of the fleet to face the enemy.","exampleCN":"将军命令舰队变换队形以面对敌军。","why":"This older military sense is also an unfolding: units rotate through a planned sequence of positions, like a formation opening.","whyCN":"这个较老的军事义项同样是‘展开’：各单位按预定序列轮换位置，就像队形在打开。"},{"no":"08","title":"Choreographic movements","titleCN":"舞蹈动作编排：一组连续的身位变化","definition":"a set of movements performed in sequence, especially in dance or gymnastics","definitionCN":"按顺序完成的一组动作，尤指舞蹈或体操中的","example":"The dancer repeated the same evolution of arms and steps.","exampleCN":"舞者重复了同一组手臂与步伐的动作。","why":"The body also unrolls a sequence: each position follows from the last, and the whole set is called an evolution.","whyCN":"身体也在‘展开’一个序列：每个位置都从前一个位置生出，整组动作就叫 evolution。"}],"etymology":{"intro":{"en":"Evolution is from Latin evolutio, an unrolling, from evolvere to roll out. English used it for any unfolding before Darwin gave it the biological sense.","cn":"evolution 来自拉丁 evolutio‘展开’，源头是 evolvere‘滚出’。在达尔文赋予生物学义项之前，英语用它表示任何‘展开’。"},"items":[{"era":"LATIN volvere","en":"To roll or turn. The root runs through revolve, involve, devolve, and volume, where a rolled scroll is a volumen.","cn":"滚、转。这个词根贯穿 revolve、involve、devolve 与 volume；卷起的卷轴就是 volumen。"},{"era":"LATIN evolvere","en":"Ex- out plus volvere roll: to roll out, unroll, open. It could describe a book scroll opening or a plan being disclosed.","cn":"ex-‘向外’加 volvere‘滚’：滚出、展开、打开。可描述书卷打开，也可描述计划被披露。"},{"era":"LATIN evolutio","en":"The noun meant an unrolling, hence a development or a disclosure. Classical usage was closer to ‘opening’ than to ‘change of species’.","cn":"该名词意为展开，因而指发展或披露。古典用法更接近‘打开’，而不是‘物种改变’。"},{"era":"ENGLISH 17c","en":"English borrowed the word for the unfolding of events, ideas, or literary plots. The metaphor was still visual: something rolled up becomes visible.","cn":"英语借入该词，表示事件、思想或情节的展开。比喻仍是视觉性的：卷起来的东西变得可见。"},{"era":"ENGLISH 19c","en":"Darwin and his readers fixed the modern biological sense. Earlier writers had used evolution for the growth of an embryo, which helped the transfer.","cn":"达尔文及其读者固定了现代生物学义项。更早的作者曾用 evolution 指胚胎发育，这帮助了词义转移。"},{"era":"MODERN ENGLISH","en":"The word then spread to stars, software, institutions, and mathematics. Each field keeps the same skeleton: a sequence of states, each following from the one before.","cn":"这个词随后扩展到恒星、软件、制度与数学。每个领域都保留同一骨架：一串状态，后一个由前一个生出。"}]},"similar":{"note":{"en":"The first group is the evolution word family; the second compares nouns for change, each specifying a different cause and span of time.","cn":"第一组是 evolution 词族；第二组比较表示‘变化’的名词，各自限定不同的原因与时间跨度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"evolutionary","ipa":"/ɪˌvɒljuːˈʃənəri/","tag":"adjective","definition":"relating to evolution. It describes the kind of change, not the change itself.","definitionCN":"与进化有关的；描述变化的类型，而不是变化本身。"},{"word":"evolve","ipa":"/ɪˈvɒlv/","tag":"verb","definition":"to undergo gradual change. It is the act; evolution is the resulting process seen as a whole.","definitionCN":"经历逐渐变化；是动作，evolution 则是被视为整体的过程。"},{"word":"evolutionist","ipa":"/ɪˌvɒljuːˈʃənɪst/","tag":"person noun","definition":"one who accepts or studies the theory of evolution. It is about a person's stance.","definitionCN":"接受或研究进化论的人；关涉个人立场。"},{"word":"evolutions","ipa":"/ɪˌvɒljuːʃənz/","tag":"plural / specialized","definition":"the plural is used for repeated movements or developments, especially in dance and military drill.","definitionCN":"复数形式用于反复的动作或发展，尤见于舞蹈与军事操演。"}]},{"heading":"NEAR MEANING","entries":[{"word":"development","ipa":"/dɪˈveləpmənt/","tag":"general growth","definition":"the process of growing or becoming more advanced. It is broader and can be planned.","definitionCN":"成长或变得更先进的过程；更宽泛，且可以是有计划的。"},{"word":"progression","ipa":"/prəˈɡreʃn/","tag":"ordered sequence","definition":"movement through a series of stages. It stresses order rather than origin or selection.","definitionCN":"经过一系列阶段的推进；强调顺序，而非起源或选择。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"fitted change","definition":"a change that fits an organism or system to its conditions. It is a product of evolution, not the whole process.","definitionCN":"使生物或系统适应条件的改变；是进化的产物，而非全过程。"},{"word":"transformation","ipa":"/ˌtrænsfəˈmeɪʃn/","tag":"change of form","definition":"a complete change in form or nature. It can be sudden, where evolution is gradual.","definitionCN":"形态或性质的彻底改变；可以是突然的，而 evolution 是渐进的。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"lineage","definition":"the line of ancestry from earlier to later forms. It names the path, not the mechanism.","definitionCN":"从早先形态到后来形态的祖先线；命名路径，而非机制。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out plus volvere roll. Evolution is a scroll opening, and every later species is a page further along.","cn":"只用真实成分：ex-‘向外’加 volvere‘滚’。evolution 是卷轴打开，后来的每个物种都是更后面的一页。"},"normal":[{"en":"E- out, volvere roll: evolution is the unrolling of a long scroll.","cn":"e- 向外，volvere 滚：evolution 就是长卷轴慢慢展开。"},{"en":"A fossil row is the scroll read from left to right.","cn":"一排化石就是从左右读过去的卷轴。"},{"en":"A star's evolution is its life story told in stages.","cn":"恒星的 evolution 是用阶段讲述的一生。"},{"en":"Phone versions are evolutions: each keeps what sold and edits what did not.","cn":"手机版本就是 evolution：保留卖得好的，改掉卖不好的。"},{"en":"A dance evolution is a sequence of positions, each opening into the next.","cn":"舞蹈的 evolution 是一串身位，每一个都打开下一个。"}],"abstract":[{"en":"Evolution is history without a plan: the record of what survived, not a ladder toward perfection.","cn":"演化是没有计划的历史：记录的是‘什么活下来了’，而不是通向完美的阶梯。"},{"en":"The word's oldest image is reading, not fighting: an unrolled text of changes.","cn":"这个词最古老的意象是‘阅读’，不是‘战斗’：一部被展开的变化之书。"},{"en":"Any system that copies with error will start to evolve, whether it is made of cells or code.","cn":"任何‘带误差复制’的系统都会开始演化，无论它由细胞还是代码构成。"}]},"examples":[{"en":"The evolution of language leaves traces in the words that neighbouring languages borrow.","cn":"语言的演变留在相邻语言借用的词语里。"},{"en":"Evolution is often slower than the changes it must answer.","cn":"演化常常慢于它必须回应的那些变化。"},{"en":"The engineer spoke of the evolution of the design, not of a single breakthrough.","cn":"工程师谈的是设计的逐步演化，而不是一次单独的突破。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一缕雾，慢慢散”——evolution 读起来像“一缕雾”，雾气一层层展开，像演化。","word":"evolution"},"root":"源自拉丁 evolutio（展开）与 evolvere（ex-‘向外’+ volvere‘滚’），本义是把卷起的东西滚开；核心是‘一阶段一阶段展开’的渐进变化。","sensesIntro":{"en":"Eight senses of evolution, one skeleton: a sequence of states, each following from the one before. Biology, ideas, stars, equations, products, troops, and dance all fill that skeleton with different material.","cn":"evolution 的八个义项共用同一骨架：一串状态，后一个由前一个生出。生物学、思想、恒星、方程、产品、军队与舞蹈只是往骨架里填不同的材料。"},"semanticMap":{"core":{"en":"CORE IMAGE: a scroll unrolling, each panel showing a slightly altered version of the last.","cn":"核心意象：卷轴慢慢展开，每一格都是上一格略有改动的版本。"},"chain":["LATIN VOLVERE = TO ROLL","EVOLVERE = TO ROLL OUT, UNROLL","EVOLUTIO = AN UNROLLING","ENGLISH EVOLUTION = AN UNFOLDING","A SEQUENCE OF DIFFERENT STATES","ANY LONG-RUN GRADUAL CHANGE"],"branches":[{"senses":"01 · 03","en":"LIFE AND ITS THEORY: species change across generations, and the theory explains that change.","cn":"生命及其理论：物种跨世代改变，理论解释这种改变。"},{"senses":"02 · 06","en":"CUMULATIVE UNFOLDING: novels, institutions, and products develop by retained small changes.","cn":"累积展开：小说、制度与产品通过被保留的小改动发展。"},{"senses":"04 · 05","en":"PHYSICAL SEQUENCES: stars and mathematical states follow irreversible stage-by-stage paths.","cn":"物理序列：恒星与数学状态沿着不可逆的分阶段路径变化。"},{"senses":"07","en":"PLANNED MOVEMENT: troops rotate through positions in a prescribed order.","cn":"有计划的移动：部队按预定顺序轮换位置。"},{"senses":"08","en":"BODILY SEQUENCE: dance positions open one into the next.","cn":"身体序列：舞蹈身位一个打开下一个。"}]},"affixes":{"intro":{"en":"Evolution is e- plus volvere plus -tion. The family spreads across Latin-derived verbs (revolve, involve, devolve) and the noun volume.","cn":"evolution 是 e- 加 volvere 加 -tion。词族分布在拉丁来源动词（revolve、involve、devolve）与名词 volume 上。"},"latinIntro":{"en":"The Latin forms are volvere, evolvere, and evolutio. They are all attested; the English noun is a borrowing of the last, not an English invention.","cn":"拉丁形式是 volvere、evolvere、evolutio，均有文献可证。英语名词借自最后一个，并非英语自造。"},"items":[{"word":"evolve","structure":"e- + volvere (verb)","meaning":"to develop gradually","meaningCN":"逐渐发展；演化","example":"The team evolved a simpler protocol.","exampleCN":"团队逐步发展出一套更简单的流程。"},{"word":"evolutionary","structure":"evolution + -ary","meaning":"relating to evolution","meaningCN":"与进化有关的","example":"Evolutionary change is usually measured in generations.","exampleCN":"进化变化通常以世代来衡量。"},{"word":"evolutionist","structure":"evolution + -ist","meaning":"a student or supporter of evolution theory","meaningCN":"进化论研究者或支持者","example":"The museum invited an evolutionist to lecture.","exampleCN":"博物馆邀请了一位进化论者来讲课。"},{"word":"evolutionism","structure":"evolution + -ism","meaning":"the doctrine of evolution","meaningCN":"进化主义；进化论学说","example":"Evolutionism spread through Victorian science writing.","exampleCN":"进化主义通过维多利亚时期的科学写作传播开来。"},{"word":"evolutions","structure":"evolution + -s (plural)","meaning":"repeated movements or developments","meaningCN":"反复的动作或发展（复数）","example":"The drill required precise evolutions of the squadron.","exampleCN":"这次操演要求中队做精确的队形变换。"},{"word":"revolve","structure":"re- + volvere","meaning":"to turn around a centre","meaningCN":"绕中心旋转","example":"The wheel revolved slowly in the sand.","exampleCN":"轮子在沙里缓慢转动。"},{"word":"involve","structure":"in- + volvere","meaning":"to include or entangle","meaningCN":"包含；使卷入","example":"The plan involves three separate agencies.","exampleCN":"该计划涉及三个独立机构。"},{"word":"devolve","structure":"de- + volvere","meaning":"to pass down or deteriorate","meaningCN":"下放；恶化","example":"Authority devolved to the regional councils.","exampleCN":"权力下放给了地区委员会。"},{"word":"volume","structure":"Latin volumen (rolled scroll)","meaning":"a book or the amount of space","meaningCN":"卷册；体积；源自卷轴","example":"The second volume covers the later period.","exampleCN":"第二卷覆盖较晚的时期。"},{"word":"voluble","structure":"volvere (to roll) + -ble","meaning":"speaking easily and at length","meaningCN":"健谈的；滔滔不绝的（本义‘能滚动’）","example":"He was voluble about his plans.","exampleCN":"他对自己的计划滔滔不绝。"}],"latinEntries":[{"word":"volvere","structure":"Latin verb","meaning":"to roll, turn, wrap","meaningCN":"滚；转；卷"},{"word":"evolvere","structure":"ex- + volvere","meaning":"to roll out, unfold","meaningCN":"滚出；展开"},{"word":"evolutio","structure":"evolut- + -io","meaning":"an unrolling, a development","meaningCN":"展开；发展"}]}},{"word":"examination","ipa_uk":"/ɪɡˌzæmɪˈneɪʃn/","ipa_us":"/ɪɡˌzæmɪˈneɪʃən/","definition_zh":"考试；检查；审查；诊察；质证","definition_en":"a formal test of knowledge, or a careful inspection of something","core_image":"天平中央那根指针：一边放砝码，一边放待称的东西，指针偏转就说明重量。","scene":"考场上，学生翻开试卷，计时器开始走动；同一周里，医生也在给另一位病人做检查。In the hall a student opens the paper as the timer starts, and that same week a doctor carries out an examination of another patient.","sceneCN":"这里 examination 同时体现「考试」和「医学检查」两个义项（第 1、3 个义项）；句意：考场里学生翻开试卷、计时器开始走动；同一周里，医生也在给另一位病人做检查。","pos":[{"tag":"n.","zh":"考试；检查；审查；诊察；（法律）质证；检验"}],"collocations":[{"phrase":"sit an examination","zh":"参加考试"},{"phrase":"a medical examination","zh":"体格检查"},{"phrase":"under examination","zh":"正在接受检查／审查"},{"phrase":"cross-examination","zh":"交叉质证"},{"phrase":"a close examination","zh":"仔细检查"},{"phrase":"entrance examination","zh":"入学考试"},{"phrase":"physical examination","zh":"体格检查"}],"forms":[{"label":"复数（名词）","form":"examinations"}],"derivatives":[{"word":"examine","pos":"v.","zh":"检查；审查；考核"},{"word":"examiner","pos":"n.","zh":"考官；审查员"},{"word":"examinee","pos":"n.","zh":"应试者；受检查者"},{"word":"exam","pos":"n.","zh":"考试（examination 的缩略）"}],"senses":[{"no":"01","title":"A formal test","titleCN":"考试：用题目测知识或能力","definition":"a formal test of knowledge or ability, usually written or spoken","definitionCN":"对知识或能力的正式测试，通常为笔试或口试","example":"The final examination covers everything from the first term.","exampleCN":"期末考试覆盖第一学期以来的全部内容。","why":"A test is a weighing: the candidate's knowledge is placed against a fixed standard, and the mark records the difference.","whyCN":"考试就是一次称重：考生的知识被放到固定标准旁，分数记录了两者的差距。"},{"no":"02","title":"Close inspection","titleCN":"仔细检查：把东西看透","definition":"a careful look at something in order to find out its condition or details","definitionCN":"为查明状况或细节而仔细查看某物","example":"A close examination showed a hairline crack in the frame.","exampleCN":"仔细检查发现框架上有一条细裂缝。","why":"The original image is a balance pointer: examination is the act of bringing something under scrutiny so that its hidden weight shows.","whyCN":"原意象是天平的指针：examination 就是把东西放到审视之下，让隐藏的‘重量’显现。"},{"no":"03","title":"Medical examination","titleCN":"医学检查：把身体放到诊断标准下","definition":"a physical or clinical check of a patient's body or health","definitionCN":"对病人身体或健康状况进行的体格或临床检查","example":"The doctor began the examination with the patient's breathing.","exampleCN":"医生从病人的呼吸开始检查。","why":"The body becomes the object weighed against normal signs; the examination looks for what departs from the expected range.","whyCN":"身体成为对照正常体征被称量的对象；检查寻找的是偏离预期范围的部分。"},{"no":"04","title":"Cross-examination","titleCN":"法律质证：用问题检验证词","definition":"the questioning of a witness by the opposing side in a legal case","definitionCN":"法律案件中由对方对证人进行的提问与检验","example":"Cross-examination exposed a contradiction in the witness's account.","exampleCN":"交叉质证暴露了证人陈述中的矛盾。","why":"A witness's story is put on the scale of other evidence; each question tests whether it still balances.","whyCN":"证人的说法被放到其他证据的天平上；每个问题都在检验它是否仍然平衡。"},{"no":"05","title":"Official inquiry","titleCN":"官方审查：对事件与账目立案调查","definition":"a formal investigation by an authority into an event or a set of records","definitionCN":"权威机构对事件或记录进行的正式调查","example":"The committee's examination of the accounts lasted six months.","exampleCN":"委员会对账目的审查持续了六个月。","why":"An authority sets the standard and compels the records to be produced; the examination is the forced comparison.","whyCN":"权威设定标准并强制调取记录；examination 就是这场强制性的对照。"},{"no":"06","title":"Academic scrutiny","titleCN":"学术审查：把论文与证据逐条核对","definition":"the critical review of a scholarly claim, text, or body of evidence","definitionCN":"对学术主张、文本或证据体系进行的批判性审查","example":"The theory did not survive examination by later researchers.","exampleCN":"该理论没能经受后来研究者的审查。","why":"In scholarship the balance is evidence: a claim is examined by asking whether the evidence outweighs the objections.","whyCN":"学术里的天平是证据：审查一个主张，就是问证据是否压过反方意见。"},{"no":"07","title":"Laboratory test","titleCN":"化验：把样本放到仪器里检验","definition":"a laboratory procedure that tests a sample for particular substances or conditions","definitionCN":"在实验室检验样本中特定物质或状况的程序","example":"Examination of the water sample revealed high lead levels.","exampleCN":"对水样的化验显示铅含量偏高。","why":"Here the instrument replaces the human eye; the sample is examined because its contents are not visible without a test.","whyCN":"这里仪器替代了眼睛；样本之所以被检验，是因为不测试就看不见其中的成分。"},{"no":"08","title":"Testing a hypothesis","titleCN":"检验：用证据考验假设","definition":"the process of testing a hypothesis, idea, or method against evidence","definitionCN":"用证据对假设、观点或方法进行检验的过程","example":"The proposal came under examination during the trial.","exampleCN":"该方案在试验期间受到了检验。","why":"An idea is examined by putting it in a situation where it could fail. Passing the examination is not proof, only survival so far.","whyCN":"检验一个想法，就是把它放进可能失败的处境。通过检验不是证明，只是截至目前还活着。"}],"etymology":{"intro":{"en":"Examination comes from Latin examen, the tongue or pointer of a balance, and examinare, to weigh or test. The weighing image is older than the school sense.","cn":"examination 来自拉丁 examen（天平的指针）与 examinare（称量、检验）。‘称重’的意象比‘考试’义更古老。"},"items":[{"era":"LATIN examen","en":"The pointer or tongue of a balance, hence a means of weighing. The word names the instrument that reveals weight, not the weight itself.","cn":"天平的指针或舌，因而指称量的手段。这个词命名的是显示重量的器具，而不是重量本身。"},{"era":"LATIN exigere","en":"To drive out, to demand, to weigh. Many sources connect examen with exigere, but the link is reconstructed rather than directly attested; it is best marked as generally accepted, not certain.","cn":"驱出、索取、称量。许多来源把 examen 与 exigere 联系起来，但这是重构而非直接可证的联系；宜标为“一般认为是”，不是确定结论。"},{"era":"LATIN examinare","en":"To weigh, test, or examine. The verb extends the balance image to any careful assessment of a thing's value or truth.","cn":"称量、检验、审查。该动词把天平意象扩展到对事物价值或真实性的任何仔细评估。"},{"era":"FRENCH examinacion","en":"Old French passed the noun to English. The French form kept both the legal and the scholarly possibilities of the Latin verb.","cn":"古法语把该名词传给英语。法语形式同时保留了拉丁动词的法律与学术两种可能。"},{"era":"ENGLISH 14c","en":"English examination is recorded from the 14th century, first in legal and religious inquiry, then in academic testing.","cn":"英语 examination 自 14 世纪有记录，先用于法律与宗教调查，后用于学业测试。"},{"era":"MODERN ENGLISH","en":"The school examination became fixed in the 19c as public education expanded. Medicine and science kept the older sense of inspecting a body or a sample.","cn":"19 世纪公共教育扩张，学校‘考试’义固定下来；医学与科学则保留更古老的‘检查身体或样本’义。"}]},"similar":{"note":{"en":"The first group is the examine family; the second compares kinds of checking, from a scored test to a broad inquiry.","cn":"第一组是 examine 词族；第二组比较各种‘检查’，从计分考试到广泛调查。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"examine","ipa":"/ɪɡˈzæmɪn/","tag":"verb","definition":"to inspect or test something carefully. It is the action behind examination.","definitionCN":"仔细检查或检验；是 examination 背后的动作。"},{"word":"examiner","ipa":"/ɪɡˈzæmɪnə/","tag":"person noun","definition":"a person who sets or marks an examination, or who inspects something officially.","definitionCN":"出题或评卷的人，或进行官方检查的人。"},{"word":"examinee","ipa":"/ɪɡˌzæmɪˈniː/","tag":"person noun","definition":"a person who is being examined, especially in a test. The suffix -ee marks the receiver.","definitionCN":"接受考试或检查的人；后缀 -ee 标记接受者。"},{"word":"exam","ipa":"/ɪɡˈzæm/","tag":"short form","definition":"the informal short form of examination in the school sense. It is not used for medical inspection.","definitionCN":"学校义项中 examination 的非正式缩略；不用于医学检查。"}]},{"heading":"NEAR MEANING","entries":[{"word":"test","ipa":"/test/","tag":"scored trial","definition":"a procedure that measures ability or quality, often with a score. It is the everyday word for a school examination.","definitionCN":"测量能力或质量的程序，常带分数；是学校考试的日常用词。"},{"word":"inspection","ipa":"/ɪnˈspekʃn/","tag":"looking over","definition":"an official or careful look at something to check its condition. It stresses seeing rather than questioning.","definitionCN":"为核查状况而进行的官方或仔细查看；强调‘看’，而非‘问’。"},{"word":"assessment","ipa":"/əˈsesmənt/","tag":"judgement","definition":"a judgement of quality, ability, or risk. It is broader than a single examination.","definitionCN":"对质量、能力或风险的判断；比单次考试更宽泛。"},{"word":"inquiry","ipa":"/ɪnˈkwaɪəri/","tag":"investigation","definition":"a formal or systematic investigation into a question. It emphasizes seeking facts, not grading.","definitionCN":"对某个问题的正式或系统调查；强调寻找事实，而非评分。"},{"word":"screening","ipa":"/ˈskriːnɪŋ/","tag":"preliminary check","definition":"a quick check to identify cases that need closer attention. It is an examination used as a filter.","definitionCN":"为找出需要进一步关注的对象而做的快速检查；是作为筛选器的 examination。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: Latin examen, the pointer of a balance, plus -ation. The word asks what something weighs when placed against a standard.","cn":"只用真实成分：拉丁 examen‘天平指针’加 -ation。这个词问的是：把某物放到标准旁，它有多重。"},"normal":[{"en":"A balance pointer is the original examination: it shows the hidden weight.","cn":"天平指针就是最初的 examination：它让隐藏的重量显形。"},{"en":"An exam paper is a balance: your answer on one side, the mark scheme on the other.","cn":"试卷就是天平：一边你的答案，一边评分标准。"},{"en":"A doctor's examination puts your body beside normal ranges.","cn":"医生的 examination 把身体放到正常范围旁边。"},{"en":"Cross-examination weighs one story against other evidence.","cn":"交叉质证用其他证据来称量一个说法。"},{"en":"A lab examination reveals what the eye cannot weigh.","cn":"实验室检查揭示眼睛称不出来的东西。"}],"abstract":[{"en":"To examine is to risk an answer, not to confirm one.","cn":"审查是让答案承担风险，而不是确认答案。"},{"en":"Every examination chooses its instrument, and the instrument decides what can be found.","cn":"每次检查都选择自己的仪器，而仪器决定了能发现什么。"},{"en":"A test measures the answer, not the person; the confusion between them is a social fact.","cn":"考试测量的是答案，不是人；把两者混为一谈是一种社会事实。"}]},"examples":[{"en":"The examination was moved online after the snow closed the school.","cn":"大雪停课后，考试改到了线上。"},{"en":"A second examination of the manuscript found a date written in a later hand.","cn":"对抄本的再次检查发现了一个后来补写的日期。"},{"en":"Under examination, the witness admitted he had not seen the car.","cn":"在质证中，证人承认他并没有看见那辆车。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一个贼，没捏住”——考试时想作弊，被老师“捏住”检查：examination 检查、考试。","word":"examination"},"root":"源自拉丁 examen（天平指针）与 examinare（称量、检验），经古法语 examinacion 进入英语；核心是“把对象放到标准上称一称”。","sensesIntro":{"en":"Eight senses of examination, one gesture: place something against a standard and see how it weighs. The standard can be a mark scheme, a normal range, another witness, an authority's rule, a body of evidence, or an instrument.","cn":"examination 的八个义项共用一个动作：把对象放到标准上，看它有多重。标准可以是评分方案、正常范围、另一份证词、权威规则、证据体系或仪器。"},"semanticMap":{"core":{"en":"CORE IMAGE: the pointer of a balance swinging as a weight is placed on one side.","cn":"核心意象：砝码放上一边时，天平指针摆动。"},"chain":["LATIN EXAMEN = BALANCE POINTER","EXAMINARE = TO WEIGH, TEST","EXAMINACION = A WEIGHING, AN INQUIRY","ENGLISH EXAMINATION = INSPECTION","A STANDARD IS APPLIED TO A CASE","ANY FORMAL TESTING, INCLUDING SCHOOL TESTS"],"branches":[{"senses":"01 · 06","en":"TESTING CLAIMS: a school paper and a scholarly thesis are both weighed against a standard.","cn":"检验主张：试卷与学术论文都被放到标准上称量。"},{"senses":"02 · 08","en":"BRINGING TO LIGHT: close inspection and hypothesis testing reveal what was hidden.","cn":"让隐者显形：仔细检查与假设检验都揭示隐藏的东西。"},{"senses":"03 · 07","en":"READING THE BODY OR SAMPLE: the clinic and the laboratory use instruments to weigh what the eye cannot see.","cn":"读取身体或样本：诊所与实验室用仪器称量眼睛看不见的东西。"},{"senses":"04","en":"QUESTIONING A WITNESS: cross-examination weighs one account against other evidence.","cn":"质询证人：交叉质证用一个说法对账其他证据。"},{"senses":"05","en":"INVESTIGATING RECORDS: an authority compels documents into the open for comparison.","cn":"调查记录：权威强制把文件摆出来做对照。"}]},"affixes":{"intro":{"en":"Examination is examin- plus -ation. English also has the verb examine, the person nouns examiner and examinee, and the clipped form exam.","cn":"examination 是 examin- 加 -ation。英语还有动词 examine、人物名词 examiner 与 examinee，以及缩略形式 exam。"},"latinIntro":{"en":"The Latin forms are examen, examinare, and exigere. The connection between examen and exigere is generally accepted but reconstructed, so it should not be presented as certain.","cn":"拉丁形式是 examen、examinare、exigere。examen 与 exigere 的联系被普遍接受，但属于重构，不应说成确定事实。"},"items":[{"word":"examine","structure":"Latin examinare (to weigh, test)","meaning":"to inspect or test carefully","meaningCN":"仔细检查；审查；考核","example":"The panel examined every page of the report.","exampleCN":"专家组审查了报告的每一页。"},{"word":"examination","structure":"examin- + -ation (action noun)","meaning":"a test or careful inspection","meaningCN":"考试；检查；审查","example":"The examination lasted three hours.","exampleCN":"考试持续了三个小时。"},{"word":"examiner","structure":"examine + -er (agent noun)","meaning":"one who examines or marks","meaningCN":"考官；审查员","example":"The examiner checked the seal on each sample.","exampleCN":"审查员检查了每个样本上的封条。"},{"word":"examinee","structure":"examine + -ee (receiver noun)","meaning":"one who is examined","meaningCN":"应试者；受检查者","example":"Each examinee received a numbered desk.","exampleCN":"每位应试者拿到一张编号课桌。"},{"word":"exam","structure":"clipped form of examination","meaning":"a school or academic test","meaningCN":"考试（学校义项的缩略）","example":"She has three exams next week.","exampleCN":"她下周有三场考试。"},{"word":"cross-examine","structure":"cross- + examine (legal verb)","meaning":"to question a witness for the opposing side","meaningCN":"交叉质证；盘问（法律）","example":"The lawyer cross-examined the witness for an hour.","exampleCN":"律师盘问证人一个小时。"},{"word":"cross-examination","structure":"cross-examine + -ation","meaning":"the questioning of a witness by the other side","meaningCN":"交叉质证（名词）","example":"Cross-examination is limited to the scope of direct testimony.","exampleCN":"交叉质证限于直接证词的范围。"},{"word":"exact","structure":"Latin exactus (driven out, demanded) < exigere","meaning":"precise, or to demand and obtain","meaningCN":"精确的；强求；源自 exigere‘驱出、索取’","example":"The exact wording of the clause matters.","exampleCN":"该条款的精确措辞很重要。"},{"word":"exigent","structure":"exigere + -ent (adjective)","meaning":"urgent, demanding immediate action","meaningCN":"紧急的；迫切需要处理的","example":"The exigent circumstances justified a late-night call.","exampleCN":"紧急情况使得深夜致电成为正当。"},{"word":"exigency","structure":"exigent + -cy (state noun)","meaning":"an urgent need or emergency","meaningCN":"紧急情况；迫切需求","example":"The budget was cut in response to a fiscal exigency.","exampleCN":"为应对财政紧急状况，预算被削减。"}],"latinEntries":[{"word":"examen","structure":"Latin noun","meaning":"the tongue or pointer of a balance; a weighing","meaningCN":"天平指针；称量"},{"word":"examinare","structure":"Latin verb","meaning":"to weigh, test, examine","meaningCN":"称量；检验；审查"},{"word":"exigere","structure":"ex- + agere (drive)","meaning":"to drive out, demand, weigh","meaningCN":"驱出；索取；称量（与 examen 的联系属一般认为）"}]}},{"word":"exception","ipa_uk":"/ɪkˈsepʃn/","ipa_us":"/ɪkˈsepʃən/","definition_zh":"例外；例外情况；除外；异议；异常","definition_en":"a person or thing that is not included by a rule, or the act of excluding something from a rule","core_image":"一条画得笔直的规则线，线外单独站着一个小点，旁边插着一面写着‘除此之外’的小旗。","scene":"图书馆规定不许带饮料，但管理员指着门口的水杯架。The library bans drinks, but the librarian points at the cup rack by the door and says plain water is an exception.","sceneCN":"这里 exception 是「规则之外的例外」（第 1 个义项：规则不适用的人或事物）；句意：图书馆禁止带饮料，管理员指着门口的水杯架说清水是例外。","pos":[{"tag":"n.","zh":"例外；例外情况；除外；异议；异常"}],"collocations":[{"phrase":"with the exception of","zh":"除……之外"},{"phrase":"make an exception","zh":"破例"},{"phrase":"a notable exception","zh":"一个显著的例外"},{"phrase":"take exception to","zh":"对……提出异议"},{"phrase":"without exception","zh":"毫无例外"},{"phrase":"a rare exception","zh":"罕见的例外"},{"phrase":"exception handling","zh":"异常处理"}],"forms":[{"label":"复数（名词）","form":"exceptions"}],"derivatives":[{"word":"except","pos":"prep./conj./v.","zh":"除……之外；把……排除"},{"word":"exceptional","pos":"adj.","zh":"例外的；非凡的；异常的"},{"word":"exceptionable","pos":"adj.","zh":"可反对的；令人反感的"},{"word":"unexceptionable","pos":"adj.","zh":"无可指摘的；完全妥当的"}],"senses":[{"no":"01","title":"Something outside the rule","titleCN":"例外：被规则漏掉的那一个","definition":"a person or thing that a rule does not apply to","definitionCN":"规则不适用的人或事物","example":"Everyone must attend, with the exception of those on night duty.","exampleCN":"除值夜班者外，所有人都必须出席。","why":"A rule draws a line. The exception is the point deliberately taken out of that line and placed beyond it.","whyCN":"规则画出一条线；例外就是被有意从线里取出来、放到线外的那个点。"},{"no":"02","title":"An excepting clause","titleCN":"除外条款：合同里写明‘不算’的部分","definition":"a clause or provision that excludes something from a rule or agreement","definitionCN":"把某事物从规则或协议中排除的条款","example":"The contract has an exception for damage caused by storms.","exampleCN":"合同对暴风雨造成的损坏有一项除外条款。","why":"The exception becomes part of the text: the rule is stated, then a piece is explicitly lifted out of it.","whyCN":"例外变成了文本的一部分：先写出规则，再明确把一块从规则里拿出去。"},{"no":"03","title":"Objection","titleCN":"异议：对某说法表示不接受","definition":"an objection or disagreement, especially in the phrase take exception to","definitionCN":"反对或不赞同，尤见于 take exception to 这一说法","example":"She took exception to the way the report described her team.","exampleCN":"她对报告描述她团队的方式提出了异议。","why":"To take exception is to single out a statement and refuse it: the same gesture of lifting one item away from the accepted whole.","whyCN":"take exception 就是把某一句话单独挑出来并拒绝接受：同一个‘把一项从整体里拎出来’的动作。"},{"no":"04","title":"Legal exemption","titleCN":"法律豁免：法律规定可以不适用","definition":"a legal provision that exempts a person or case from a general requirement","definitionCN":"使某人或某情形不受一般要求约束的法律规定","example":"The law grants an exception for religious gatherings.","exampleCN":"法律对宗教集会给予例外。","why":"Statutes are written as general rules; the exception names the case the legislature chose to leave outside.","whyCN":"成文法写成一般规则；例外命名的是立法者选择留在规则之外的情形。"},{"no":"05","title":"Programming exception","titleCN":"程序异常：正常流程之外的事件","definition":"an event in a program that interrupts normal execution and must be handled separately","definitionCN":"程序运行中打断正常执行、必须单独处理的事件","example":"The code catches an exception when the file is missing.","exampleCN":"文件缺失时，代码会捕获一个异常。","why":"A program's normal path is the rule; an exception is the event taken out of that path so that a separate handler can deal with it.","whyCN":"程序的正常路径就是规则；异常是被从路径里取出来的事件，好让单独的处理程序接手。"},{"no":"06","title":"A rare case","titleCN":"特例：罕见但确实存在的一例","definition":"a rare instance that does not follow the usual pattern","definitionCN":"不遵循通常模式的罕见实例","example":"A two-headed snake is an exception, not a new species.","exampleCN":"双头蛇是一个特例，不是一个新物种。","why":"The word can mark frequency rather than rules: the case is unusual enough that the general statement fails to cover it.","whyCN":"这个词也可以标记频率而非规则：这一例足够罕见，以至于一般陈述覆盖不到它。"},{"no":"07","title":"Accounting exclusion","titleCN":"会计除外项：不计入总额的部分","definition":"an item deliberately left out of a total, a policy, or a calculation","definitionCN":"被有意排除在总额、保单或计算之外的项目","example":"The insurance policy lists several exclusions from cover.","exampleCN":"这份保单列了几项不予承保的除外责任。","why":"Accounting and insurance define what counts. An exclusion is the item placed outside the boundary before the sum is made.","whyCN":"会计与保险先定义‘什么算数’；exclusion 是在求和之前就被放到边界之外的项目。"},{"no":"08","title":"Except for","titleCN":"除……之外：整体减去一项","definition":"the state of a whole having one item removed, as in all except","definitionCN":"整体中减去一项的状态，如 all except 结构","example":"The room was empty except for a single chair.","exampleCN":"房间里空空的，只有一把椅子。","why":"This sense is the grammar of subtraction: first imagine the whole, then take one item out and look at what remains.","whyCN":"这个义项是‘减法语法’：先想象整体，再取出一项，看剩下什么。"}],"etymology":{"intro":{"en":"Exception is from Latin exceptio, from excipere, to take out: ex- out plus capere to take. It is literally a thing taken out of a whole.","cn":"exception 来自拉丁 exceptio，源头是 excipere‘取出’：ex-‘向外’加 capere‘拿’。字面就是‘从整体里拿出来的东西’。"},"items":[{"era":"LATIN capere","en":"To take, seize, or capture. It is one of the most productive Latin roots: accept, receive, capture, and concept all contain it.","cn":"拿、抓、捕获。它是最多产的拉丁词根之一：accept、receive、capture、concept 都含它。"},{"era":"LATIN excipere","en":"Ex- out plus capere take: to take out, single out, or make an exception. The verb can also mean to catch a speaker's words, hence the legal questioning sense.","cn":"ex-‘向外’加 capere‘拿’：取出、单独挑出、作例外。该动词还可指‘接住说话人的话’，因而有法律询问义。"},{"era":"LATIN exceptio","en":"A taking out, hence an exception or a legal plea that blocks the general rule. Roman law gave the word a precise procedural sense.","cn":"取出，因而指例外，或指阻断一般规则的法律抗辩。罗马法赋予该词精确的程序意义。"},{"era":"LATIN exemptio","en":"A different noun from eximere (ex- + emere, take out). Exemption and exception split in English: one removes an obligation, the other removes a case from a rule.","cn":"另一个名词，来自 eximere（ex- + emere‘取’）。英语中 exemption 与 exception 分工：前者免除义务，后者把案例移出规则。"},{"era":"ENGLISH 14c","en":"English borrowed exception through French for legal and theological exceptions. The everyday ‘not included’ sense followed.","cn":"英语经法语借入 exception，先用于法律与神学上的例外；日常‘不包括’义随后出现。"},{"era":"MODERN ENGLISH","en":"Computing added exception in the 20c for an event outside normal execution. The old metaphor survived intact: the normal path is the rule, the event is taken out.","cn":"20 世纪计算领域加入‘异常’义，指正常执行之外的事件。旧比喻原封不动：正常路径是规则，事件被取出去。"}]},"similar":{"note":{"en":"The first group shares the exception stem; the second compares words for things left out, each with a different reason for leaving them out.","cn":"第一组共享 exception 词干；第二组比较‘被排除’的词，各自排除的理由不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"except","ipa":"/ɪkˈsept/","tag":"preposition / verb","definition":"not including, or to leave out. It performs the act that creates an exception.","definitionCN":"不包括；把……排除。它执行的是‘制造例外’的动作。"},{"word":"exceptional","ipa":"/ɪkˈsepʃənl/","tag":"adjective","definition":"unusual, or far above average. It describes the quality of the case, not the case itself.","definitionCN":"异常的，或远高于平均的；描述案例的性质，而非案例本身。"},{"word":"exceptionable","ipa":"/ɪkˈsepʃənəbl/","tag":"adjective","definition":"open to objection; likely to be criticized. It is not a synonym of exceptional and is much rarer.","definitionCN":"可反对的；容易招致批评的。它不是 exceptional 的同义词，而且少见得多。"},{"word":"unexceptionable","ipa":"/ˌʌnɪkˈsepʃənəbl/","tag":"negative adjective","definition":"beyond objection; entirely acceptable. Note that it does not mean ‘unexceptional’.","definitionCN":"无可指摘的；完全可接受的。注意它不等于 unexceptional。"}]},{"heading":"NEAR MEANING","entries":[{"word":"exemption","ipa":"/ɪɡˈzempʃn/","tag":"release from duty","definition":"freedom from an obligation others must meet, especially a tax or duty. It removes a burden, not a case.","definitionCN":"免于他人必须承担的义项，尤指税负；它移除的是负担，不是案例。"},{"word":"exclusion","ipa":"/ɪkˈskluːʒn/","tag":"shutting out","definition":"the act of keeping someone or something out. It stresses the boundary and the act of shutting.","definitionCN":"把人或物挡在外面；强调边界与‘关闭’的动作。"},{"word":"anomaly","ipa":"/əˈnɒməli/","tag":"unexplained oddity","definition":"something that does not fit a rule and puzzles observers. It stresses mystery rather than permission.","definitionCN":"不合规则且令人困惑的事物；强调谜团，而非许可。"},{"word":"outlier","ipa":"/ˈaʊtlaɪə/","tag":"statistical case","definition":"a value far from the rest of a data set. It is an exception in measurement, not in law.","definitionCN":"远离数据集其余部分的数值；是测量上的例外，不是法律上的。"},{"word":"special case","ipa":"/ˈspiːʃl keɪs/","tag":"handled separately","definition":"a case that must be treated by its own rule. It is the practical result of an exception.","definitionCN":"必须按自己规则处理的情形；是例外在操作上的结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out plus capere take. An exception is literally a thing taken out of the set.","cn":"只用真实成分：ex-‘向外’加 capere‘拿’。exception 字面上就是‘从集合里拿出来的东西’。"},"normal":[{"en":"Ex- out, capere take: take one item out of the rule and you have an exception.","cn":"ex- 向外，capere 拿：从规则里拿出一个，就得到 exception。"},{"en":"Every rule has a line; the exception is the dot standing outside it.","cn":"每条规则都有一条线；例外就是站在线外的那个点。"},{"en":"Make an exception: open the rule for one person, then close it again.","cn":"make an exception：为一个人打开规则，然后再关上。"},{"en":"Take exception to a remark: pick that one sentence out and refuse it.","cn":"take exception to 一句话：把那一句单独挑出来拒绝。"},{"en":"A code exception is a branch taken out of the normal path.","cn":"代码里的异常，就是从正常路径上分出去的一支。"}],"abstract":[{"en":"A rule is known by what it is willing to exclude.","cn":"一条规则，靠它愿意排除什么来显出自己的样子。"},{"en":"Exceptions do not weaken rules; they reveal where the rule was always drawing a line.","cn":"例外不会削弱规则；它揭示规则一直在哪里画线。"},{"en":"Every exception is a small decision about who or what does not count.","cn":"每个例外都是一次小决定：谁、什么不算数。"}]},"examples":[{"en":"All the paintings were sold except for one small sketch.","cn":"除了一幅小素描，所有画都卖掉了。"},{"en":"The policy makes an exception for emergency repairs.","cn":"该政策对紧急维修作了例外规定。"},{"en":"The exception proved the rule, because it was the only case that fitted the old theory.","cn":"这个例外反而证明了规则，因为它是唯一符合旧理论的情形。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗赛跑”——所有词都在队列里跑，只有“一颗”被叫出去赛跑：exception 例外。","word":"exception"},"root":"源自拉丁 excipere（ex-‘向外’+ capere‘拿’，即‘取出’）与 exceptio；核心是“从整体或规则中单独拿出来的一项”。","sensesIntro":{"en":"Eight senses of exception, one operation: take one item out of a whole. The whole may be a rule, a contract, a statement, a statute, a program path, a species, an insurance cover, or a room.","cn":"exception 的八个义项共用一个操作：从整体里取出一项。整体可以是规则、合同、陈述、法规、程序路径、物种、保单或房间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straight rule-line with one dot deliberately placed outside it.","cn":"核心意象：一条笔直的规则线，一个小点被有意放在线外。"},"chain":["LATIN CAPERE = TO TAKE","EX- + CAPERE = TO TAKE OUT","EXCEPTIO = A THING TAKEN OUT","ENGLISH EXCEPTION = A CASE OUTSIDE THE RULE","AN ITEM REMOVED FROM A SET","ANY DELIBERATE EXCLUSION OR OBJECTION"],"branches":[{"senses":"01 · 06","en":"THE OUTSIDE CASE: a rule-breaker and a rare specimen are both cases the general statement does not cover.","cn":"线外案例：破例者与罕见样本，都是一般陈述覆盖不到的情形。"},{"senses":"02 · 07","en":"THE WRITTEN EXCLUSION: contract clauses and insurance exclusions name items left outside on purpose.","cn":"写明的排除：合同条款与保险除外责任，命名被有意留在外面的项目。"},{"senses":"03","en":"THE REFUSED STATEMENT: taking exception lifts one remark out of the accepted account.","cn":"被拒绝的陈述：提出异议，就是把一句话从被接受的说法里拎出来。"},{"senses":"04 · 08","en":"THE LEGAL OR GRAMMATICAL SUBTRACTION: a statute or an except-phrase removes one case from the whole.","cn":"法律或语法上的减法：法规或 except 短语从整体中移走一个情形。"},{"senses":"05","en":"THE PROGRAM PATH: an exception leaves normal execution for a separate handler.","cn":"程序路径：异常离开正常执行，进入单独的处理程序。"}]},"affixes":{"intro":{"en":"Exception is ex- plus cap- plus -tion. The same capere gives accept, receive, and capture; the near-twin eximere gives exempt and exemption.","cn":"exception 是 ex- 加 cap- 加 -tion。同一个 capere 给出 accept、receive、capture；近亲 eximere 则给出 exempt 与 exemption。"},"latinIntro":{"en":"The real Latin forms are capere, excipere, and exceptio. Exemption belongs to a different verb, eximere, and should not be merged with exception.","cn":"真实拉丁形式是 capere、excipere、exceptio。exemption 属于另一个动词 eximere，不应与 exception 合并。"},"items":[{"word":"except","structure":"ex- + capere (verb/preposition)","meaning":"to leave out; not including","meaningCN":"排除；除……之外","example":"Everyone except the guard left the building.","exampleCN":"除警卫外，所有人都离开了大楼。"},{"word":"exception","structure":"except- + -ion (action noun)","meaning":"a case left outside a rule","meaningCN":"规则之外的例外","example":"The exception was written into the agreement.","exampleCN":"这项例外被写进了协议。"},{"word":"exceptional","structure":"exception + -al (relational adjective)","meaning":"unusual or outstanding","meaningCN":"异常的；杰出的","example":"Her exceptional memory helped her pass the exam.","exampleCN":"她非凡的记忆力帮她通过了考试。"},{"word":"exceptionable","structure":"exception + -able (capable adjective)","meaning":"open to objection","meaningCN":"可反对的；易招批评的","example":"The wording was exceptionable to several members.","exampleCN":"这个措辞让几位成员觉得可以反对。"},{"word":"unexceptionable","structure":"un- + exceptionable","meaning":"beyond objection","meaningCN":"无可指摘的；完全妥当的","example":"The referee's conduct was unexceptionable.","exampleCN":"裁判的行为无可指摘。"},{"word":"exempt","structure":"ex- + emere (take) → eximere (take out)","meaning":"freed from a duty or rule","meaningCN":"被免除义务的（来自 eximere，与 exception 不同动词）","example":"Small charities are exempt from the fee.","exampleCN":"小型慈善机构免缴该费用。"},{"word":"exemption","structure":"exempt + -ion","meaning":"release from an obligation","meaningCN":"豁免；免除义务","example":"He claimed a tax exemption for dependants.","exampleCN":"他为受养人申请了税收豁免。"},{"word":"accept","structure":"ad- (to) + capere (take)","meaning":"to receive willingly","meaningCN":"接受；收下（ad-‘朝向’+ capere‘拿’）","example":"She accepted the offer after a day's thought.","exampleCN":"她考虑了一天后接受了这个提议。"},{"word":"receive","structure":"re- (back) + capere (take)","meaning":"to take into one's hands or possession","meaningCN":"收到；接收（re-‘回’+ capere‘拿’）","example":"He received the package at the front desk.","exampleCN":"他在前台收到了包裹。"},{"word":"capture","structure":"capt- + -ure (noun/verb)","meaning":"to seize or take control of","meaningCN":"捕获；夺取","example":"The camera captured the moment of impact.","exampleCN":"相机捕捉到了撞击的瞬间。"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize, capture","meaningCN":"拿；抓；捕获"},{"word":"excipere","structure":"ex- + capere","meaning":"to take out, single out, except","meaningCN":"取出；单独挑出；作例外"},{"word":"exceptio","structure":"except- + -io (action noun)","meaning":"a taking out; an exception or legal plea","meaningCN":"取出；例外；法律抗辩"}]}},{"word":"exceptional","ipa_uk":"/ɪkˈsepʃənl/","ipa_us":"/ɪkˈsepʃənl/","definition_zh":"杰出的；非凡的；异常的；例外的","definition_en":"unusually good, or unusually different from the normal case","core_image":"一排同样高的树里，有一棵高出许多，树梢几乎碰到云。","scene":"音乐老师听完所有学生的演奏。After hearing every student play, the music teacher says only that this child's pitch is exceptional.","sceneCN":"这里 exceptional 是「远高于一般水平的、杰出的」（第 1 个义项：异常优秀或令人印象深刻）；句意：听完所有学生演奏后，音乐老师只说这个孩子的音准极为出色。","pos":[{"tag":"adj.","zh":"杰出的；非凡的；异常的；例外的；特殊教育的"}],"collocations":[{"phrase":"exceptional ability","zh":"非凡的能力"},{"phrase":"exceptional circumstances","zh":"特殊情况"},{"phrase":"an exceptional student","zh":"特别出色的学生"},{"phrase":"exceptional quality","zh":"卓越的品质"},{"phrase":"exceptional cases","zh":"例外情形"},{"phrase":"exceptional weather","zh":"异常天气"}],"forms":[{"label":"原级（形容词）","form":"exceptional"},{"label":"比较级（用 more）","form":"more exceptional"},{"label":"最高级（用 most）","form":"most exceptional"},{"label":"副词形式","form":"exceptionally"}],"derivatives":[{"word":"exception","pos":"n.","zh":"例外；除外"},{"word":"exceptionally","pos":"adv.","zh":"极其；非凡地；例外地"},{"word":"exceptionality","pos":"n.","zh":"特殊性；超常性"},{"word":"exceptionalism","pos":"n.","zh":"例外论；独特论"}],"senses":[{"no":"01","title":"Far above average","titleCN":"杰出的：远高于一般水平","definition":"unusually good or impressive, far above the average","definitionCN":"异常优秀或令人印象深刻，远高于平均水平","example":"She has an exceptional ear for harmony.","exampleCN":"她对和声有非凡的听觉。","why":"Exceptional starts from exception: the person is lifted out of the ordinary row. The direction of the lift here is upward.","whyCN":"exceptional 从‘例外’出发：这个人被从普通的一排里拎出来；这里的拎出方向是向上。"},{"no":"02","title":"Unusual or rare","titleCN":"异常的：不常发生，因而显眼","definition":"unusual and therefore notable, without necessarily being good","definitionCN":"不寻常因而值得注意，不一定含褒义","example":"The storm was exceptional for its early date.","exampleCN":"这场风暴因来得太早而异常。","why":"Here the lift is sideways: the case simply does not sit in the usual distribution, and the judgement is neutral.","whyCN":"这里的拎出是横向的：这一例干脆不在通常分布里，判断是中性的。"},{"no":"03","title":"Forming an exception","titleCN":"例外的：规则管不到的","definition":"forming an exception to a rule or general statement","definitionCN":"构成规则或一般陈述之外的特殊情形","example":"This is an exceptional case that the policy did not foresee.","exampleCN":"这是政策没有预见到的例外情形。","why":"This is the literal legal sense: the adjective describes a case that has been taken out of the rule's scope.","whyCN":"这是字面上的法律义：形容词描述一个被移出规则适用范围的情形。"},{"no":"04","title":"Outstanding student","titleCN":"特别出色的学生：天赋或成绩超常","definition":"describing a pupil or student whose ability is far above the expected level","definitionCN":"形容能力远高于预期水平的学生","example":"The school created a programme for exceptional learners.","exampleCN":"学校为超常学习者设立了一个项目。","why":"Education uses the word as a neutral technical label for children at the far end of a distribution, whether that end is high or low.","whyCN":"教育领域把这个词当作中性技术标签，指分布两端的孩子，既可以是高端，也可以是低端。"},{"no":"05","title":"Exceptional size or degree","titleCN":"超常的：尺寸或强度超出常规","definition":"much larger, stronger, or more intense than is normal","definitionCN":"比正常情况大得多、强得多或强烈得多","example":"The bridge was built to withstand exceptional loads.","exampleCN":"这座桥按承受超常荷载来建造。","why":"Engineering uses the word for values beyond the design range: the structure is designed for the ordinary and then checked for the exception.","whyCN":"工程上用这个词指超出设计范围的数值：结构先按常规设计，再针对例外情形校核。"},{"no":"06","title":"Extraordinarily good quality","titleCN":"卓越的：质量好到少见","definition":"of extraordinarily high quality","definitionCN":"质量高到少见的","example":"The wine was exceptional, even for that famous vineyard.","exampleCN":"这款酒即使对那个著名酒庄而言也属卓越。","why":"The word praises by placing the object outside its class: it is not merely a good wine, it is a wine that leaves the category.","whyCN":"这个词通过把对象放到同类之外来赞美：它不只是好酒，而是离开了‘好酒’这一类别。"},{"no":"07","title":"Special needs","titleCN":"特殊教育的：需要额外支持的孩子","definition":"in education, describing children who need special support because of disability or high ability","definitionCN":"教育中形容因残障或超常能力而需要额外支持的孩子","example":"Funding was increased for exceptional children in the district.","exampleCN":"该学区增加了对特殊需求儿童的拨款。","why":"The euphemistic use keeps the logic of exception: these children fall outside the standard classroom design and need a separate arrangement.","whyCN":"这个委婉用法保留例外逻辑：这些孩子落在标准课堂设计之外，需要单独安排。"},{"no":"08","title":"Exceptionally allowed","titleCN":"破例允许的：作为特殊情况被批准","definition":"allowed only as a special case, contrary to the usual practice","definitionCN":"仅作为特殊情况、违背通常做法而被允许","example":"The committee granted exceptional permission to use the hall.","exampleCN":"委员会破例批准使用礼堂。","why":"Here the adjective modifies the permission itself: the rule stays in place, but one case is allowed to step outside it.","whyCN":"这里形容词修饰的是‘许可’本身：规则仍然有效，但有一个情形被允许跨到线外。"}],"etymology":{"intro":{"en":"Exceptional is exception plus -al. It first meant ‘forming an exception’; the sense ‘unusually good’ is a later 19c development.","cn":"exceptional 是 exception 加 -al。它最初意为“构成例外的”；“异常优秀”义是 19 世纪较晚的发展。"},"items":[{"era":"LATIN excipere","en":"To take out, from ex- out and capere take. The participle exceptus supplies the stem seen in exception and exceptional.","cn":"取出，来自 ex-‘向外’与 capere‘拿’。分词 exceptus 提供了 exception 与 exceptional 中可见的词干。"},{"era":"LATIN exceptio","en":"A taking out, an exception. The noun entered English through French and kept a legal flavour for centuries.","cn":"取出、例外。该名词经法语进入英语，数百年间都带法律色彩。"},{"era":"ENGLISH 17c","en":"Exceptional is recorded in the 17th century meaning ‘of the nature of an exception’. It described cases and conditions, not people's talents.","cn":"exceptional 在 17 世纪有记录，意为‘属于例外性质的’。它描述情形与条件，不描述人的才能。"},{"era":"ENGLISH 18c","en":"The sense ‘unusual, uncommon’ developed next. Anything rare enough to leave the ordinary class could be called exceptional.","cn":"接着发展出‘不寻常、罕见’义。任何罕见得足以离开普通类别的东西，都可称为 exceptional。"},{"era":"ENGLISH 19c","en":"The positive sense ‘excellently unusual’ is recorded in the early 19c. Praise borrowed the logic of rarity: good beyond the normal range.","cn":"正面义‘异常优秀’在 19 世纪早期有记录。赞美借用了‘稀有’的逻辑：好到超出正常范围。"},{"era":"MODERN ENGLISH","en":"Special education fixed exceptional as a technical label in the 20c. Engineering and law kept the neutral ‘outside the normal range’ sense.","cn":"20 世纪特殊教育把 exceptional 固定为技术标签；工程与法律则保留中性的‘超出正常范围’义。"}]},"similar":{"note":{"en":"The first group shares the exception stem and includes two words that are often confused; the second compares adjectives of high quality or rarity.","cn":"第一组共享 exception 词干，并包含两个常被混淆的词；第二组比较表示‘高品质或罕见’的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"exception","ipa":"/ɪkˈsepʃn/","tag":"noun","definition":"a case outside a rule. Exceptional is the adjective describing such a case or a quality beyond the norm.","definitionCN":"规则之外的案例；exceptional 是描述这类案例或超常性质的形容词。"},{"word":"exceptionable","ipa":"/ɪkˈsepʃənəbl/","tag":"negative adjective","definition":"open to objection; blameworthy. It is not a stronger form of exceptional and carries disapproval.","definitionCN":"可反对的；该受批评的。它不是 exceptional 的比较级，而带不赞同意味。"},{"word":"unexceptionable","ipa":"/ˌʌnɪkˈsepʃənəbl/","tag":"negative adjective","definition":"beyond objection; entirely proper. It is the opposite of exceptionable, not of exceptional.","definitionCN":"无可指摘的；完全妥当的。它是 exceptionable 的反义，不是 exceptional 的反义。"},{"word":"exceptionally","ipa":"/ɪkˈsepʃənəli/","tag":"adverb","definition":"to an unusual degree. It often means ‘extremely’ rather than ‘as an exception’.","definitionCN":"达到不寻常的程度；常表示‘极其’，而非‘作为例外地’。"}]},{"heading":"NEAR MEANING","entries":[{"word":"outstanding","ipa":"/aʊtˈstændɪŋ/","tag":"excellent","definition":"exceptionally good, standing out from others. It is warmer and more evaluative than exceptional.","definitionCN":"杰出、从众人中站出来的；比 exceptional 更温暖、更具评价性。"},{"word":"extraordinary","ipa":"/ɪkˈstrɔːdnri/","tag":"beyond the ordinary","definition":"very unusual or remarkable. It stresses departure from the ordinary order rather than from a rule.","definitionCN":"非常不寻常或非凡；强调离开‘寻常秩序’，而非离开某条规则。"},{"word":"unusual","ipa":"/ʌnˈjuːʒuəl/","tag":"not common","definition":"not happening often. It is neutral and can describe bad as easily as good.","definitionCN":"不常发生的；中性，可描述坏也可描述好。"},{"word":"rare","ipa":"/reə/","tag":"seldom found","definition":"existing in small numbers or occurring seldom. It is about frequency, not quality.","definitionCN":"数量少或很少发生；讲频率，不讲质量。"},{"word":"anomalous","ipa":"/əˈnɒmələs/","tag":"irregular","definition":"deviating from what is standard or expected. It sounds technical and often implies a problem.","definitionCN":"偏离标准或预期的；听起来技术化，常暗示有问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: exception plus -al. The person or thing is lifted out of the ordinary row, either upward or sideways.","cn":"只用真实成分：exception 加 -al。人或物被从普通的一排里拎出来，方向可上可侧。"},"normal":[{"en":"Exception plus -al: exceptional means standing outside the ordinary row.","cn":"exception 加 -al：exceptional 就是站在普通队列之外。"},{"en":"The tallest tree in a row is exceptional without breaking any rule.","cn":"一排树里最高的那棵，不违反任何规则，却就是 exceptional。"},{"en":"Exceptional weather is not good weather; it is weather outside the normal range.","cn":"exceptional 天气不是好天气，而是正常范围之外的天气。"},{"en":"An exceptional student is one the standard lesson plan cannot fully hold.","cn":"exceptional 学生，是标准教案装不下的那个学生。"},{"en":"Exceptional permission keeps the rule and opens one door.","cn":"破例许可保留规则，只打开一扇门。"}],"abstract":[{"en":"Every scale creates exceptions at both ends; the word does not decide which end is good.","cn":"每个量表都在两端制造例外；这个词本身不决定哪一端是好的。"},{"en":"Praise and abnormality use the same grammar: outside the normal class.","cn":"赞美与异常用的是同一套语法：在正常类别之外。"},{"en":"What a society calls exceptional is a map of what it expects.","cn":"一个社会称为 exceptional 的东西，就是它期待的分布图。"}]},"examples":[{"en":"The orchestra gave an exceptional performance despite the broken string.","cn":"尽管琴弦断了，乐团仍奉献了一场非凡的演出。"},{"en":"The judge allowed the evidence only under exceptional circumstances.","cn":"法官仅在特殊情况下才允许采纳该证据。"},{"en":"An exceptional year for rainfall left the reservoirs full.","cn":"降雨异常充沛的一年让水库蓄满了水。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗赛破神”——一颗棋子破了神的常规，成了例外：exceptional 异常的、非凡的。","word":"exceptional"},"root":"由 exception 加 -al 构成，源头是拉丁 excipere（ex-‘向外’+ capere‘拿’）；本义为“属于例外性质的”，后引申出“罕见、异常优秀”。","sensesIntro":{"en":"Eight senses of exceptional, one move: lift a case out of the ordinary row. Upward lift gives ‘outstanding’, sideways lift gives ‘unusual’, legal lift gives ‘excepted’, and the classroom lift gives ‘special needs’.","cn":"exceptional 的八个义项共用一个动作：把一个情形从普通队列里拎出来。向上拎是‘杰出’，横向拎是‘异常’，法律拎是‘除外’，课堂拎是‘特殊需求’。"},"semanticMap":{"core":{"en":"CORE IMAGE: one tree in a row that rises far above the others.","cn":"核心意象：一排树中有一棵远远高出其他树。"},"chain":["LATIN CAPERE = TO TAKE","EXCIPERE = TO TAKE OUT","EXCEPTIO = AN EXCEPTION","EXCEPTIONAL = OF THE NATURE OF AN EXCEPTION","ANYTHING OUTSIDE THE NORMAL RANGE","HIGHLY UNUSUAL, OFTEN HIGHLY GOOD"],"branches":[{"senses":"01 · 06","en":"THE UPWARD LIFT: outstanding ability and exceptional quality leave the ordinary class from above.","cn":"向上的拎出：非凡能力与卓越品质从上方离开普通类别。"},{"senses":"02 · 08","en":"THE SIDEWAYS LIFT: rare weather and special permission simply sit outside the usual distribution.","cn":"横向的拎出：异常天气与特殊许可只是位于通常分布之外。"},{"senses":"03","en":"THE LEGAL LIFT: a case is formally removed from a rule's scope.","cn":"法律上的拎出：情形被正式移出规则范围。"},{"senses":"04 · 07","en":"THE EDUCATIONAL LIFT: pupils beyond the standard design, at either end, need a separate arrangement.","cn":"教育上的拎出：超出标准设计的学童，无论高低端，都需要单独安排。"},{"senses":"05","en":"THE ENGINEERING LIFT: loads beyond the design range are checked separately.","cn":"工程上的拎出：超出设计范围的荷载被单独校核。"}]},"affixes":{"intro":{"en":"Exceptional is exception plus the relational suffix -al. The adverb exceptionally often weakens into ‘extremely’, a sign of how far the word has travelled from law.","cn":"exceptional 是 exception 加关系后缀 -al。副词 exceptionally 常弱化为‘极其’，这说明该词离开法律有多远。"},"latinIntro":{"en":"The Latin base is capere, with the compound excipere and the noun exceptio. The same family yields accept, receive, and capture.","cn":"拉丁词基是 capere，复合动词 excipere，名词 exceptio。同一词族还产生 accept、receive、capture。"},"items":[{"word":"exception","structure":"excipere + -io (action noun)","meaning":"a case outside a rule","meaningCN":"规则之外的例外","example":"The rule has one exception.","exampleCN":"这条规则有一个例外。"},{"word":"exceptional","structure":"exception + -al (relational adjective)","meaning":"unusual or outstanding","meaningCN":"异常的；杰出的","example":"The result was exceptional for its consistency.","exampleCN":"这个结果因一致性而异常出色。"},{"word":"exceptionally","structure":"exceptional + -ly (adverb)","meaning":"to an unusual degree","meaningCN":"异常地；极其","example":"The winter was exceptionally mild.","exampleCN":"这个冬天异常温和。"},{"word":"exceptionality","structure":"exceptional + -ity (quality noun)","meaning":"the state of being exceptional","meaningCN":"特殊性；超常状态","example":"The study examined exceptionality in early readers.","exampleCN":"该研究考察早期阅读者的超常现象。"},{"word":"exceptionalism","structure":"exceptional + -ism (doctrine noun)","meaning":"the belief that a group is uniquely exempt from common rules","meaningCN":"例外论；认为某群体独特而不受共同规则约束的信念","example":"The speech appealed to a sense of national exceptionalism.","exampleCN":"演讲诉诸一种民族例外论情感。"},{"word":"except","structure":"ex- + capere (verb/preposition)","meaning":"to leave out; not including","meaningCN":"排除；除……之外","example":"No one except the porter was allowed in.","exampleCN":"除搬运工外，任何人都不许进入。"},{"word":"exceptionable","structure":"exception + -able","meaning":"open to objection","meaningCN":"可反对的","example":"The remark was exceptionable and was withdrawn.","exampleCN":"那句话可遭反对，因而被撤回。"},{"word":"unexceptionable","structure":"un- + exceptionable","meaning":"beyond objection","meaningCN":"无可指摘的","example":"Her references were unexceptionable.","exampleCN":"她的推荐信无可指摘。"},{"word":"accept","structure":"ad- + capere","meaning":"to take willingly","meaningCN":"接受","example":"He accepted the terms without complaint.","exampleCN":"他毫无怨言地接受了条件。"},{"word":"capture","structure":"capt- + -ure","meaning":"to seize or record","meaningCN":"捕获；记录","example":"The sensor captured a faint signal.","exampleCN":"传感器捕捉到一个微弱信号。"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize","meaningCN":"拿；抓"},{"word":"excipere","structure":"ex- + capere","meaning":"to take out, except","meaningCN":"取出；排除"},{"word":"exceptio","structure":"except- + -io","meaning":"an exception","meaningCN":"例外"}]}},{"word":"exclusion","ipa_uk":"/ɪkˈskluːʒn/","ipa_us":"/ɪkˈskluːʒən/","definition_zh":"排除；排斥；除外；被排除的状态；社会排斥","definition_en":"the act of keeping someone or something out, or the state of being kept out","core_image":"一扇门在某人面前合上，门内是灯光和人群，门外只剩走廊。","scene":"实验室门口贴着「仅限授权人员」，新来的实习生被挡在门外。A sign on the lab door reads authorised staff only, and the new intern stands outside: that is exclusion.","sceneCN":"这里 exclusion 是「被排除在外、不得进入」（第 1、2 个义项）；句意：实验室门口贴着仅限授权人员，新来的实习生被挡在门外，这就是被排除在外。","pos":[{"tag":"n.","zh":"排除；排斥；除外；被排除状态；（生态）竞争排斥"}],"collocations":[{"phrase":"social exclusion","zh":"社会排斥"},{"phrase":"the exclusion of evidence","zh":"对证据的排除"},{"phrase":"to the exclusion of","zh":"以至于排除掉……"},{"phrase":"an exclusion clause","zh":"除外条款"},{"phrase":"competitive exclusion","zh":"竞争排斥"},{"phrase":"exclusion from school","zh":"被学校停学／开除"}],"forms":[{"label":"复数（名词）","form":"exclusions"}],"derivatives":[{"word":"exclude","pos":"v.","zh":"排除；把……挡在外"},{"word":"exclusive","pos":"adj.","zh":"排他的；独有的；高档的"},{"word":"exclusively","pos":"adv.","zh":"专门地；唯独地"},{"word":"exclusionary","pos":"adj.","zh":"排他性的；造成排斥的"}],"senses":[{"no":"01","title":"Shutting someone out","titleCN":"排除：把某人挡在门外","definition":"the act of preventing a person or thing from entering or taking part","definitionCN":"阻止人或物进入或参与的行为","example":"The exclusion of non-members from the vote caused an outcry.","exampleCN":"把非会员排除在投票之外引发了抗议。","why":"The Latin verb means to shut the door. Exclusion is that closing seen as an act: the boundary is drawn by whoever holds the door.","whyCN":"拉丁动词意为‘关上门’。exclusion 就是这次关门被视为一个动作：边界由掌着门的人画出。"},{"no":"02","title":"The state of being left out","titleCN":"被排除的状态：人在门外的那一侧","definition":"the condition of being left outside a group, place, or activity","definitionCN":"被留在群体、场所或活动之外的状态","example":"Her exclusion from the committee lasted two years.","exampleCN":"她被排除在委员会之外长达两年。","why":"The same event can be told from the door's other side. Here the noun names the experience of the one who remains outside.","whyCN":"同一件事可以从门的另一侧讲述。这里的名词命名的是留在门外那个人的经历。"},{"no":"03","title":"Exclusion clause","titleCN":"除外条款：合同里预先排除的责任","definition":"a contractual or insurance clause that removes a risk or item from cover","definitionCN":"把某项风险或项目排除在保障之外的合同或保险条款","example":"The policy's exclusion for flood damage was printed in bold.","exampleCN":"保单对洪水损害的除外责任用粗体印出。","why":"Contracts define the protected space first, then list what is shut out of it. The clause is the door drawn on paper.","whyCN":"合同先划定受保护的空间，再列出被关在门外的项目。条款就是画在纸上的那扇门。"},{"no":"04","title":"Social exclusion","titleCN":"社会排斥：被挡在正常生活之外","definition":"the process by which groups are pushed to the margins of society and denied normal participation","definitionCN":"某些群体被推到社会边缘、无法正常参与的过程","example":"Poor transport links deepen the social exclusion of rural families.","exampleCN":"交通不便加深了农村家庭的社会排斥。","why":"Here the door is not one building but a whole set of institutions: work, school, housing, and health. Exclusion becomes structural rather than personal.","whyCN":"这里的门不是一栋楼，而是一整套制度：工作、学校、住房与医疗。排斥由此变成结构性的，而非个人性的。"},{"no":"05","title":"Competitive exclusion","titleCN":"竞争排斥：两个物种不能长期占同一生态位","definition":"the ecological principle that two species competing for the same resource cannot coexist indefinitely","definitionCN":"两个物种争夺同一资源时无法无限期共存的生态学原理","example":"Competitive exclusion drove the native species from the pond.","exampleCN":"竞争排斥把本地物种逐出了池塘。","why":"One species uses the shared resource slightly better, so the other is gradually shut out of its own niche. The door here is closed by competition, not policy.","whyCN":"一个物种对共享资源的利用略好，另一个就被逐渐关在自己的生态位之外。这里的门由竞争关上，而非政策。"},{"no":"06","title":"Tax exclusion","titleCN":"不计入项：税法里不纳入收入的部分","definition":"an item of income that is not counted for tax purposes","definitionCN":"在计税时不计入收入的项目","example":"The tax exclusion for employer health cover reduced the bill.","exampleCN":"雇主医保的免税待遇降低了税单。","why":"The tax base is a defined set. An exclusion removes one item before the rate is applied, so the item never enters the calculation.","whyCN":"税基是一个被定义的集合。exclusion 在套用税率前移走一项，因此该项从未进入计算。"},{"no":"07","title":"Expulsion from an institution","titleCN":"逐出：被学校或组织开除","definition":"the removal of a person from a school, club, or organization as a punishment","definitionCN":"作为惩罚把某人从学校、俱乐部或组织中除名","example":"The exclusion was reduced to a suspension on appeal.","exampleCN":"经上诉，开除处分被减为停学。","why":"An institution controls its own door. Expulsion is exclusion made punitive: the person is not merely outside but formally put outside.","whyCN":"机构控制自己的门。开除是带惩罚性的 exclusion：当事人不仅在门外，而且是被正式放到门外。"},{"no":"08","title":"Exclusivity","titleCN":"排他性：只让一部分人进入的安排","definition":"the quality of an arrangement that admits only a limited set of people","definitionCN":"只接纳有限人群的安排所具有的性质","example":"The club's exclusion was part of its appeal.","exampleCN":"这家俱乐部的排他性正是其吸引力的一部分。","why":"Here exclusion is valued rather than resented: the closed door itself becomes the product, because being inside signals membership.","whyCN":"这里的排斥被珍视而非怨恨：关着的门本身成了产品，因为‘在里面’标志着 membership。"}],"etymology":{"intro":{"en":"Exclusion is from Latin exclusio, from excludere, to shut out: ex- out plus claudere to shut. The same claudere runs through include, conclude, and clause.","cn":"exclusion 来自拉丁 exclusio，源头是 excludere‘关在外面’：ex-‘向外’加 claudere‘关’。同一个 claudere 贯穿 include、conclude 与 clause。"},"items":[{"era":"LATIN claudere","en":"To shut, close, or enclose. It gives English close, clause, cloister, and the -clude verbs. The root image is a door or a barrier.","cn":"关、闭、围住。它给出英语 close、clause、cloister 以及 -clude 系列动词。词根意象是门或障碍。"},{"era":"LATIN excludere","en":"Ex- out plus claudere shut: to shut out, exclude, or cut off. The verb assumes an inside that is being protected.","cn":"ex-‘向外’加 claudere‘关’：关在外面、排除、切断。该动词预设了一个被保护的‘里面’。"},{"era":"LATIN exclusio","en":"A shutting out. In rhetoric it could also mean omission or rejection of a possibility; in law, a bar to entry.","cn":"关在外面。在修辞学里也可指省略或排除某种可能；在法律里指禁止进入。"},{"era":"FRENCH exclusion","en":"French passed the noun to English. The legal sense of a bar or an exception travelled with it.","cn":"法语把名词传给英语，禁止进入或除外条款的法律义随之而来。"},{"era":"ENGLISH 15c","en":"English exclusion is recorded in the 15c. Early uses were legal and institutional: exclusion from office, from a court, from a will.","cn":"英语 exclusion 在 15 世纪有记录。早期用法是法律与制度性的：排除公职、排除法庭、排除继承。"},{"era":"MODERN ENGLISH","en":"The 20c added social exclusion and competitive exclusion, extending the closed door from law to society and ecology.","cn":"20 世纪加入社会排斥与竞争排斥，把‘关上的门’从法律扩展到社会与生态。"}]},"similar":{"note":{"en":"The first group is the exclude family; the second compares ways of removing someone or something, each with a different mechanism.","cn":"第一组是 exclude 词族；第二组比较把人或物移走的不同方式，各自机制不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"exclude","ipa":"/ɪkˈskluːd/","tag":"verb","definition":"to shut someone or something out. It is the action; exclusion is the act or state.","definitionCN":"把人或物关在外面；是动作，exclusion 是行为或状态。"},{"word":"exclusive","ipa":"/ɪkˈskluːsɪv/","tag":"adjective","definition":"limited to a particular group, or not shared. It describes the arrangement, not the act of shutting.","definitionCN":"限于特定群体的，或不共享的；描述安排，而非关门动作。"},{"word":"exclusively","ipa":"/ɪkˈskluːsɪvli/","tag":"adverb","definition":"only, and to the exclusion of everything else. It turns the adjective into a restriction on scope.","definitionCN":"只；唯独；把其他一切排除在外。它把形容词变成范围限制。"},{"word":"exclusionary","ipa":"/ɪkˈskluːʒənəri/","tag":"adjective","definition":"tending to exclude people or things. It is used of rules, practices, and policies.","definitionCN":"倾向于排斥人或物的；用于规则、做法与政策。"}]},{"heading":"NEAR MEANING","entries":[{"word":"omission","ipa":"/əˈmɪʃn/","tag":"left out by oversight","definition":"something left out, often by mistake or by choice in writing. It does not require a door or a boundary.","definitionCN":"被漏掉的东西，常因疏忽或书写选择；不需要门或边界。"},{"word":"removal","ipa":"/rɪˈmuːvl/","tag":"taking away","definition":"the act of taking something away from its place. It focuses on the object being moved, not on who is kept out.","definitionCN":"把某物从其位置拿走；聚焦被移动的对象，而不是被挡在外面的人。"},{"word":"ejection","ipa":"/ɪˈdʒekʃn/","tag":"forced out","definition":"the act of forcing someone or something out, often physically. It is more violent than exclusion.","definitionCN":"强行把人或物弄出去，常是物理性的；比 exclusion 更暴力。"},{"word":"ostracism","ipa":"/ˈɒstrəsɪzəm/","tag":"social shunning","definition":"the deliberate avoidance or shunning of a person by a group. It is exclusion carried out by many small refusals.","definitionCN":"群体对某人有意回避、排斥；是许多次小拒绝共同完成的 exclusion。"},{"word":"segregation","ipa":"/ˌseɡrɪˈɡeɪʃn/","tag":"separated groups","definition":"the enforced separation of groups, especially by race or sex. It divides space rather than simply shutting one door.","definitionCN":"按种族或性别等强制分隔群体；它分割空间，而不只是关一扇门。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out plus claudere shut. Exclusion is the closing of a door in someone's face, seen either as an act or as a state.","cn":"只用真实成分：ex-‘向外’加 claudere‘关’。exclusion 就是在某人面前关门，可作为动作也可作为状态来看。"},"normal":[{"en":"Ex- out, claudere shut: exclusion is being shut out.","cn":"ex- 向外，claudere 关：exclusion 就是被关在外面。"},{"en":"Include and exclude are the two directions of the same door.","cn":"include 与 exclude 是同一扇门的两个方向。"},{"en":"An exclusion clause is a door drawn on paper.","cn":"除外条款就是画在纸上的一扇门。"},{"en":"Social exclusion closes many doors at once.","cn":"社会排斥同时关上许多扇门。"},{"en":"A club's exclusion is its selling point: the closed door is the product.","cn":"俱乐部的排他性就是卖点：关着的门本身是产品。"}],"abstract":[{"en":"Every inside is made by an outside; exclusion is how a group learns its own shape.","cn":"每个‘里面’都由‘外面’造出；排斥是群体认识自身形状的方式。"},{"en":"The same closed door can be a punishment or a privilege, depending on which side you stand.","cn":"同一扇关着的门，可以是惩罚也可以是特权，取决于你站在哪一侧。"},{"en":"Exclusion is cheaper than inclusion, which is why systems drift toward it.","cn":"排斥比容纳便宜，所以系统会自然漂向排斥。"}]},"examples":[{"en":"The exclusion of the small firms from the scheme was challenged in court.","cn":"把小公司排除在该计划之外的做法在法庭上受到挑战。"},{"en":"He worked on the project to the exclusion of almost everything else.","cn":"他做这个项目，几乎把其他一切排除在外。"},{"en":"The report treated social exclusion as a health issue, not only a moral one.","cn":"报告把社会排斥当作健康问题，而不只是道德问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗死路”——走到一颗标着‘死路’的门前，被关在外面：exclusion 排除、排斥。","word":"exclusion"},"root":"源自拉丁 excludere（ex-‘向外’+ claudere‘关’）与 exclusio‘关在外面’；核心是“把某人或某物挡在门外的动作或状态”。","sensesIntro":{"en":"Eight senses of exclusion, one image: a door closes and someone stays outside. The door may be a club, a contract, a society, a niche, a tax base, a school, or a membership rule.","cn":"exclusion 的八个义项共用一个意象：门关上，有人留在外面。这扇门可以是俱乐部、合同、社会、生态位、税基、学校或会员规则。"},"semanticMap":{"core":{"en":"CORE IMAGE: a door closing with a person left in the corridor.","cn":"核心意象：门关上，一个人被留在走廊里。"},"chain":["LATIN CLAUDERE = TO SHUT","EX- + CLAUDERE = TO SHUT OUT","EXCLUSIO = A SHUTTING OUT","ENGLISH EXCLUSION = THE ACT OR STATE OF BEING OUT","A BOUNDARY IS DRAWN AND ENFORCED","ANY DELIBERATE KEEPING OUT"],"branches":[{"senses":"01 · 02","en":"THE TWO SIDES OF THE DOOR: the act of shutting out and the experience of being outside.","cn":"门的两侧：关门的动作与留在外面的经历。"},{"senses":"03 · 06","en":"THE WRITTEN BOUNDARY: insurance clauses and tax rules remove items before they count.","cn":"写下的边界：保险条款与税务规则在计算前移走项目。"},{"senses":"04 · 07","en":"THE SOCIAL AND PUNITIVE DOOR: structural marginalization and formal expulsion both put a person outside.","cn":"社会性与惩罚性的门：结构性边缘化与正式开除都把一个人放到外面。"},{"senses":"05","en":"THE ECOLOGICAL DOOR: competition closes a niche on a rival species.","cn":"生态的门：竞争对竞争者关上生态位。"},{"senses":"08","en":"THE VALUED DOOR: exclusivity makes the closed door itself desirable.","cn":"被珍视的门：排他性让关着的门本身变得有吸引力。"}]},"affixes":{"intro":{"en":"Exclusion is ex- plus claud- plus -sion. The same root gives include, conclude, seclude, and the noun clause; the door image is shared across all of them.","cn":"exclusion 是 ex- 加 claud- 加 -sion。同一词根给出 include、conclude、seclude 与名词 clause；它们共享‘门’的意象。"},"latinIntro":{"en":"The Latin forms are claudere, excludere, and exclusio. Excludere is built from a real prefix and a real verb, so no reconstruction is needed here.","cn":"拉丁形式是 claudere、excludere、exclusio。excludere 由真实前缀与真实动词构成，这里不需要重构。"},"items":[{"word":"exclude","structure":"ex- + claudere (verb)","meaning":"to shut out or leave out","meaningCN":"排除；把……关在外面","example":"The rules exclude late entries.","exampleCN":"规则排除迟交的参赛作品。"},{"word":"exclusion","structure":"exclud- + -sion (action noun)","meaning":"the act or state of being shut out","meaningCN":"排除；被排除的状态","example":"His exclusion from the team was temporary.","exampleCN":"他被排除在队伍之外是暂时的。"},{"word":"exclusive","structure":"exclud- + -ive (adjective)","meaning":"restricted to a few; not shared","meaningCN":"排他的；独有的","example":"The shop sells exclusive designs.","exampleCN":"这家店出售独家设计。"},{"word":"exclusively","structure":"exclusive + -ly (adverb)","meaning":"only; with everything else excluded","meaningCN":"专门地；唯独地","example":"The room is used exclusively for meetings.","exampleCN":"这个房间只用于开会。"},{"word":"exclusivity","structure":"exclusive + -ity (quality noun)","meaning":"the state of being restricted to a few","meaningCN":"排他性；独家性","example":"The brand charges for exclusivity.","exampleCN":"这个品牌为排他性收费。"},{"word":"exclusionary","structure":"exclusion + -ary (relational adjective)","meaning":"tending to exclude","meaningCN":"排他性的；造成排斥的","example":"The zoning rules had an exclusionary effect.","exampleCN":"分区规则产生了排斥效果。"},{"word":"include","structure":"in- (in) + claudere (shut)","meaning":"to shut inside, hence to contain","meaningCN":"包含；把……关在里面（in-‘在内’+ claudere‘关’）","example":"The price includes breakfast.","exampleCN":"价格包含早餐。"},{"word":"conclude","structure":"com- (together) + claudere (shut)","meaning":"to close together, hence to end or infer","meaningCN":"结束；得出结论（com-‘一起’+ claudere‘关’）","example":"The talk concluded with a short summary.","exampleCN":"讲座以简短总结结束。"},{"word":"seclude","structure":"se- (apart) + claudere (shut)","meaning":"to shut apart, hence to isolate","meaningCN":"使隔离；隐居（se-‘分开’+ claudere‘关’）","example":"The cabin was secluded by tall pines.","exampleCN":"小屋被高松林隔离起来。"},{"word":"clause","structure":"Latin clausa (a closing) < claudere","meaning":"a distinct part of a sentence or contract","meaningCN":"从句；条款；源自‘关闭、收束的部分’","example":"The final clause limits the agreement to five years.","exampleCN":"最后一条条款把协议限制在五年内。"}],"latinEntries":[{"word":"claudere","structure":"Latin verb","meaning":"to shut, close, enclose","meaningCN":"关；闭；围住"},{"word":"excludere","structure":"ex- + claudere","meaning":"to shut out","meaningCN":"关在外面；排除"},{"word":"exclusio","structure":"exclus- + -io (action noun)","meaning":"a shutting out","meaningCN":"关在外面；排除"}]}},{"word":"exclusively","ipa_uk":"/ɪkˈskluːsɪvli/","ipa_us":"/ɪkˈskluːsɪvli/","definition_zh":"专门地；唯独地；独家地；排他地；完全地","definition_en":"in a way that includes only one person, group, purpose, or source and excludes all others","core_image":"一扇门只为一个名字打开，门上的名单短得只剩一行。","scene":"画廊开幕前，策展人说这批画只在这里展出。Before the opening the curator says these paintings are shown exclusively here and nowhere else.","sceneCN":"这里 exclusively 是「独家地、只此一处」（第 2 个义项：把展示的独有权只给一家机构地）；句意：开幕前，策展人说这批画只在这里独家展出，别处看不到。","pos":[{"tag":"adv.","zh":"专门地；唯独地；独家地；排他地；完全地"}],"collocations":[{"phrase":"exclusively for members","zh":"仅限会员"},{"phrase":"available exclusively online","zh":"仅在线上提供"},{"phrase":"rely exclusively on","zh":"完全依赖"},{"phrase":"devoted exclusively to","zh":"专门用于；全心投入"},{"phrase":"exclusively owned","zh":"独家拥有的"},{"phrase":"broadcast exclusively","zh":"独家播出"}],"forms":[{"label":"原级（副词）","form":"exclusively"},{"label":"比较级（用 more）","form":"more exclusively"},{"label":"最高级（用 most）","form":"most exclusively"},{"label":"形容词形式","form":"exclusive"}],"derivatives":[{"word":"exclusive","pos":"adj.","zh":"排他的；独有的；高档的"},{"word":"exclusion","pos":"n.","zh":"排除；排斥"},{"word":"exclusivity","pos":"n.","zh":"排他性；独家性"},{"word":"exclude","pos":"v.","zh":"排除；不包括"}],"senses":[{"no":"01","title":"For one group only","titleCN":"专门地：只对某一群体开放","definition":"in a way that is open only to a particular group of people","definitionCN":"仅对某一特定人群开放地","example":"The lounge is used exclusively by first-class passengers.","exampleCN":"休息室只供头等舱乘客使用。","why":"The adverb modifies the verb of access: the door opens for one list and stays shut for every other list.","whyCN":"这个副词修饰‘进入’这个动作：门对一份名单打开，对所有其他名单保持关闭。"},{"no":"02","title":"Exclusive rights","titleCN":"独家地：只授权一家媒体或卖家","definition":"in a way that gives one outlet the sole right to publish, sell, or show something","definitionCN":"把出版、销售或展示的独有权只给一家机构地","example":"The interview was broadcast exclusively on the local channel.","exampleCN":"这次采访只在本频道独家播出。","why":"Here the exclusion is contractual: other outlets are kept out by rights, so access itself becomes the product.","whyCN":"这里的排除是合同性的：其他媒体被权利挡在门外，于是‘能访问’本身成了产品。"},{"no":"03","title":"Not shared with others","titleCN":"排他地：不与他人共享","definition":"in a way that excludes sharing or joint use","definitionCN":"排除共享或共同使用地","example":"The two researchers worked exclusively, never pooling their notes.","exampleCN":"两位研究者各自独立工作，从不合并笔记。","why":"The word can separate people as well as things: each side keeps its own territory, and the boundary is deliberately maintained.","whyCN":"这个词也能把人分开：各自守住自己的地盘，边界被有意维持。"},{"no":"04","title":"Only, and nothing else","titleCN":"唯独地：唯一依赖或唯一原因","definition":"solely; with no other factor or source involved","definitionCN":"仅仅；不涉及任何其他因素或来源地","example":"Success depends exclusively on how well the team prepares.","exampleCN":"成功完全取决于团队准备得如何。","why":"The exclusion is logical rather than physical: all other candidate causes are eliminated, leaving one factor that must carry the result.","whyCN":"这里的排除是逻辑性的而非物理性的：所有其他候选原因都被排除，只剩一个必须承担结果的因素。"},{"no":"05","title":"Sole ownership","titleCN":"专有地：权利只归一方","definition":"in a way that gives one party sole legal control or ownership","definitionCN":"使一方获得唯一法律控制权或所有权地","example":"The company holds the patent exclusively.","exampleCN":"该公司独家持有这项专利。","why":"Legal exclusion defines who may act. The right is not stronger because it is exclusive; it is exclusive because the law names only one holder.","whyCN":"法律上的排除定义‘谁可以行动’。权利不是因排他而更强，而是因法律只点名一个持有人才排他。"},{"no":"06","title":"Entirely devoted","titleCN":"完全地：把全部时间或精力只给一件事","definition":"with all of one's time, attention, or resources given to one thing","definitionCN":"把全部时间、注意力或资源只给一件事地","example":"Her time was devoted exclusively to the dictionary project.","exampleCN":"她的时间全部投入到词典项目。","why":"Attention is treated as a finite set: whatever is given here is simultaneously taken from everything else.","whyCN":"注意力被当作有限集合：给这里多少，就同时从其他一切那里拿走多少。"},{"no":"07","title":"Separately, not jointly","titleCN":"单独地：分开处理，不合并","definition":"in a way that deals with things separately rather than together","definitionCN":"把事物分开处理而不是合并处理地","example":"The report treats the two periods exclusively, in separate chapters.","exampleCN":"报告把两个时期分开，各用单独章节处理。","why":"This is the procedural sense: categories are kept apart so that each can be judged on its own terms.","whyCN":"这是程序性义项：类别被分开，好让每一类按自己的标准被判断。"},{"no":"08","title":"Restricted purpose","titleCN":"专款专用于：只许用于某一用途","definition":"in a way that limits a fund or resource to one specified use","definitionCN":"把资金或资源限定在某一指定用途地","example":"The fund is used exclusively for student scholarships.","exampleCN":"这笔基金只用于学生奖学金。","why":"Money is marked before it is spent. The restriction travels with the resource, so any other use would be a breach.","whyCN":"钱在被花出去之前就被打上标记。限制随资源一起流动，因此任何其他用途都构成违规。"}],"etymology":{"intro":{"en":"Exclusively is exclusive plus -ly. Exclusive comes from Medieval Latin exclusivus, from excludere, to shut out. The adverb adds the Old English suffix -lice.","cn":"exclusively 是 exclusive 加 -ly。exclusive 来自中世纪拉丁 exclusivus，源头是 excludere‘关在外面’。副词再加古英语后缀 -lice。"},"items":[{"era":"LATIN claudere","en":"To shut or close. The family includes include, conclude, seclude, and clause, all built from the image of a closed boundary.","cn":"关、闭。词族包括 include、conclude、seclude 与 clause，全部建在‘闭合边界’的意象上。"},{"era":"LATIN excludere","en":"Ex- out plus claudere shut: to shut out. The verb creates an inside by keeping something outside.","cn":"ex-‘向外’加 claudere‘关’：关在外面。该动词通过把某物留在外面来创造‘里面’。"},{"era":"LATIN exclusivus","en":"Medieval Latin exclusivus meant ‘that excludes’. It shifted from the act of shutting out to the quality of a right or privilege.","cn":"中世纪拉丁 exclusivus 意为‘排除的’。它从‘关门的动作’转向权利或特权所具有的性质。"},{"era":"ENGLISH 16c","en":"English exclusive appears in the 16c, first in legal and commercial contexts where one party held a sole right.","cn":"英语 exclusive 在 16 世纪出现，先用于一方持有独有权力的法律与商业语境。"},{"era":"ENGLISH 19c","en":"The adverb exclusively settled into general use in the 19c, when advertising and retail began to sell access itself as a mark of status.","cn":"副词 exclusively 在 19 世纪进入一般用法；当时广告与零售开始把‘准入’本身当作身份标志来售卖。"},{"era":"MODERN ENGLISH","en":"Modern usage ranges from neutral logic (depends exclusively on) to social signalling (an exclusive club). The adverb keeps the door image in both.","cn":"现代用法从中性的逻辑（完全取决于）到社会信号（高档俱乐部）都有；副词在两者中都保留‘门’的意象。"}]},"similar":{"note":{"en":"The first group is the exclusive family; the second compares adverbs of restriction, each limiting a different dimension.","cn":"第一组是 exclusive 词族；第二组比较表示限制的副词，各自限制不同维度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"exclusive","ipa":"/ɪkˈskluːsɪv/","tag":"adjective","definition":"restricted to a particular group or holder. The adverb applies that restriction to an action.","definitionCN":"限于特定群体或持有者的；副词则把这种限制加到动作上。"},{"word":"exclusion","ipa":"/ɪkˈskluːʒn/","tag":"noun","definition":"the act or state of being shut out. It names the boundary, not the manner of acting.","definitionCN":"排除的行为或状态；命名边界，而非动作方式。"},{"word":"exclusivity","ipa":"/ˌekskluːˈsɪvəti/","tag":"quality noun","definition":"the quality of being limited to few. It names the value of the closed door as a product.","definitionCN":"限于少数人的性质；命名‘关着的门’作为产品的价值。"},{"word":"exclude","ipa":"/ɪkˈskluːd/","tag":"verb","definition":"to shut out. It is the action that produces the exclusive arrangement.","definitionCN":"关在外面；是产生排他安排的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"solely","ipa":"/ˈsəʊlli/","tag":"single factor","definition":"for one reason or by one party only. It stresses a single cause or owner rather than a closed group.","definitionCN":"仅因一个原因或仅由一方；强调单一原因或所有者，而非封闭群体。"},{"word":"only","ipa":"/ˈəʊnli/","tag":"general restriction","definition":"no one or nothing else. It is the broadest limiter and can replace exclusively in many sentences.","definitionCN":"没有其他任何人或物；是最宽泛的限制词，许多句中可替代 exclusively。"},{"word":"entirely","ipa":"/ɪnˈtaɪəli/","tag":"full degree","definition":"completely, with no part left out. It measures extent, not membership.","definitionCN":"完全地，没有一部分被遗漏；测量程度，不涉及成员资格。"},{"word":"uniquely","ipa":"/juːˈniːkli/","tag":"one of a kind","definition":"in a way that is peculiar to one thing. It stresses distinctiveness rather than exclusion.","definitionCN":"以某物独有的方式；强调独特性，而非排除。"},{"word":"purely","ipa":"/ˈpjʊəli/","tag":"nothing mixed in","definition":"with nothing else mixed in. It stresses freedom from contamination or mixture.","definitionCN":"不掺入其他东西；强调没有混杂或污染。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: exclusive plus -ly. The adverb tells you that the door was built for one name and closed on every other.","cn":"只用真实成分：exclusive 加 -ly。这个副词告诉你：门是为一个名字造的，对其他所有名字关闭。"},"normal":[{"en":"Ex- out, claudere shut, -ly manner: exclusively means in a shut-out manner.","cn":"ex- 向外，claudere 关，-ly 方式：exclusively 就是‘以关在外面的方式’。"},{"en":"Exclusively for members: the guest list has one line.","cn":"exclusively for members：宾客名单只有一行。"},{"en":"An exclusive interview: the other cameras are still outside.","cn":"独家采访：其他摄像机还留在门外。"},{"en":"Depends exclusively on: every other cause has been struck from the list.","cn":"完全取决于：其他每个原因都已被从名单上划掉。"},{"en":"A fund used exclusively: the money carries its own label.","cn":"专款专用：钱上贴着自己的标签。"}],"abstract":[{"en":"Exclusively always answers a silent question: excluded from what, and for whom?","cn":"exclusively 总在回答一个沉默的问题：把什么排除在外，又为谁留着？"},{"en":"Scarcity can be made by rules as easily as by supply; exclusive access is manufactured scarcity.","cn":"稀缺可以由规则造出，也可以由供给造出；排他准入就是人造稀缺。"},{"en":"The same word describes a rigorous proof and a luxury club: logic and status share a door.","cn":"同一个词既能描述严格证明，也能描述奢侈俱乐部：逻辑与身份共用一扇门。"}]},"examples":[{"en":"The dataset is available exclusively to researchers who sign the agreement.","cn":"该数据集仅对签署协议的研究者开放。"},{"en":"He spoke exclusively in quotations, as if his own voice might give offence.","cn":"他说话全用引文，仿佛自己的声音会冒犯人。"},{"en":"The species feeds exclusively on one kind of fig, which makes it vulnerable.","cn":"该物种只以一种无花果为食，这使它很脆弱。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗死路，只为一人开”——别的路都封死，只留一扇门：exclusively 专门地、唯独地。","word":"exclusively"},"root":"由 exclusive 加 -ly 构成；exclusive 来自中世纪拉丁 exclusivus，源头是 excludere（ex-‘向外’+ claudere‘关’），核心是“只对一方开放、把其余全部关在门外”。","sensesIntro":{"en":"Eight senses of exclusively, one structure: one door, one list, everyone else outside. The list may be a customer group, a media right, a research team, a cause, a patent holder, a project, a procedure, or a budget line.","cn":"exclusively 的八个义项共用一个结构：一扇门、一份名单、其余人留在外面。名单可以是顾客群、媒体权利、研究团队、原因、专利持有人、项目、程序或预算科目。"},"semanticMap":{"core":{"en":"CORE IMAGE: a door with a one-line guest list, everyone else in the corridor.","cn":"核心意象：门上一份只有一行的宾客名单，其他人都留在走廊。"},"chain":["LATIN CLAUDERE = TO SHUT","EXCLUDERE = TO SHUT OUT","EXCLUSIVUS = THAT EXCLUDES","EXCLUSIVE = RESTRICTED TO ONE","EXCLUSIVELY = IN A RESTRICTED MANNER","ONLY THIS GROUP, USE, CAUSE, OR HOLDER"],"branches":[{"senses":"01 · 02","en":"THE DOOR OF ACCESS: a members' lounge and an exclusive broadcast both limit who may enter.","cn":"准入之门：会员休息室与独家播出都限定谁能进入。"},{"senses":"03 · 07","en":"THE SEPARATION LINE: not sharing work and treating periods separately both keep categories apart.","cn":"分隔线：不共享工作与分开处理时期，都把类别隔开。"},{"senses":"04","en":"THE LOGICAL KNIFE: one cause is left after all others are cut away.","cn":"逻辑的刀：其他原因都被切掉后，只剩一个。"},{"senses":"05","en":"THE LEGAL MONOPOLY: the law names a single holder.","cn":"法律垄断：法律只点名一个持有人。"},{"senses":"06 · 08","en":"THE FINITE RESOURCE: time and money are marked for one use and taken from all others.","cn":"有限资源：时间与金钱被标记给一种用途，并从其他用途中取走。"}]},"affixes":{"intro":{"en":"Exclusively is exclusive plus -ly. Exclusive is ex- plus claud- plus -ive, and the family also gives exclusion, exclusivity, and the verb exclude.","cn":"exclusively 是 exclusive 加 -ly。exclusive 是 ex- 加 claud- 加 -ive；词族还有 exclusion、exclusivity 与动词 exclude。"},"latinIntro":{"en":"The Latin chain is claudere, excludere, exclusivus. The last form is Medieval Latin, so the adjective is a later legal development rather than a classical one.","cn":"拉丁链条是 claudere、excludere、exclusivus。最后一个属中世纪拉丁，因此形容词是较晚的法律发展，而非古典形式。"},"items":[{"word":"exclusive","structure":"ex- + claud- + -ive (adjective)","meaning":"restricted to one group or holder","meaningCN":"排他的；独有的","example":"The hotel has an exclusive beach.","exampleCN":"这家酒店有一片专属海滩。"},{"word":"exclusively","structure":"exclusive + -ly (adverb)","meaning":"only, with others shut out","meaningCN":"专门地；唯独地","example":"Tickets are sold exclusively online.","exampleCN":"门票只在线上出售。"},{"word":"exclusiveness","structure":"exclusive + -ness (quality noun)","meaning":"the quality of being exclusive","meaningCN":"排他性；封闭性","example":"The exclusiveness of the group discouraged newcomers.","exampleCN":"这个团体的封闭性让新人却步。"},{"word":"exclusivity","structure":"exclusive + -ity (state noun)","meaning":"the commercial or social value of limited access","meaningCN":"独家性；排他带来的价值","example":"The contract guarantees exclusivity for two years.","exampleCN":"合同保证两年独家权。"},{"word":"exclusion","structure":"exclud- + -sion (action noun)","meaning":"the act or state of being shut out","meaningCN":"排除；被排除状态","example":"The exclusion of the witness changed the case.","exampleCN":"排除该证人改变了案件走向。"},{"word":"excluding","structure":"exclude + -ing (preposition/participle)","meaning":"not counting; leaving out","meaningCN":"不包括；除……之外","example":"The price is 20 pounds, excluding postage.","exampleCN":"价格为二十英镑，不含邮费。"},{"word":"exclude","structure":"ex- + claudere (verb)","meaning":"to shut out","meaningCN":"排除；不让进入","example":"The test excludes anyone under eighteen.","exampleCN":"该测试排除十八岁以下者。"},{"word":"include","structure":"in- + claudere (verb)","meaning":"to shut in, hence contain","meaningCN":"包含；把……纳入","example":"The fee includes two nights' stay.","exampleCN":"费用包含两晚住宿。"},{"word":"seclude","structure":"se- + claudere (verb)","meaning":"to shut apart, isolate","meaningCN":"使隔离；使隐居","example":"The writer secluded herself for a month.","exampleCN":"作家把自己隔离了一个月。"},{"word":"clause","structure":"Latin clausa (closing) < claudere","meaning":"a closed-off section of a sentence or contract","meaningCN":"从句；条款（被收束起来的一段）","example":"The clause allows early termination.","exampleCN":"该条款允许提前终止。"}],"latinEntries":[{"word":"claudere","structure":"Latin verb","meaning":"to shut, close","meaningCN":"关；闭"},{"word":"excludere","structure":"ex- + claudere","meaning":"to shut out","meaningCN":"关在外面；排除"},{"word":"exclusivus","structure":"Medieval Latin adjective","meaning":"that excludes, exclusive","meaningCN":"排除性的；排他的"}]}},{"word":"expansion","ipa_uk":"/ɪkˈspænʃn/","ipa_us":"/ɪkˈspænʃən/","definition_zh":"扩张；扩大；膨胀；扩建；扩展；（数学）展开式","definition_en":"the process of becoming larger in size, scope, or volume, or the result of that growth","core_image":"一张地图被从中心向四周摊开，边角不断推到桌沿，纸面越来越宽。","scene":"公司把一间小办公室扩成三层楼。The company turns one small office into three floors, and the staff call it an expansion rather than a move.","sceneCN":"这里 expansion 是「规模或空间的扩大」（第 1、2 个义项）；句意：公司把一间小办公室扩成三层楼，员工说这是扩张而不是搬家。","pos":[{"tag":"n.","zh":"扩张；扩大；膨胀；扩建；扩展；（数学）展开式"}],"collocations":[{"phrase":"economic expansion","zh":"经济扩张"},{"phrase":"territorial expansion","zh":"领土扩张"},{"phrase":"thermal expansion","zh":"热膨胀"},{"phrase":"business expansion","zh":"业务扩张"},{"phrase":"an expansion of the scope","zh":"范围的扩大"},{"phrase":"expansion into new markets","zh":"向新市场扩张"},{"phrase":"a binomial expansion","zh":"二项式展开"}],"forms":[{"label":"复数（名词）","form":"expansions"}],"derivatives":[{"word":"expand","pos":"v.","zh":"扩张；扩大；展开"},{"word":"expansive","pos":"adj.","zh":"广阔的；扩张性的；健谈的"},{"word":"expanse","pos":"n.","zh":"广阔的区域；大片"},{"word":"expansionist","pos":"n./adj.","zh":"扩张主义者；扩张主义的"}],"senses":[{"no":"01","title":"Increase in size or scope","titleCN":"扩张：规模或范围变大","definition":"the process of becoming larger in size, number, or scope","definitionCN":"尺寸、数量或范围变大的过程","example":"The expansion of the library added two reading rooms.","exampleCN":"图书馆的扩建增加了两个阅览室。","why":"Expansion is the noun of a surface being spread wider. What was bounded becomes less bounded, and the change is measured against the old edge.","whyCN":"expansion 是‘表面被摊得更宽’的名词。原本有边的东西变得少受边界限制，变化以旧边界为参照来测量。"},{"no":"02","title":"Physical swelling","titleCN":"膨胀：体积因内部作用变大","definition":"an increase in volume caused by heat, pressure, or internal processes","definitionCN":"由热、压力或内部过程引起的体积增大","example":"The expansion of the gas pushed the piston down.","exampleCN":"气体的膨胀把活塞推了下去。","why":"Here the spreading is three-dimensional and driven from inside: particles move apart, so the same amount of matter occupies more space.","whyCN":"这里的摊开是三维的、由内部驱动的：粒子彼此远离，因此同样的物质占据更多空间。"},{"no":"03","title":"Thermal expansion","titleCN":"热膨胀：受热后尺寸变大","definition":"the increase in length or volume of a material when its temperature rises","definitionCN":"材料温度升高时长或体积的增加","example":"Railways leave gaps for thermal expansion.","exampleCN":"铁轨留出缝隙以应对热膨胀。","why":"Heat adds kinetic energy, the bonds stretch slightly, and the object grows. The effect is predictable enough to be designed for.","whyCN":"热量增加动能，化学键略微拉长，物体就变大。这个效应可预测到足以被设计进来。"},{"no":"04","title":"Building extension","titleCN":"扩建：在原有结构上加大","definition":"the addition of new space or structures to an existing building or site","definitionCN":"在现有建筑或场地上增加新的空间或结构","example":"The museum's expansion doubled its exhibition space.","exampleCN":"博物馆的扩建让展陈面积翻倍。","why":"A building has a footprint. Expansion means pushing that footprint outward while keeping the original as the centre.","whyCN":"建筑有一个占地轮廓。扩建就是把轮廓向外推，同时把原建筑当作中心。"},{"no":"05","title":"Territorial expansion","titleCN":"领土扩张：国家把边界向外推","definition":"the extension of a country's territory or political control","definitionCN":"一国领土或政治控制范围的扩展","example":"The empire's expansion brought new languages under one administration.","exampleCN":"帝国的扩张把新的语言纳入同一行政体系。","why":"A border is a line on a map. Expansion moves the line outward, and the move is usually backed by power rather than by geometry.","whyCN":"边界是地图上的一条线。扩张把线向外移，而这一移动通常由权力而非几何推动。"},{"no":"06","title":"Economic expansion","titleCN":"经济扩张：产出与需求一起增长","definition":"a period in which economic activity, output, or employment grows","definitionCN":"经济活动、产出或就业增长的时期","example":"The expansion lasted longer than the central bank expected.","exampleCN":"这轮经济扩张持续得比央行预期更久。","why":"An economy is measured by aggregates. Expansion means the aggregate grows, even if some regions or sectors shrink.","whyCN":"经济由总量衡量。扩张指总量增长，即使某些地区或部门在收缩。"},{"no":"07","title":"Mathematical expansion","titleCN":"数学展开：把乘积写成多项式之和","definition":"the rewriting of a compact mathematical expression as a longer sum or product","definitionCN":"把紧凑的数学表达式改写成更长的和式或乘积","example":"The expansion of the bracket produced four terms.","exampleCN":"括号展开后得到四项。","why":"In algebra the word reverses the idea of compactness: a folded expression is spread out into all its parts, even though the result is longer.","whyCN":"代数里这个词反转了‘紧凑’：折叠的表达式被摊成所有部件，即使结果更长。"},{"no":"08","title":"Business expansion","titleCN":"业务扩张：进入新市场或新品类","definition":"the growth of a company into new products, markets, or locations","definitionCN":"公司扩展到新产品、新市场或新地点","example":"Its expansion into Asia required a new supply chain.","exampleCN":"它向亚洲的扩张需要一套新的供应链。","why":"A firm's boundary is its market. Expansion crosses that boundary, and the cost of crossing is usually paid before the revenue arrives.","whyCN":"公司的边界就是它的市场。扩张跨过边界，而跨越的成本通常在收入到来之前先付。"},{"no":"09","title":"Narrative unfolding","titleCN":"叙述展开：把要点铺成完整段落","definition":"the development of a story, argument, or speech from a brief idea into fuller form","definitionCN":"故事、论证或演讲由简短想法发展为更完整的形式","example":"The essay is an expansion of a single paragraph in her notebook.","exampleCN":"这篇文章是她笔记本里一段话的展开。","why":"Language also unfolds: a compressed idea is stretched into sentences, and the length is the visible sign of the expansion.","whyCN":"语言也会展开：压缩的想法被拉成句子，长度就是 expansion 的外在标志。"}],"etymology":{"intro":{"en":"Expansion is from Latin expansio, from expandere: ex- out plus pandere to spread. The root is pandere, not spend, and the two should never be merged.","cn":"expansion 来自拉丁 expansio，源头是 expandere：ex-‘向外’加 pandere‘摊开’。词根是 pandere，不是 spend，两者绝不应合并。"},"items":[{"era":"LATIN pandere","en":"To spread out, open wide, or unfold. It describes a surface or arms being opened, and it is unrelated to English spend, which comes from pendere, to weigh out.","cn":"摊开、张开、展开。它描述表面或手臂被打开；与英语 spend 无关，spend 来自 pendere‘称量付出’。"},{"era":"LATIN expandere","en":"Ex- out plus pandere spread: to spread out, unfold, expand. The verb keeps the physical image of something opened beyond its former edge.","cn":"ex-‘向外’加 pandere‘摊开’：摊开、展开、扩张。该动词保留‘某物被打开到旧边界之外’的物理意象。"},{"era":"LATIN expansio","en":"A spreading out. The noun could describe land, the sky, or a gesture; the modern technical senses are later specializations.","cn":"摊开。该名词可描述土地、天空或手势；现代技术义项是后来的专门化。"},{"era":"ENGLISH 17c","en":"English expansion appears in the 17c for physical spreading and for the growth of territory or influence.","cn":"英语 expansion 在 17 世纪出现，用于物理摊开，也用于领土或影响力的增长。"},{"era":"ENGLISH 18c-19c","en":"Science gave the word thermal expansion and algebraic expansion, each a precise kind of spreading with its own rules.","cn":"科学赋予了该词热膨胀与代数展开两个义项，各自是有精确规则的一类摊开。"},{"era":"MODERN ENGLISH","en":"Economics added the business cycle sense, while media added the sense of expanding a story or an idea into fuller text.","cn":"经济学加入商业周期义项，媒体则加入‘把故事或想法扩写成更完整文本’的义项。"}]},"similar":{"note":{"en":"The first group is the expand family; the second compares kinds of growth, each changing a different dimension or driven by a different force.","cn":"第一组是 expand 词族；第二组比较各种‘增长’，各自改变不同维度或由不同力量驱动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"expand","ipa":"/ɪkˈspænd/","tag":"verb","definition":"to become or make larger. It is the action behind expansion, and also means to spread out.","definitionCN":"变大或使变大；是 expansion 背后的动作，也可指摊开。"},{"word":"expansive","ipa":"/ɪkˈspænsɪv/","tag":"adjective","definition":"wide in extent, or tending to expand. It can also describe a warm, talkative mood.","definitionCN":"广阔的，或倾向于扩张的；也可形容热情健谈的情绪。"},{"word":"expanse","ipa":"/ɪkˈspæns/","tag":"noun","definition":"a wide area of land, water, or sky. It names the result, not the process.","definitionCN":"大片土地、水域或天空；命名结果，而非过程。"},{"word":"expansionism","ipa":"/ɪkˈspænʃənɪzəm/","tag":"political noun","definition":"the policy of extending a country's territory or influence. It is expansion turned into a doctrine.","definitionCN":"扩展一国领土或影响力的政策；是 expansion 变成一种主义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"growth","ipa":"/ɡrəʊθ/","tag":"increase in amount","definition":"an increase in size, number, or importance. It is the broadest word and can be biological or economic.","definitionCN":"尺寸、数量或重要性的增加；最宽泛，可指生物或经济。"},{"word":"enlargement","ipa":"/ɪnˈlɑːdʒmənt/","tag":"made bigger","definition":"the act of making something larger, often an image or a space. It stresses the agent doing the enlarging.","definitionCN":"把某物变大的行为，常指图像或空间；强调施动者。"},{"word":"extension","ipa":"/ɪkˈstenʃn/","tag":"added length or scope","definition":"the act of adding to something so that it reaches further. It often implies adding a part rather than spreading the whole.","definitionCN":"把某物加长或加宽以延伸；常暗示增加一部分，而非整体摊开。"},{"word":"swelling","ipa":"/ˈswelɪŋ/","tag":"body or material","definition":"an increase in volume, especially from pressure or fluid. It is usually unwanted and local.","definitionCN":"体积增大，尤因压力或液体；通常是不想要的、局部的。"},{"word":"dilation","ipa":"/daɪˈleɪʃn/","tag":"widening an opening","definition":"the widening of an opening or cavity. It is expansion in one dimension, as of a pupil or a cervix.","definitionCN":"开口或腔体的变宽；是单维度的 expansion，如瞳孔或宫颈。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out plus pandere spread. Expansion is a surface pushed past its old edge. The look-alike spend belongs to a different root.","cn":"只用真实成分：ex-‘向外’加 pandere‘摊开’。expansion 是表面被推到旧边界之外。形近词 spend 属于另一个词根。"},"normal":[{"en":"Ex- out, pandere spread: expansion is spreading the map wider.","cn":"ex- 向外，pandere 摊开：expansion 就是把地图摊得更宽。"},{"en":"Heat makes the rail longer; the gap is designed expansion.","cn":"热让铁轨变长；那道缝就是被设计出来的 expansion。"},{"en":"A museum expansion keeps the old hall as its centre.","cn":"博物馆扩建把旧展厅当作中心。"},{"en":"In algebra, expansion unfolds a bracket into every term.","cn":"代数里，expansion 把括号摊成每一项。"},{"en":"Spend is not the root: expansion spreads, spend weighs out money.","cn":"spend 不是词根：expansion 是摊开，spend 是把钱称量付出。"}],"abstract":[{"en":"Every expansion moves a boundary, and a boundary moved is a boundary disputed.","cn":"每次扩张都移动边界，而被移动的边界就是有争议的边界。"},{"en":"Growth in one dimension is usually paid for by compression in another.","cn":"一个维度上的扩张，通常由另一个维度上的压缩来支付。"},{"en":"The word is neutral: a lung, an empire, and an equation all expand, but only one of them can regret it.","cn":"这个词是中性的：肺、帝国与方程都会 expansion，但只有其中之一会后悔。"}]},"examples":[{"en":"The expansion of the universe is measured by the redshift of distant light.","cn":"宇宙的膨胀通过远处光线的红移来测量。"},{"en":"The company's expansion into rural areas brought jobs but also higher transport costs.","cn":"公司向农村地区扩张带来了就业，也带来了更高的运输成本。"},{"en":"Her short note became a two-page expansion after the editor asked for detail.","cn":"编辑要求补充细节后，她的短笺扩写成了两页。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一克死翻开”——一克东西被死命翻开、摊大：expansion 扩张、膨胀。","word":"expansion"},"root":"源自拉丁 expandere（ex-‘向外’+ pandere‘摊开’）与 expansio‘摊开’；核心是“把有边的东西向四周摊开、变大”。注意与 spend（pendere‘称量’）无词源关系。","sensesIntro":{"en":"Nine senses of expansion, one geometry: something with an edge is spread beyond that edge. The edge may be a wall, a volume, a border, an economy, a bracket, a market, or a paragraph.","cn":"expansion 的九个义项共用一种几何：有边的东西被摊到边界之外。边界可以是墙、体积、国界、经济总量、括号、市场或段落。"},"semanticMap":{"core":{"en":"CORE IMAGE: a map or sheet spread wider and wider across a table.","cn":"核心意象：一张地图或纸在桌面上越摊越宽。"},"chain":["LATIN PANDERE = TO SPREAD OUT","EX- + PANDERE = TO SPREAD FORTH","EXPANSIO = A SPREADING OUT","ENGLISH EXPANSION = THE PROCESS OF GROWING WIDER","AN EDGE IS PUSHED BEYOND ITS OLD POSITION","ANY INCREASE IN SIZE, SCOPE, OR VOLUME"],"branches":[{"senses":"01 · 04","en":"PHYSICAL SPACE: a building or a site pushes its footprint outward.","cn":"物理空间：建筑或场地把占地轮廓向外推。"},{"senses":"02 · 03","en":"VOLUME FROM WITHIN: gas and heated solids occupy more space as their particles move apart.","cn":"由内而外的体积：气体与受热固体因粒子分离而占据更多空间。"},{"senses":"05 · 06 · 08","en":"POLITICAL AND ECONOMIC BOUNDARIES: territory, aggregate output, and markets all have edges that can be crossed.","cn":"政治与经济的边界：领土、总量产出与市场都有可被跨越的边。"},{"senses":"07","en":"THE ALGEBRAIC UNFOLDING: a compact expression is written out term by term.","cn":"代数展开：紧凑表达式被逐项写开。"},{"senses":"09","en":"THE TEXTUAL UNFOLDING: a brief idea is stretched into full sentences.","cn":"文本展开：简短想法被拉成完整句子。"}]},"affixes":{"intro":{"en":"Expansion is ex- plus pans- plus -ion. English builds expand, expansive, expanse, and the political nouns expansionism and expansionist from the same stem.","cn":"expansion 是 ex- 加 pans- 加 -ion。英语用同一词干造出 expand、expansive、expanse，以及政治名词 expansionism 与 expansionist。"},"latinIntro":{"en":"The real Latin forms are pandere, expandere, and expansio. Pandere means to spread; it is not related to pendere, the root of spend and pendant.","cn":"真实拉丁形式是 pandere、expandere、expansio。pandere 意为摊开；它与 pendere（spend 与 pendant 的词根）无关。"},"items":[{"word":"expand","structure":"ex- + pandere (verb)","meaning":"to spread out or become larger","meaningCN":"摊开；扩大；膨胀","example":"Metal expands when it is heated.","exampleCN":"金属受热时会膨胀。"},{"word":"expansion","structure":"expans- + -ion (action noun)","meaning":"the process of growing larger","meaningCN":"扩张；膨胀的过程","example":"The expansion of the port took five years.","exampleCN":"港口的扩建花了五年。"},{"word":"expansive","structure":"expans- + -ive (adjective)","meaning":"wide, or tending to expand","meaningCN":"广阔的；扩张性的","example":"The valley opened into an expansive plain.","exampleCN":"山谷展开成一片广阔平原。"},{"word":"expanse","structure":"expans- + -e (result noun)","meaning":"a wide area","meaningCN":"广阔的区域","example":"A grey expanse of water lay before them.","exampleCN":"一片灰色的广阔水域展现在他们面前。"},{"word":"expansionism","structure":"expansion + -ism (doctrine noun)","meaning":"the policy of territorial or economic expansion","meaningCN":"扩张主义；领土或经济扩张政策","example":"Expansionism shaped the foreign policy of the period.","exampleCN":"扩张主义塑造了那个时期的外交政策。"},{"word":"expansionist","structure":"expansion + -ist (person/adjective)","meaning":"supporting or practising expansion","meaningCN":"扩张主义者；扩张主义的","example":"The government was accused of expansionist aims.","exampleCN":"政府被指有扩张主义目的。"},{"word":"expansionary","structure":"expansion + -ary (relational adjective)","meaning":"designed to encourage economic growth","meaningCN":"扩张性的；旨在刺激经济增长的","example":"The budget was expansionary by design.","exampleCN":"这份预算在设计上就是扩张性的。"},{"word":"expandable","structure":"expand + -able (capability adjective)","meaning":"able to be expanded","meaningCN":"可扩展的；可扩充的","example":"The memory is expandable to twice its size.","exampleCN":"内存可扩展到原来的两倍。"},{"word":"expansively","structure":"expansive + -ly (adverb)","meaning":"in a wide-ranging or outgoing way","meaningCN":"广阔地；热情健谈地","example":"He gestured expansively toward the whole valley.","exampleCN":"他大手一挥，指向整片山谷。"},{"word":"expansiveness","structure":"expansive + -ness (quality noun)","meaning":"the quality of being expansive","meaningCN":"广阔性；扩张性；外向","example":"The expansiveness of the plain surprised the travellers.","exampleCN":"平原的广阔让旅人惊讶。"}],"latinEntries":[{"word":"pandere","structure":"Latin verb","meaning":"to spread out, open","meaningCN":"摊开；打开"},{"word":"expandere","structure":"ex- + pandere","meaning":"to spread out, expand","meaningCN":"摊开；扩张"},{"word":"expansio","structure":"expans- + -io (action noun)","meaning":"a spreading out","meaningCN":"摊开；扩张"}]}},{"word":"experimental","ipa_uk":"/ɪkˌsperɪˈmentl/","ipa_us":"/ˌeksperɪˈmentəl/","definition_zh":"实验的；实验性的；试验性的；实验派的","definition_en":"relating to experiments, or based on a new and untested method","core_image":"一张实验台上摆着两组装置：一组是标准对照，一组加了新变量，中间只差一个条件。","scene":"新药还没上市。The drug is not on the market yet, and the doctor tells the patient it is an experimental treatment that may work or fail.","sceneCN":"这里 experimental 是「试验性的、尚未定论的」（第 2 个义项：新的、试探性的，尚未被确认安全或有效）；句意：新药还没上市，医生告诉病人这是一种试验性治疗，可能有效也可能失败。","pos":[{"tag":"adj.","zh":"实验的；实验性的；试验性的；（艺术）实验派的"}],"collocations":[{"phrase":"experimental evidence","zh":"实验证据"},{"phrase":"experimental design","zh":"实验设计"},{"phrase":"an experimental treatment","zh":"试验性治疗"},{"phrase":"experimental physics","zh":"实验物理学"},{"phrase":"an experimental approach","zh":"实验性方法"},{"phrase":"experimental art","zh":"实验艺术"}],"forms":[{"label":"原级（形容词）","form":"experimental"},{"label":"比较级（用 more）","form":"more experimental"},{"label":"最高级（用 most）","form":"most experimental"},{"label":"副词形式","form":"experimentally"}],"derivatives":[{"word":"experiment","pos":"n./v.","zh":"实验；试验；做实验"},{"word":"experimentally","pos":"adv.","zh":"以实验方式；试验性地"},{"word":"experimentation","pos":"n.","zh":"实验；试验活动"},{"word":"experimentalist","pos":"n.","zh":"实验主义者；实验研究者"}],"senses":[{"no":"01","title":"Based on experiment","titleCN":"实验的：靠实验得来或验证的","definition":"based on or derived from experiments rather than theory alone","definitionCN":"以实验为基础或由实验得出的，而非仅靠理论","example":"The claim rests on experimental evidence, not on a model.","exampleCN":"该主张依赖实验证据，而不是模型。","why":"The adjective marks the source of knowledge. A statement is experimental when a controlled trial, not an argument, produced it.","whyCN":"这个形容词标记知识来源。一个陈述之所以是 experimental，是因为产生它的是受控实验，而不是论证。"},{"no":"02","title":"Tentative and untested","titleCN":"试验性的：还没有定论","definition":"new, tentative, and not yet established as safe or effective","definitionCN":"新的、试探性的，尚未被确认安全或有效","example":"The drug is still experimental and is available only in trials.","exampleCN":"该药仍属试验性，只在临床试验中提供。","why":"Here the word warns the listener: the thing exists, but its status is provisional. It has left the lab and not yet entered routine use.","whyCN":"这里的词是在提醒听者：东西已经存在，但其地位是暂定的。它离开了实验室，尚未进入常规使用。"},{"no":"03","title":"Laboratory equipment or setting","titleCN":"实验室的：用于实验的场地或设备","definition":"used in or belonging to a laboratory or a controlled test","definitionCN":"用于实验室或受控测试的","example":"The experimental rig was calibrated before each run.","exampleCN":"实验装置在每次运行前都经过校准。","why":"The adjective can simply label the setting: a rig, a plot, or a group is experimental because it is part of a test arrangement.","whyCN":"这个形容词也可以单纯标记场景：装置、地块或分组之所以是 experimental，是因为它属于测试安排的一部分。"},{"no":"04","title":"Experimental science","titleCN":"实验科学的：以操控变量为方法","definition":"relating to a branch of science that tests hypotheses by manipulating variables","definitionCN":"与通过操控变量检验假设的科学分支有关的","example":"Experimental physics and theoretical physics ask the same questions differently.","exampleCN":"实验物理学与理论物理学以不同方式问同样的问题。","why":"Here the adjective divides a discipline by method: one side builds apparatus, the other builds equations, and the two must agree.","whyCN":"这里的形容词按方法划分学科：一边造装置，一边造方程，而两者必须对得上。"},{"no":"05","title":"Avant-garde art","titleCN":"实验派的：故意打破既有形式","definition":"in art, music, or film, deliberately departing from established forms and techniques","definitionCN":"在艺术、音乐或电影中故意偏离既有形式与手法","example":"Her experimental films ignore the usual three-act structure.","exampleCN":"她的实验电影无视通常的三幕结构。","why":"The word moves from science to art as a metaphor: the work is a trial, and the audience is the apparatus that will show whether it holds.","whyCN":"这个词从科学借到艺术，成为一个比喻：作品就是一次试验，观众就是检验它是否成立的装置。"},{"no":"06","title":"Empirical research","titleCN":"实证研究的：以数据与实验为依据","definition":"describing research that gathers data through observation or controlled testing","definitionCN":"通过观察或受控测试收集数据的研究","example":"Experimental psychology replaced introspection with measurable tasks.","exampleCN":"实验心理学用可测量的任务取代了内省。","why":"The adjective signals that a claim will be settled by data, not by authority or intuition.","whyCN":"这个形容词表明：主张将由数据来定案，而不是由权威或直觉。"},{"no":"07","title":"Investigational therapy","titleCN":"试验性治疗的：尚未获批的新疗法","definition":"describing a treatment that is still under clinical investigation","definitionCN":"仍处于临床研究阶段的治疗方法","example":"She was offered an experimental therapy after standard options failed.","exampleCN":"标准方案失败后，她获得了试验性治疗。","why":"Medicine uses the word as a consent term: it tells the patient that benefit is hoped for but not established.","whyCN":"医学上用这个词作为知情同意术语：它告诉病人，疗效是被期待的，但尚未被证实。"},{"no":"08","title":"Trial-and-error approach","titleCN":"试探性的：先做小试验再决定","definition":"proceeding by small trials rather than by a fixed plan","definitionCN":"通过小的尝试而非固定计划推进","example":"They took an experimental approach to the schedule, adjusting it weekly.","exampleCN":"他们对日程采取试验性做法，每周调整。","why":"The adjective describes a strategy, not a lab: action is provisional, and each step is treated as information for the next.","whyCN":"这个形容词描述的是策略，而非实验室：行动是暂定的，每一步都被当作下一步的信息。"}],"etymology":{"intro":{"en":"Experimental is experiment plus -al. Experiment comes from Latin experimentum, a trial or test, from experiri, to try. The deeper root is reconstructed and should be marked as generally accepted, not certain.","cn":"experimental 是 experiment 加 -al。experiment 来自拉丁 experimentum‘试验、检验’，源头是 experiri‘尝试’。更深层的词根属于重构，应标为“一般认为是”，不是确定结论。"},"items":[{"era":"LATIN experiri","en":"To try, test, or put to proof. It is a deponent verb, so its passive form has active meaning; the past participle expertus supplies the idea of having tried.","cn":"尝试、检验、验证。它是异态动词，被动形式有主动意义；过去分词 expertus 提供‘已经试过’的含义。"},{"era":"LATIN peritus / periculum","en":"The second element is traditionally connected with peritus, experienced, and periculum, danger or trial. The connection is reconstructed; sources differ on whether the link is direct.","cn":"第二个成分传统上与 peritus‘有经验的’及 periculum‘危险、试炼’联系。该联系是重构的；不同来源对其是否直接相关有分歧。"},{"era":"LATIN experimentum","en":"A trial, test, or proof. In classical Latin it could also mean an attempt or an experience, so the noun still carried the sense of undergoing something.","cn":"试验、检验、证明。古典拉丁中它也可指尝试或经历，因此名词仍带‘经历某事’的意思。"},{"era":"ENGLISH 14c","en":"English borrowed experiment in the 14c for a trial or a proof. The modern scientific sense grew with the controlled method in the 17c.","cn":"英语在 14 世纪借入 experiment，指试验或证明。现代科学义项随 17 世纪受控方法的发展而成长。"},{"era":"ENGLISH 17c","en":"Experimental appears as the adjective of the new method. The Royal Society's culture of demonstration made ‘experimental philosophy’ a public label.","cn":"experimental 作为新方法的形容词出现。皇家学会的演示文化使‘实验哲学’成为公共标签。"},{"era":"MODERN ENGLISH","en":"The 19c-20c extended the adjective to medicine, psychology, and art. In each field it marks something provisional, tested rather than settled.","cn":"19 至 20 世纪，该形容词扩展到医学、心理学与艺术。在每个领域，它都标记某种暂定的、被检验而未定论的东西。"}]},"similar":{"note":{"en":"The first group is the experiment family; the second compares adjectives for knowledge or action that is still being tested.","cn":"第一组是 experiment 词族；第二组比较表示‘仍在检验中’的知识或行动的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"experiment","ipa":"/ɪkˈsperɪmənt/","tag":"noun / verb","definition":"a test carried out to find something out. Experimental is the adjective describing what belongs to such a test.","definitionCN":"为查明某事而做的测试；experimental 是描述属于此类测试的形容词。"},{"word":"experimentally","ipa":"/ɪkˌsperɪˈmentli/","tag":"adverb","definition":"by means of an experiment. It says how a result was obtained.","definitionCN":"通过实验方式；说明结果是如何获得的。"},{"word":"experimentation","ipa":"/ɪkˌsperɪmenˈteɪʃn/","tag":"noun","definition":"the activity or process of experimenting. It names the practice, not a single trial.","definitionCN":"实验活动或过程；命名实践，而非单次试验。"},{"word":"experimentalist","ipa":"/ɪkˌsperɪˈmentəlɪst/","tag":"person noun","definition":"a person who relies on experiment, especially in art or science. It labels the practitioner.","definitionCN":"依赖实验的人，尤指艺术或科学中；标记实践者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"empirical","ipa":"/ɪmˈpɪrɪkl/","tag":"data-based","definition":"based on observation or experience rather than theory. It is broader than experimental and can include field data.","definitionCN":"以观察或经验而非理论为依据；比 experimental 更宽，可包含野外数据。"},{"word":"tentative","ipa":"/ˈtentətɪv/","tag":"provisional","definition":"not final; done as a first attempt. It stresses uncertainty rather than method.","definitionCN":"非最终的；作为初次尝试的；强调不确定性，而非方法。"},{"word":"pilot","ipa":"/ˈpaɪlət/","tag":"small-scale trial","definition":"describing a small version of a project used to test it. It is experimental work at reduced scale.","definitionCN":"形容用于测试项目的小规模版本；是缩小规模的实验性工作。"},{"word":"trial","ipa":"/ˈtraɪəl/","tag":"test period","definition":"a period in which something is tested. It is the practical occasion, while experimental is the property.","definitionCN":"对某物进行测试的时期；是实际场合，experimental 是属性。"},{"word":"innovative","ipa":"/ˌɪnəˈveɪtɪv/","tag":"new method","definition":"introducing new ideas or methods. It praises novelty; it does not necessarily imply testing.","definitionCN":"引入新想法或新方法；赞美新颖，不一定暗示经过检验。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: experiment plus -al. The word marks knowledge or practice that comes from a trial, and therefore remains provisional.","cn":"只用真实成分：experiment 加 -al。这个词标记来自试验的知识或实践，因此仍是暂定的。"},"normal":[{"en":"Experiment plus -al: experimental means produced by a trial.","cn":"experiment 加 -al：experimental 就是‘由试验产生的’。"},{"en":"A control group is the quiet half of an experimental design.","cn":"对照组是 experimental design 里安静的那一半。"},{"en":"An experimental drug is a promise with a warning attached.","cn":"experimental 药物是一个附带警告的承诺。"},{"en":"Experimental art treats the audience as its apparatus.","cn":"实验艺术把观众当作自己的仪器。"},{"en":"An experimental schedule is adjusted weekly, because each week is data.","cn":"试验性日程每周调整，因为每一周都是数据。"}],"abstract":[{"en":"To call something experimental is to admit that the outcome is not yet known.","cn":"把某物称为 experimental，就是承认结果尚不可知。"},{"en":"Every experiment chooses a variable; the choice is a theory in disguise.","cn":"每个实验都要选择变量；这个选择是伪装成操作的理论。"},{"en":"The word moves between lab and studio because both test by making.","cn":"这个词在实验室与工作室之间移动，因为两者都通过‘做’来检验。"}]},"examples":[{"en":"The experimental group improved, but the difference was small.","cn":"实验组有所改善，但差异很小。"},{"en":"The city ran an experimental bus route for six months.","cn":"这座城市试运行了一条公交线路六个月。"},{"en":"His experimental novel was praised more than it was read.","cn":"他那部实验小说得到的赞誉多于读者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗死，配一闷头”——实验里一颗对照组死了，另一组闷头记录：experimental 实验的。","word":"experimental"},"root":"由 experiment 加 -al 构成；experiment 源自拉丁 experimentum（试验、检验），源头 experiri（尝试）。更深的 per- 词根联系属重构，宜标“一般认为是”。","sensesIntro":{"en":"Eight senses of experimental, one condition: the result is produced by a trial and is not yet settled. The trial may be a lab run, a drug protocol, a research method, an art form, or a weekly adjustment.","cn":"experimental 的八个义项共有一个条件：结果由试验产生，且尚未定论。试验可以是实验室运行、药物方案、研究方法、艺术形式或每周调整。"},"semanticMap":{"core":{"en":"CORE IMAGE: two rigs side by side, identical except for one changed variable.","cn":"核心意象：两套并排的装置，除一个变量外完全相同。"},"chain":["LATIN EXPERIRI = TO TRY, TEST","EXPERIMENTUM = A TRIAL, A PROOF","EXPERIMENT = A CONTROLLED TEST","EXPERIMENTAL = BELONGING TO A TEST","THE RESULT IS PROVISIONAL","ANY PRACTICE THAT PROCEEDS BY TRIAL"],"branches":[{"senses":"01 · 04 · 06","en":"THE METHOD: evidence, a scientific branch, and empirical psychology all settle claims by controlled trial.","cn":"方法：证据、科学分支与实证心理学都用受控试验来定案。"},{"senses":"02 · 07","en":"THE PROVISIONAL STATUS: an unapproved drug and a tentative scheme both exist without a settled verdict.","cn":"暂定地位：未获批药物与试探性方案都存在，但尚无定论。"},{"senses":"03","en":"THE APPARATUS: a rig or a plot belongs to the test arrangement.","cn":"装置：实验台或地块属于测试安排的一部分。"},{"senses":"05","en":"THE ARTISTIC TRIAL: avant-garde work tests forms by making them.","cn":"艺术试验：前卫作品通过‘做出来’来检验形式。"},{"senses":"08","en":"THE STRATEGY: small steps are treated as information for the next step.","cn":"策略：小步行动被当作下一步的信息。"}]},"affixes":{"intro":{"en":"Experimental is experiment plus -al. The family includes the adverb experimentally, the practice noun experimentation, and the person nouns experimenter and experimentalist.","cn":"experimental 是 experiment 加 -al。词族包括副词 experimentally、实践名词 experimentation，以及人物名词 experimenter 与 experimentalist。"},"latinIntro":{"en":"The attested Latin forms are experiri, experimentum, and expertus. The link to peritus and periculum is reconstructed and is best marked as generally accepted, not proven.","cn":"可证的拉丁形式是 experiri、experimentum、expertus。与 peritus、periculum 的联系属于重构，宜标“一般认为是”，而非已证。"},"items":[{"word":"experiment","structure":"Latin experimentum (trial, proof)","meaning":"a test carried out to discover something","meaningCN":"为发现某事而进行的试验","example":"The experiment was repeated three times.","exampleCN":"这个实验重复了三次。"},{"word":"experimental","structure":"experiment + -al (relational adjective)","meaning":"relating to or based on experiments","meaningCN":"与实验有关的；基于实验的","example":"The experimental results matched the prediction.","exampleCN":"实验结果与预测相符。"},{"word":"experimentally","structure":"experimental + -ly (adverb)","meaning":"by experimental means","meaningCN":"以实验方式","example":"The effect was confirmed experimentally.","exampleCN":"该效应已通过实验得到确认。"},{"word":"experimentation","structure":"experiment + -ation (action noun)","meaning":"the activity of conducting experiments","meaningCN":"实验活动；试验","example":"Years of experimentation produced the new alloy.","exampleCN":"多年实验造出了这种新合金。"},{"word":"experimentalist","structure":"experimental + -ist (person noun)","meaning":"one who works by experiment","meaningCN":"实验研究者；实验主义者","example":"The film was made by an experimentalist.","exampleCN":"这部影片由一位实验派作者拍摄。"},{"word":"experimenter","structure":"experiment + -er (agent noun)","meaning":"the person who runs an experiment","meaningCN":"实验者；实验执行者","example":"The experimenter recorded every reading.","exampleCN":"实验者记录了每一次读数。"},{"word":"expert","structure":"Latin expertus (having tried) < experiri","meaning":"a person with special knowledge","meaningCN":"专家；有专门知识的人（本义‘试过的人’）","example":"The expert had tested the material herself.","exampleCN":"这位专家亲自测试过该材料。"},{"word":"experience","structure":"Latin experientia < experiri","meaning":"knowledge gained by doing or undergoing","meaningCN":"通过实践或经历获得的知识","example":"Experience taught her to check the seals twice.","exampleCN":"经验教会她检查两次封条。"},{"word":"peril","structure":"Latin periculum (trial, danger); link to experiri is generally accepted but reconstructed","meaning":"serious danger","meaningCN":"严重危险（与 experiri 的联系属一般认为，非已证）","example":"The climb put them in real peril.","exampleCN":"这次攀登让他们陷入真正的危险。"},{"word":"perilous","structure":"peril + -ous (adjective)","meaning":"full of danger","meaningCN":"危险的","example":"The path was perilous after the storm.","exampleCN":"暴风雨后那条路很危险。"}],"latinEntries":[{"word":"experiri","structure":"Latin deponent verb","meaning":"to try, test, experience","meaningCN":"尝试；检验；经历"},{"word":"experimentum","structure":"experi- + -mentum (result noun)","meaning":"a trial, test, proof","meaningCN":"试验；检验；证明"},{"word":"periculum","structure":"Latin noun","meaning":"trial, danger; connection to experiri is reconstructed","meaningCN":"试炼；危险（与 experiri 的联系属重构）"}]}},{"word":"experimentally","ipa_uk":"/ɪkˌsperɪˈmentli/","ipa_us":"/ˌeksperɪˈmentəli/","definition_zh":"以实验方式；实验性地；在实验中；通过实验证明地","definition_en":"by means of an experiment, or in a tentative way that is still being tested","core_image":"一只手在记录本上写下“第 3 次试验”，旁边是刚刚调好的仪器刻度。","scene":"论文的方法部分说明这个效应不是靠推算。The methods section says the effect was measured experimentally rather than inferred.","sceneCN":"这里 experimentally 是「通过实验方式测定」（第 1、8 个义项）；句意：方法部分写明，这个效应是通过实验测得的，而不是靠推算。","pos":[{"tag":"adv.","zh":"以实验方式；实验性地；通过实验地"}],"collocations":[{"phrase":"verified experimentally","zh":"经实验验证"},{"phrase":"measured experimentally","zh":"通过实验测量"},{"phrase":"determined experimentally","zh":"由实验确定"},{"phrase":"tested experimentally","zh":"经实验测试"},{"phrase":"produced experimentally","zh":"通过实验制得"},{"phrase":"treat experimentally","zh":"以试验方式处理"}],"forms":[{"label":"原级（副词）","form":"experimentally"},{"label":"比较级（用 more）","form":"more experimentally"},{"label":"最高级（用 most）","form":"most experimentally"},{"label":"形容词形式","form":"experimental"}],"derivatives":[{"word":"experimental","pos":"adj.","zh":"实验的；试验性的"},{"word":"experiment","pos":"n./v.","zh":"实验；做实验"},{"word":"experimentation","pos":"n.","zh":"实验活动"},{"word":"experimenter","pos":"n.","zh":"实验者"}],"senses":[{"no":"01","title":"By experimental means","titleCN":"以实验方式：靠动手试验而非推理","definition":"by carrying out an experiment rather than by reasoning alone","definitionCN":"通过进行实验而非仅靠推理地","example":"The hypothesis was tested experimentally, not argued from first principles.","exampleCN":"该假设是通过实验检验的，而不是从基本原理推出来的。","why":"The adverb answers the question How was this found out? The answer is a procedure: someone built a test and ran it.","whyCN":"这个副词回答‘这是怎么知道的？’答案是程序：有人搭了测试并运行它。"},{"no":"02","title":"In the course of an experiment","titleCN":"在实验中：作为实验过程的一部分","definition":"in the course of an experiment, as part of its procedure","definitionCN":"在实验过程中，作为其程序的一部分","example":"The samples were handled experimentally under sterile conditions.","exampleCN":"这些样本在无菌条件下按实验规程处理。","why":"Here the adverb places an action inside the experiment: the action is not merely tested, it belongs to the test's internal sequence.","whyCN":"这里副词把动作放进实验内部：该动作不只是被检验，它属于实验内部的步骤序列。"},{"no":"03","title":"Confirmed by experiment","titleCN":"经实验证明地：结果站住了","definition":"in a way that has been confirmed by experimental results","definitionCN":"已被实验结果确认地","example":"The prediction was confirmed experimentally in two independent labs.","exampleCN":"该预测在两个独立实验室中经实验得到确认。","why":"The adverb can mark epistemic status: the claim is not just tested but has passed the test, at least so far.","whyCN":"这个副词可以标记认识论地位：该主张不只是被测试，而是通过了测试，至少截至目前。"},{"no":"04","title":"Tentatively, as a trial","titleCN":"试验性地：先试一段时间再定","definition":"in a tentative way, as a trial rather than a final arrangement","definitionCN":"以试探方式，作为试验而非最终安排地","example":"The team experimentally moved the meeting to Friday.","exampleCN":"团队试验性地把会议改到了周五。","why":"Here the word has escaped the laboratory: any provisional action can be done experimentally, with the option of reversing it.","whyCN":"这里这个词已经离开实验室：任何暂定行动都可以 experimental 地做，并保留撤回的选项。"},{"no":"05","title":"Methodologically","titleCN":"在方法上：用实验法而非观察法","definition":"with respect to experimental method, as opposed to observation or theory","definitionCN":"就实验方法而言，相对于观察或理论地","example":"The two groups were compared experimentally and statistically.","exampleCN":"两组分别从实验和统计上作了比较。","why":"The adverb can distinguish a methodology from its neighbours: field observation records what happens, experimental work makes something happen.","whyCN":"这个副词可以把一种方法论与邻居区分开：野外观察记录发生什么，实验工作则让某事发生。"},{"no":"06","title":"In a clinical trial","titleCN":"在临床试验中：作为受试方案","definition":"as part of a clinical trial or an investigational treatment","definitionCN":"作为临床试验或研究性治疗的一部分地","example":"The patient was treated experimentally under a strict protocol.","exampleCN":"病人在严格方案下接受了试验性治疗。","why":"Medicine uses the adverb for care delivered inside a trial, where the protocol defines what may and may not be done.","whyCN":"医学用这个副词指在试验内部提供的照护；方案定义了可以做什么、不可以做什么。"},{"no":"07","title":"In an experimental art practice","titleCN":"在实验艺术中：以作品作为试验","definition":"in an avant-garde or trial-based artistic practice","definitionCN":"以前卫或试验为基础的艺术实践中","example":"The composer worked experimentally with recorded noise.","exampleCN":"这位作曲家以实验方式处理录制噪声。","why":"The adverb transfers the lab attitude to art: the work is made to see what happens, and failure is allowed to remain visible.","whyCN":"这个副词把实验室态度转到艺术上：作品被做出来是为了看会发生什么，失败被允许留在明处。"},{"no":"08","title":"Measured by experiment","titleCN":"以实验测定地：数值来自装置","definition":"by a measurement obtained through experimental apparatus","definitionCN":"通过实验装置获得的测量地","example":"The constant was determined experimentally to four decimal places.","exampleCN":"该常数由实验测定到四位小数。","why":"Here the focus is the number's origin: it came from an instrument and a procedure, not from a table or a calculation.","whyCN":"这里聚焦数值的来源：它来自仪器与程序，而不是表格或计算。"}],"etymology":{"intro":{"en":"Experimentally is experimental plus -ly. The adjective comes from experiment, from Latin experimentum, a trial. The suffix -ly descends from Old English -lice.","cn":"experimentally 是 experimental 加 -ly。形容词来自 experiment，源头是拉丁 experimentum‘试验’。后缀 -ly 源自古典英语 -lice。"},"items":[{"era":"LATIN experiri","en":"To try or test. Its past participle expertus also gives English expert: an expert is literally someone who has tried things.","cn":"尝试、检验。其过去分词 expertus 也给出英语 expert：专家字面上就是‘试过事情的人’。"},{"era":"LATIN experimentum","en":"A trial, test, or proof. The noun names both the procedure and the evidence it produces.","cn":"试验、检验、证明。该名词既命名程序，也命名程序产生的证据。"},{"era":"ENGLISH experiment","en":"Borrowed in the 14c. Its meaning narrowed as the controlled method developed: a trial that deliberately changes one variable.","cn":"14 世纪借入。随着受控方法发展，词义收窄为‘有意改变一个变量的试验’。"},{"era":"ENGLISH experimental","en":"The adjective appears in the 17c with the rise of demonstrative science. It marks both the method and the provisional status of the result.","cn":"形容词随 17 世纪演示科学兴起而出现。它同时标记方法与结果的暂定地位。"},{"era":"ENGLISH -ly","en":"The adverb suffix -ly comes from Old English -lice, originally a distinct word meaning ‘body’ or ‘form’. It became the regular way to turn adjectives into manner adverbs.","cn":"副词后缀 -ly 来自古典英语 -lice，原是一个意为‘身体、形态’的独立词，后来成为把形容词变方式副词的常规手段。"},{"era":"MODERN ENGLISH","en":"The adverb spread from scientific writing into medicine, management, and art, wherever an action is described as a trial rather than a settled practice.","cn":"这个副词从科学写作扩展到医学、管理与艺术：凡是把行动描述为试验而非既定做法的地方都能用。"}]},"similar":{"note":{"en":"The first group is the experiment family; the second compares adverbs for how a claim is established or how cautiously an action is taken.","cn":"第一组是 experiment 词族；第二组比较表示‘如何确立主张’或‘行动有多谨慎’的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"experimental","ipa":"/ɪkˌsperɪˈmentl/","tag":"adjective","definition":"relating to or based on an experiment. The adverb applies that property to the manner of an action.","definitionCN":"与实验有关或基于实验的；副词把这一属性加到动作方式上。"},{"word":"experiment","ipa":"/ɪkˈsperɪmənt/","tag":"noun / verb","definition":"a test, or to carry out a test. The adverb says the action was done through such a test.","definitionCN":"试验，或进行试验；副词说明动作是通过这种试验完成的。"},{"word":"experimentation","ipa":"/ɪkˌsperɪmenˈteɪʃn/","tag":"noun","definition":"the practice of experimenting. It is the activity; experimentally is the manner.","definitionCN":"进行实验的实践；是活动，experimentally 是方式。"},{"word":"experimenter","ipa":"/ɪkˈsperɪmentə/","tag":"person noun","definition":"the person who runs the test. It names the agent behind the adverb.","definitionCN":"运行测试的人；命名副词背后的施动者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"empirically","ipa":"/ɪmˈpɪrɪkli/","tag":"from observation","definition":"by observation or experience rather than theory. It is broader than experimentally and includes field evidence.","definitionCN":"通过观察或经验而非理论；比 experimentally 更宽，包含野外证据。"},{"word":"tentatively","ipa":"/ˈtentətɪvli/","tag":"provisionally","definition":"in a cautious, provisional way. It stresses hesitation rather than procedure.","definitionCN":"以谨慎、暂定的方式；强调犹豫，而非程序。"},{"word":"practically","ipa":"/ˈpræktɪkli/","tag":"in practice","definition":"in actual practice rather than in theory. It contrasts with theory, not with observation.","definitionCN":"在实际做法中而非理论上；与理论相对，而非与观察相对。"},{"word":"analytically","ipa":"/əˈnælɪtɪkli/","tag":"by analysis","definition":"by breaking a problem into parts. It is a desk method, often the opposite of hands-on testing.","definitionCN":"把问题拆成部分来处理；是书桌方法，常与动手测试相对。"},{"word":"theoretically","ipa":"/θiəˈretɪkli/","tag":"by theory","definition":"according to theory, or in principle. It marks the opposite source of knowledge to experimentally.","definitionCN":"根据理论，或原则上；标记与 experimentally 相对的知识来源。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: experimental plus -ly. The adverb says the action was done through a trial, or as a trial.","cn":"只用真实成分：experimental 加 -ly。这个副词说明动作是通过试验完成的，或本身就作为试验。"},"normal":[{"en":"Experimental plus -ly: in the manner of a test.","cn":"experimental 加 -ly：以测试的方式。"},{"en":"Measured experimentally: the number came out of a machine, not a table.","cn":"measured experimentally：数字来自机器，不是表格。"},{"en":"Confirmed experimentally: the claim survived contact with apparatus.","cn":"confirmed experimentally：主张经受住了与仪器的接触。"},{"en":"Treated experimentally: the protocol, not the clinic routine, decides.","cn":"treated experimentally：由方案决定，而不是门诊常规。"},{"en":"Moved experimentally: try Friday, and be ready to move it back.","cn":"moved experimentally：先试周五，并准备好改回来。"}],"abstract":[{"en":"Experimentally is a confession about the source of a claim: hands made it, not arguments.","cn":"experimentally 是对主张来源的坦白：是手做出来的，不是论证出来的。"},{"en":"The adverb quietly ranks knowledge: what is experimentally shown can still be overturned by a better experiment.","cn":"这个副词在悄悄给知识排序：实验证明的东西，仍可能被更好的实验推翻。"},{"en":"A society that values experimentally also has to tolerate failure, because trial and failure are one word.","cn":"重视 experimentally 的社会也必须容忍失败，因为试验与失败是同一个词的两面。"}]},"examples":[{"en":"The viscosity was determined experimentally at three temperatures.","cn":"黏度在三个温度下通过实验测定。"},{"en":"They experimentally introduced a four-day week and measured the effect on output.","cn":"他们试验性地引入四天工作制，并测量对产出的影响。"},{"en":"The drug was used experimentally long before it was approved.","cn":"这种药在获批之前很久就被试验性使用了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗死，配一闷头，里”——实验里一组死、一组闷头记录，里里外外都试过：experimentally 以实验方式。","word":"experimentally"},"root":"由 experimental 加 -ly 构成；experimental 源自拉丁 experimentum（试验），源头 experiri（尝试）。核心是“以试验的方式”或“作为试验地”。","sensesIntro":{"en":"Eight senses of experimentally, one answer to How: through a test, inside a test, confirmed by a test, as a test, by test method, in a trial, in experimental art, or by instrument. The manner changes; the trial remains.","cn":"experimentally 的八个义项都在回答‘如何’：通过试验、在试验内、经试验确认、作为试验、用实验法、在临床试验中、在实验艺术中、用仪器测定。方式在变，试验不变。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand writing run number three beside a freshly set instrument.","cn":"核心意象：一只手在刚调好的仪器旁写下‘第三次试验’。"},"chain":["LATIN EXPERIRI = TO TRY","EXPERIMENTUM = A TRIAL","EXPERIMENTAL = OF A TRIAL","EXPERIMENTALLY = IN A TRIAL MANNER","THE ACTION IS DONE THROUGH TESTING","ANY PROVISIONAL, TEST-BASED MANNER"],"branches":[{"senses":"01 · 05","en":"THE METHOD: the claim is produced by procedure rather than by argument.","cn":"方法：主张由程序产生，而非由论证产生。"},{"senses":"02","en":"INSIDE THE TRIAL: actions belong to the protocol rather than to ordinary life.","cn":"试验进程内：动作属于既定方案，而不属于日常生活。"},{"senses":"03 · 08","en":"THE VERIFIED NUMBER: confirmation and measurement both trace back to apparatus.","cn":"被验证的数值：确认与测量都追溯回仪器。"},{"senses":"04 · 07","en":"THE PROVISIONAL ACT: a Friday meeting and a noise composition are both trials with reversible outcomes.","cn":"暂定行动：周五会议与噪声作曲都是结果可撤回的试验。"},{"senses":"06","en":"THE CONSENT FRAME: medicine uses the adverb to mark care delivered under study conditions.","cn":"知情同意框架：医学用这个副词标记在研究条件下提供的照护。"}]},"affixes":{"intro":{"en":"Experimentally is experimental plus -ly. The family runs from experiment and experimentation to experimentalist and experimenter.","cn":"experimentally 是 experimental 加 -ly。词族从 experiment、experimentation 延伸到 experimentalist 与 experimenter。"},"latinIntro":{"en":"The core Latin forms are experiri and experimentum, with the participle expertus behind English expert. The deeper per- connection is reconstructed.","cn":"核心拉丁形式是 experiri 与 experimentum，分词 expertus 是英语 expert 的来源。更深的 per- 联系属重构。"},"items":[{"word":"experiment","structure":"Latin experimentum (trial)","meaning":"a test, or to test","meaningCN":"实验；做实验","example":"They ran the experiment twice.","exampleCN":"他们把实验做了两次。"},{"word":"experimental","structure":"experiment + -al","meaning":"based on or belonging to a test","meaningCN":"实验的；试验性的","example":"The design is still experimental.","exampleCN":"这个设计仍是试验性的。"},{"word":"experimentally","structure":"experimental + -ly","meaning":"by experiment","meaningCN":"以实验方式","example":"The value was obtained experimentally.","exampleCN":"该数值是通过实验得到的。"},{"word":"experimentation","structure":"experiment + -ation","meaning":"the practice of testing","meaningCN":"实验活动；试验","example":"Experimentation preceded the final design.","exampleCN":"在最终设计之前先进行了实验。"},{"word":"experimenter","structure":"experiment + -er","meaning":"one who runs a test","meaningCN":"实验者","example":"The experimenter changed the order of trials.","exampleCN":"实验者改变了试验顺序。"},{"word":"experimentalist","structure":"experimental + -ist","meaning":"one devoted to experimental work","meaningCN":"实验研究者；实验派","example":"The composer is an experimentalist by habit.","exampleCN":"这位作曲家习惯上是实验派。"},{"word":"expert","structure":"Latin expertus (having tried)","meaning":"someone with tested knowledge","meaningCN":"专家；有经过检验的知识的人","example":"An expert reviewed the apparatus.","exampleCN":"一位专家检查了装置。"},{"word":"experience","structure":"Latin experientia (trial, practice)","meaning":"knowledge from doing","meaningCN":"经验；从实践得来的知识","example":"Experience is a long series of trials.","exampleCN":"经验是一长串试验。"},{"word":"peril","structure":"Latin periculum; link reconstructed","meaning":"danger","meaningCN":"危险（同源联系属重构）","example":"The sea ice was a known peril.","exampleCN":"海冰是已知的危险。"},{"word":"perilous","structure":"peril + -ous","meaning":"dangerous","meaningCN":"危险的","example":"The descent was perilous in the dark.","exampleCN":"黑暗中下撤很危险。"}],"latinEntries":[{"word":"experiri","structure":"Latin deponent verb","meaning":"to try, test","meaningCN":"尝试；检验"},{"word":"experimentum","structure":"experi- + -mentum","meaning":"a trial, proof","meaningCN":"试验；证明"},{"word":"expertus","structure":"past participle of experiri","meaning":"having tried, experienced","meaningCN":"已尝试过的；有经验的"}]}},{"word":"experimentation","ipa_uk":"/ɪkˌsperɪmenˈteɪʃn/","ipa_us":"/ˌeksperɪmenˈteɪʃən/","definition_zh":"实验；实验活动；试验；实验法","definition_en":"the activity or practice of conducting experiments, especially as a way of finding things out","core_image":"实验台上排着一列贴着日期的样品瓶，从最早发黄的一瓶到最新透明的一瓶。","scene":"研发主管说，新配方不是一次想出来的。The research director says the new formula came out of two years of experimentation, not one bright idea.","sceneCN":"这里 experimentation 是「反复进行实验的活动」（第 1、7 个义项）；句意：研发主管说，新配方不是一次想出来的，而是两年反复实验的结果。","pos":[{"tag":"n.","zh":"实验；实验活动；试验；实验法"}],"collocations":[{"phrase":"scientific experimentation","zh":"科学实验"},{"phrase":"animal experimentation","zh":"动物实验"},{"phrase":"years of experimentation","zh":"多年实验"},{"phrase":"human experimentation","zh":"人体实验"},{"phrase":"a period of experimentation","zh":"一段试验期"},{"phrase":"experimentation with new materials","zh":"对新材料的试验"}],"forms":[{"label":"复数（名词，较少用）","form":"experimentations"}],"derivatives":[{"word":"experiment","pos":"n./v.","zh":"实验；做实验"},{"word":"experimental","pos":"adj.","zh":"实验的；试验性的"},{"word":"experimentally","pos":"adv.","zh":"以实验方式"},{"word":"experimenter","pos":"n.","zh":"实验者"}],"senses":[{"no":"01","title":"The activity of experimenting","titleCN":"实验活动：反复做实验这件事","definition":"the activity or process of carrying out experiments","definitionCN":"进行实验的活动或过程","example":"The discovery came after months of patient experimentation.","exampleCN":"这一发现来自数月耐心的实验。","why":"Experimentation names the practice rather than one trial. It treats many experiments as a single continuous activity.","whyCN":"experimentation 命名的是一种实践，而不是单次试验。它把许多次实验当作一项连续活动。"},{"no":"02","title":"Trying out new ideas","titleCN":"试验：把新想法拿出来试一试","definition":"the act of trying new ideas, methods, or forms to see whether they work","definitionCN":"尝试新想法、新方法或新形式以检验是否可行","example":"The company encouraged experimentation with flexible hours.","exampleCN":"公司鼓励对弹性工时进行试验。","why":"The word leaves the lab and becomes social: a policy or a habit is treated as a hypothesis that can be revised.","whyCN":"这个词离开实验室，变成社会性的：一项政策或习惯被当作可修正的假设。"},{"no":"03","title":"Scientific laboratory work","titleCN":"科学实验工作：在实验室里成体系地试","definition":"systematic laboratory work aimed at testing hypotheses","definitionCN":"旨在检验假设的系统性实验室工作","example":"Scientific experimentation requires controls and records.","exampleCN":"科学实验需要对照与记录。","why":"Here the practice has rules: a control group, a protocol, and a record. Without them the activity is tinkering, not experimentation.","whyCN":"这里的实践有规则：对照组、方案与记录。没有这些，活动只是瞎捣鼓，而不是 experimentation。"},{"no":"04","title":"Experimental method","titleCN":"实验法：把实验当作认识方法","definition":"the use of experiment as a method of inquiry or a way of establishing knowledge","definitionCN":"把实验用作探究方法或确立知识的方式","example":"The rise of experimentation changed what counted as evidence.","exampleCN":"实验法的兴起改变了‘什么算证据’。","why":"This sense is methodological: experimentation is not one activity but a standard for how claims should be settled.","whyCN":"这个义项是方法论的：experimentation 不是一项活动，而是‘主张应如何定案’的标准。"},{"no":"05","title":"Human or animal testing","titleCN":"人体或动物实验：涉及伦理边界","definition":"the testing of medical treatments on humans or animals, especially when ethically regulated","definitionCN":"在人或动物身上测试医疗方法，尤指受伦理规管时","example":"Human experimentation is governed by consent and review boards.","exampleCN":"人体实验受知情同意与审查委员会规管。","why":"When the object is a living being, the word carries a moral weight: the trial is done on someone, not on a sample.","whyCN":"当对象是活着的生命时，这个词带有道德重量：试验是‘在某人身上’做的，而不是在样本上。"},{"no":"06","title":"Artistic experimentation","titleCN":"艺术实验：用作品试探形式边界","definition":"the practice of trying new forms and techniques in art, music, or writing","definitionCN":"在艺术、音乐或写作中尝试新形式与新手法的实践","example":"Her experimentation with collage began as a way to save paper.","exampleCN":"她对拼贴的实验最初只是为了省纸。","why":"The studio borrows the lab's freedom: a work may fail, and the failure is kept as part of the record.","whyCN":"工作室借用了实验室的自由：作品可以失败，而失败被保留为记录的一部分。"},{"no":"07","title":"Trial and error","titleCN":"反复试错：一次次改，直到可行","definition":"the process of trying many approaches and learning from failures","definitionCN":"尝试多种方法并从失败中学习的过程","example":"The recipe was perfected by experimentation, not by calculation.","exampleCN":"这个配方是靠反复试验完善起来的，不是靠计算。","why":"Here each failure is data. The activity is cumulative: what failed last time removes one option from the next attempt.","whyCN":"这里每次失败都是数据。活动是累积性的：上次失败的选项会从下一次尝试中被移除。"},{"no":"08","title":"Research and development","titleCN":"实验性研发：在投入生产前先试","definition":"testing carried out as part of research and development before full production","definitionCN":"在全面生产前作为研发一部分进行的测试","example":"Experimentation on the prototype delayed the launch by a year.","exampleCN":"对原型的试验让发布推迟了一年。","why":"Industry places experimentation between design and production: the cost of failure is paid early, while it is still small.","whyCN":"工业把 experimentation 放在设计与生产之间：失败的成本在还小时提前支付。"}],"etymology":{"intro":{"en":"Experimentation is experiment plus -ation, from Latin experimentum, a trial. It names the practice, while experiment names a single trial.","cn":"experimentation 是 experiment 加 -ation，源头是拉丁 experimentum‘试验’。它命名实践，而 experiment 命名单次试验。"},"items":[{"era":"LATIN experiri","en":"To try, test, or experience. The verb underlies experiment, expert, and experience, all of which involve having gone through something.","cn":"尝试、检验、经历。该动词支撑 experiment、expert 与 experience，三者都涉及‘经历过某事’。"},{"era":"LATIN experimentum","en":"A trial, test, or proof. The noun could also mean the evidence produced by a trial, which is why experiment and experience overlap in older English.","cn":"试验、检验、证明。该名词也可指试验产生的证据，因此在早期英语中 experiment 与 experience 有重叠。"},{"era":"FRENCH experiment","en":"Old French passed the noun to English in the 14c. The modern scientific sense grew in the 17c with controlled procedure.","cn":"古法语在 14 世纪把名词传给英语。现代科学义项随 17 世纪受控程序发展起来。"},{"era":"ENGLISH experimentation","en":"The action noun experimentation appears later, in the 17c-18c, when the practice itself needed a name distinct from a single test.","cn":"动作名词 experimentation 较晚出现，约在 17 至 18 世纪；此时这种实践本身需要一个区别于单次测试的名字。"},{"era":"LATIN -atio","en":"The suffix -ation comes from Latin -atio, an action or process noun. It turns the countable experiment into an uncountable practice.","cn":"后缀 -ation 来自拉丁 -atio，构成动作或过程名词。它把可数的 experiment 变成不可数的实践。"},{"era":"MODERN ENGLISH","en":"The 19c-20c extended the noun to medicine, industry, and art, and to ethical debates about testing on living beings.","cn":"19 至 20 世纪，该名词扩展到医学、工业与艺术，也进入关于在活体上试验的伦理争论。"}]},"similar":{"note":{"en":"The first group is the experiment family; the second compares nouns for systematic trying, each with a different scope or setting.","cn":"第一组是 experiment 词族；第二组比较表示‘系统尝试’的名词，各自范围或场景不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"experiment","ipa":"/ɪkˈsperɪmənt/","tag":"countable noun","definition":"one test with a defined procedure. Experimentation is the activity made of many such tests.","definitionCN":"一次有明确程序的测试；experimentation 是由许多此类测试构成的活动。"},{"word":"experimental","ipa":"/ɪkˌsperɪˈmentl/","tag":"adjective","definition":"belonging to a test, or still untested. It describes the status of a thing.","definitionCN":"属于试验的，或尚未定论的；描述事物的状态。"},{"word":"experimentally","ipa":"/ɪkˌsperɪˈmentli/","tag":"adverb","definition":"by means of a test. It describes the manner of an action.","definitionCN":"通过试验方式；描述动作的方式。"},{"word":"experimenter","ipa":"/ɪkˈsperɪmentə/","tag":"person noun","definition":"the one who performs the test. It names the agent of experimentation.","definitionCN":"执行测试的人；命名 experimentation 的施动者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"testing","ipa":"/ˈtestɪŋ/","tag":"checking performance","definition":"the process of checking whether something works or meets a standard. It is broader and often routine.","definitionCN":"检查某物是否有效或达标的过程；更宽泛，常是常规性的。"},{"word":"trial","ipa":"/ˈtraɪəl/","tag":"a test period","definition":"a single occasion or period of testing. It can be countable, unlike experimentation.","definitionCN":"单次或一段时间的测试；可数，而 experimentation 通常不可数。"},{"word":"research","ipa":"/rɪˈsɜːtʃ/","tag":"systematic study","definition":"systematic investigation to discover knowledge. Experimentation is one of its methods, not the whole.","definitionCN":"为发现知识而进行的系统研究；experimentation 只是其方法之一，不是全部。"},{"word":"inquiry","ipa":"/ɪnˈkwaɪəri/","tag":"asking and investigating","definition":"a search for information or truth. It need not involve apparatus at all.","definitionCN":"对信息或真相的探寻；完全可以不涉及仪器。"},{"word":"trial and error","ipa":"/ˌtraɪəl ən ˈerə/","tag":"method by failure","definition":"a method of reaching a solution by repeated attempts and mistakes. It emphasizes failure rather than design.","definitionCN":"通过反复尝试与错误达到解决的方法；强调失败，而非设计。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: experiment plus -ation. The suffix turns one trial into a practice made of many trials.","cn":"只用真实成分：experiment 加 -ation。后缀把一次试验变成由许多次试验构成的实践。"},"normal":[{"en":"Experiment plus -ation: one test becomes a way of working.","cn":"experiment 加 -ation：一次测试变成一种工作方式。"},{"en":"A shelf of dated sample bottles is experimentation made visible.","cn":"一排放着日期的样品瓶，就是看得见的 experimentation。"},{"en":"Scientific experimentation needs a control or it is only tinkering.","cn":"科学实验需要对照，否则只是瞎捣鼓。"},{"en":"Human experimentation adds consent to the apparatus.","cn":"人体实验在仪器之外还要加上知情同意。"},{"en":"Trial and error is experimentation without a theory, but still with records.","cn":"反复试错是没有理论的 experimentation，但仍有记录。"}],"abstract":[{"en":"Experimentation is a way of letting the world answer back.","cn":"experimentation 是一种让世界回话的方式。"},{"en":"The practice needs failure to be useful; a test that cannot fail teaches nothing.","cn":"这种实践需要失败才有用；不会失败的测试什么也教不了。"},{"en":"Calling something experimentation is a claim about humility: the answer is not yet in.","cn":"把某事称为 experimentation，是一种谦逊声明：答案还没到手。"}]},"examples":[{"en":"Decades of experimentation with drought-resistant crops finally paid off.","cn":"数十年对耐旱作物的试验终于有了回报。"},{"en":"The rules on human experimentation were tightened after the trial.","cn":"那次试验之后，人体实验的规则被收紧了。"},{"en":"Her early paintings show a period of restless experimentation.","cn":"她早期的画作显示出一段不安分的实验期。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一颗死，配一闷头，来神”——实验里一组死、一组闷头，突然来神了：experimentation 实验。","word":"experimentation"},"root":"由 experiment 加 -ation 构成；experiment 源自拉丁 experimentum（试验、检验），源头 experiri（尝试）。核心是“把一次次试验累积成一种实践”。","sensesIntro":{"en":"Eight senses of experimentation, one practice: many trials treated as a single activity. The trials may be lab runs, policy attempts, clinical protocols, artistic tests, or factory prototypes.","cn":"experimentation 的八个义项共用一种实践：把许多次试验当作一项活动。试验可以是实验室运行、政策尝试、临床方案、艺术测试或工厂原型。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of dated sample bottles, each the record of one attempt.","cn":"核心意象：一排放着日期的样品瓶，每一瓶都是一次尝试的记录。"},"chain":["LATIN EXPERIRI = TO TRY","EXPERIMENTUM = A TRIAL","EXPERIMENT = ONE TEST","EXPERIMENTATION = THE PRACTICE OF TESTING","MANY TRIALS BECOME ONE ACTIVITY","ANY SUSTAINED TRYING OUT OF IDEAS"],"branches":[{"senses":"01 · 07","en":"THE CUMULATIVE PRACTICE: months of trials and trial-and-error both accumulate into knowledge.","cn":"累积实践：数月试验与反复试错都累积成知识。"},{"senses":"02 · 06","en":"THE SOCIAL AND ARTISTIC TRIAL: policies and artworks are tested outside the lab.","cn":"社会与艺术试验：政策与作品在实验室之外接受检验。"},{"senses":"03 · 04","en":"THE METHOD: controls, records, and a standard for evidence turn activity into science.","cn":"方法：对照、记录与证据标准把活动变成科学。"},{"senses":"05","en":"THE ETHICAL BORDER: testing on living beings adds consent and review.","cn":"伦理边界：在活体上试验要加上知情同意与审查。"},{"senses":"08","en":"THE INDUSTRIAL STAGE: prototypes are tested before the cost of failure grows.","cn":"工业阶段：原型在失败成本变大之前先被测试。"}]},"affixes":{"intro":{"en":"Experimentation is experiment plus -ation, an action-noun suffix from Latin -atio. The family also includes experimental, experimentally, and experimenter.","cn":"experimentation 是 experiment 加 -ation，后者是来自拉丁 -atio 的动作名词后缀。词族还包括 experimental、experimentally 与 experimenter。"},"latinIntro":{"en":"The attested Latin forms are experiri and experimentum, with the participle expertus. The suffix -atio is a real Latin action-noun ending.","cn":"可证的拉丁形式是 experiri 与 experimentum，以及分词 expertus。后缀 -atio 是真实的拉丁动作名词词尾。"},"items":[{"word":"experiment","structure":"Latin experimentum (trial)","meaning":"one test","meaningCN":"一次实验；试验","example":"The experiment took ten minutes.","exampleCN":"这个实验花了十分钟。"},{"word":"experimentation","structure":"experiment + -ation","meaning":"the activity of testing","meaningCN":"实验活动；试验实践","example":"Experimentation continued for three years.","exampleCN":"实验持续了三年。"},{"word":"experimental","structure":"experiment + -al","meaning":"belonging to a test","meaningCN":"实验的；试验性的","example":"The method is still experimental.","exampleCN":"该方法仍是试验性的。"},{"word":"experimentally","structure":"experimental + -ly","meaning":"by test","meaningCN":"以实验方式","example":"The effect was shown experimentally.","exampleCN":"该效应已通过实验显示。"},{"word":"experimenter","structure":"experiment + -er","meaning":"one who tests","meaningCN":"实验者","example":"The experimenter kept a log.","exampleCN":"实验者保留了一本日志。"},{"word":"experimentalist","structure":"experimental + -ist","meaning":"one who favours experimental work","meaningCN":"实验派；实验研究者","example":"The laboratory hired an experimentalist.","exampleCN":"实验室聘用了一位实验研究者。"},{"word":"expert","structure":"Latin expertus","meaning":"one with tested knowledge","meaningCN":"专家","example":"The expert checked the calibration.","exampleCN":"专家检查了校准。"},{"word":"experience","structure":"Latin experientia","meaning":"knowledge from practice","meaningCN":"经验","example":"Experience came from repeated testing.","exampleCN":"经验来自反复测试。"},{"word":"peril","structure":"Latin periculum; link reconstructed","meaning":"danger","meaningCN":"危险（同源联系属重构）","example":"The experiment carried little peril.","exampleCN":"这个实验危险性很小。"},{"word":"perilous","structure":"peril + -ous","meaning":"dangerous","meaningCN":"危险的","example":"The route was perilous in winter.","exampleCN":"这条路在冬天很危险。"}],"latinEntries":[{"word":"experiri","structure":"Latin deponent verb","meaning":"to try, test","meaningCN":"尝试；检验"},{"word":"experimentum","structure":"experi- + -mentum","meaning":"a trial, proof","meaningCN":"试验；证明"},{"word":"-atio","structure":"Latin action-noun suffix","meaning":"the act or process of doing","meaningCN":"动作或过程名词后缀"}]}},{"word":"explanation","ipa_uk":"/ˌekspləˈneɪʃn/","ipa_us":"/ˌekspləˈneɪʃən/","definition_zh":"解释；说明；原因；辩解；释义","definition_en":"a statement or account that makes something clear or gives the reason for it","core_image":"一团缠住的线被一点点捋平，摊在桌面上，每一段都看得清来路。","scene":"学生问为什么天空是蓝的，老师先画了一张光散射的示意图。When a student asks why the sky is blue, the teacher draws a diagram of light scattering and then gives the explanation.","sceneCN":"这里 explanation 是「使某事变得清楚的说明」（第 1 个义项：使某事更容易理解的陈述或说明）；句意：学生问天空为什么是蓝的，老师先画光散射示意图，再给出解释。","pos":[{"tag":"n.","zh":"解释；说明；原因；辩解；释义"}],"collocations":[{"phrase":"a plausible explanation","zh":"一个说得通的解释"},{"phrase":"the explanation for","zh":"对……的解释／原因"},{"phrase":"a detailed explanation","zh":"详细的说明"},{"phrase":"demand an explanation","zh":"要求解释"},{"phrase":"a scientific explanation","zh":"科学解释"},{"phrase":"a simple explanation","zh":"简单的解释"},{"phrase":"an explanation of the text","zh":"对文本的释义"}],"forms":[{"label":"复数（名词）","form":"explanations"}],"derivatives":[{"word":"explain","pos":"v.","zh":"解释；说明"},{"word":"explanatory","pos":"adj.","zh":"解释性的；说明的"},{"word":"explainable","pos":"adj.","zh":"可解释的"},{"word":"inexplicable","pos":"adj.","zh":"无法解释的；难以理解的"}],"senses":[{"no":"01","title":"Making something clear","titleCN":"解释：把不清楚的讲清楚","definition":"a statement or account that makes something easier to understand","definitionCN":"使某事更容易理解的陈述或说明","example":"She gave a clear explanation of how the pump works.","exampleCN":"她清楚地解释了泵的工作原理。","why":"The Latin verb means to flatten out. An explanation lays a tangled matter flat so that its parts can be seen in order.","whyCN":"拉丁动词意为‘摊平’。解释把缠乱的事情摊平，让人按顺序看见它的各部分。"},{"no":"02","title":"The stated reason","titleCN":"理由：回答“为什么会这样”","definition":"the reason or reasons given for an event, action, or situation","definitionCN":"为事件、行动或状况给出的原因","example":"The explanation for the delay was a broken signal.","exampleCN":"延误的原因是信号故障。","why":"Here the word answers Why. It supplies a cause that fits the facts and removes the surprise.","whyCN":"这里这个词回答‘为什么’。它提供一个与事实相符的原因，从而消除惊讶。"},{"no":"03","title":"Justifying account","titleCN":"辩解：为自己的行为给出一套说法","definition":"an account offered to justify behaviour or defend against blame","definitionCN":"为行为辩护或抵御指责而提供的说法","example":"His explanation did not convince the committee.","exampleCN":"他的解释没有说服委员会。","why":"This sense is social: the account is addressed to someone who is judging, so it must be acceptable as well as true.","whyCN":"这个义项是社会性的：说法是说给评判者听的，因此除了真实，还必须可被接受。"},{"no":"04","title":"Scientific explanation","titleCN":"科学解释：用机制与规律说明现象","definition":"a account of a phenomenon in terms of mechanisms, causes, or laws","definitionCN":"用机制、原因或规律说明某一现象的说法","example":"A scientific explanation of the flare invoked magnetic reconnection.","exampleCN":"对这次耀斑的科学解释引用了磁重联。","why":"Science does not accept just any cause; the explanation must specify a mechanism that could produce the observed result.","whyCN":"科学不接受随便一个原因；解释必须给出一个能够产生观测结果的机制。"},{"no":"05","title":"Teaching exposition","titleCN":"讲解：课堂上把知识拆开讲","definition":"the act of explaining a subject to a learner in a structured way","definitionCN":"以有结构的方式向学习者讲解某一主题","example":"The teacher's explanation of fractions used two apples and a knife.","exampleCN":"老师用两个苹果和一把刀讲解分数。","why":"A good explanation is built for a particular listener: it starts from what they know and adds one step at a time.","whyCN":"好的讲解是为特定听者造的：从他们已知的地方开始，一次只加一步。"},{"no":"06","title":"Meaning of a text","titleCN":"释义：说明词句或文本的含义","definition":"an interpretation or statement of what a word, sentence, or text means","definitionCN":"对词、句或文本含义的阐释","example":"The edition adds an explanation of each archaic term.","exampleCN":"该版本对每个古旧词都加了释义。","why":"Here the unclear thing is language itself; the explanation translates one set of signs into another that the reader already understands.","whyCN":"这里不清楚的东西是语言本身；解释把一套符号翻译成读者已经理解的另一套符号。"},{"no":"07","title":"A cause in nature","titleCN":"自然原因：现象背后的成因","definition":"the cause or process responsible for a natural phenomenon","definitionCN":"造成某一自然现象的原因或过程","example":"The explanation of the tide lies in the moon's gravity.","exampleCN":"潮汐的成因在于月球的引力。","why":"This sense treats explanation as something the world contains, not something a person says: the cause itself is the explanation.","whyCN":"这个义项把解释当作世界所包含的东西，而不是人说出的话：原因本身就是解释。"},{"no":"08","title":"Explanatory note","titleCN":"说明文字：附在作品旁的注解","definition":"a note or passage attached to a work to explain its context or terms","definitionCN":"附在作品旁、说明其背景或术语的注解或段落","example":"The map's explanation lists the symbols used in the legend.","exampleCN":"地图的说明列出了图例中使用的符号。","why":"An explanation can be a physical part of a document: it sits beside the thing it explains and opens it for the reader.","whyCN":"解释可以是文档的物理部分：它坐在被解释物旁边，为读者把后者打开。"}],"etymology":{"intro":{"en":"Explanation is from Latin explanatio, from explanare, to flatten out or make clear: ex- out plus planus flat. The same planus gives plain and plane.","cn":"explanation 来自拉丁 explanatio，源头 explanare‘摊平、使清楚’：ex-‘向外’加 planus‘平的’。同一个 planus 给出 plain 与 plane。"},"items":[{"era":"LATIN planus","en":"Flat, level, or clear. Its physical sense produced plain and plane; its figurative sense produced the idea of making a matter clear.","cn":"平的、平坦的、清楚的。物理义产生 plain 与 plane；比喻义产生‘把事情说清楚’的观念。"},{"era":"LATIN explanare","en":"Ex- out plus planus flat: to flatten out, smooth, and hence to make clear. The verb describes removing bumps from a surface.","cn":"ex-‘向外’加 planus‘平的’：摊平、抹平，因而‘使清楚’。该动词描述把表面的凸起去掉。"},{"era":"LATIN explanatio","en":"A flattening out, hence a clear setting forth. In rhetoric it named the part of a speech that made a point plain.","cn":"摊平，因而指清楚的陈述。在修辞学中它命名演说里把论点讲明白的部分。"},{"era":"FRENCH explanation","en":"French passed the noun to English. The word kept both the rhetorical sense of setting out a case and the everyday sense of clearing up confusion.","cn":"法语把名词传给英语。该词同时保留‘铺陈论点’的修辞义与‘澄清困惑’的日常义。"},{"era":"ENGLISH 14c","en":"English explanation is recorded in the 14c. Its earliest uses were theological and legal, where a text or a rule had to be expounded.","cn":"英语 explanation 在 14 世纪有记录。最早用于神学与法律：文本或规则需要被阐述。"},{"era":"MODERN ENGLISH","en":"Science gave the word its causal sense: an explanation must name a mechanism. Education and publishing kept the older senses of exposition and note.","cn":"科学赋予该词因果义：解释必须命名机制。教育与出版则保留较老的‘阐述’与‘注解’义。"}]},"similar":{"note":{"en":"The first group is the explain family; the second compares accounts that make something clear, justify it, or state its meaning.","cn":"第一组是 explain 词族；第二组比较‘使清楚、辩护或说明含义’的各种说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"explain","ipa":"/ɪkˈspleɪn/","tag":"verb","definition":"to make something clear or give its reason. It is the act behind explanation.","definitionCN":"使某事清楚或给出其原因；是 explanation 背后的动作。"},{"word":"explanatory","ipa":"/ɪkˈsplænətəri/","tag":"adjective","definition":"serving to explain. It describes the function of a note or a diagram, not the act of speaking.","definitionCN":"起解释作用的；描述注解或图表的功能，而非说话动作。"},{"word":"explainable","ipa":"/ɪkˈspleɪnəbl/","tag":"adjective","definition":"able to be explained. It says a cause can be found, not that one has been.","definitionCN":"可解释的；说明原因能够被找到，而非已经找到。"},{"word":"inexplicable","ipa":"/ˌɪnɪkˈsplɪkəbl/","tag":"negative adjective","definition":"impossible to explain. It often expresses bafflement rather than a scientific claim.","definitionCN":"无法解释的；常表达困惑，而非科学断言。"}]},{"heading":"NEAR MEANING","entries":[{"word":"interpretation","ipa":"/ɪnˌtɜːprɪˈteɪʃn/","tag":"meaning-making","definition":"an explanation of what something means, especially a text or an action. It stresses the reader's reading.","definitionCN":"对某物含义的解释，尤指文本或行动；强调读者的解读。"},{"word":"justification","ipa":"/ˌdʒʌstɪfɪˈkeɪʃn/","tag":"defence","definition":"a reason showing that an action was right or acceptable. It is an explanation offered as a defence.","definitionCN":"表明某行动正确或可接受的理据；是作为辩护提出的解释。"},{"word":"account","ipa":"/əˈkaʊnt/","tag":"narrative version","definition":"a description or report of events. It may explain without giving a cause.","definitionCN":"对事件的描述或报告；可以解释但不一定给出原因。"},{"word":"reason","ipa":"/ˈriːzn/","tag":"cause or motive","definition":"the cause of an event or the motive for an action. It is the content an explanation supplies.","definitionCN":"事件的原因或行动的动机；是解释所提供的内容。"},{"word":"clarification","ipa":"/ˌklærəfɪˈkeɪʃn/","tag":"removing confusion","definition":"a statement that removes ambiguity. It is explanation aimed at a specific misunderstanding.","definitionCN":"消除歧义的说明；是针对特定误解的解释。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out plus planus flat. An explanation flattens a tangled matter so its parts lie open to view.","cn":"只用真实成分：ex-‘向外’加 planus‘平的’。解释把缠乱的事情摊平，让各部分摊开可见。"},"normal":[{"en":"Ex- out, planus flat: explanation lays the matter flat.","cn":"ex- 向外，planus 平：explanation 把事情摊平。"},{"en":"Plain and plane share the root: to explain is to make the surface plain.","cn":"plain 与 plane 同根：explain 就是把表面弄平、弄明白。"},{"en":"A knot becomes a line when you explain it.","cn":"经你一解释，一团结就变成一条线。"},{"en":"A legend on a map is a small explanation sitting beside the symbols.","cn":"地图图例就是坐在符号旁边的小型 explanation。"},{"en":"A good teacher explains one step at a time, not the whole staircase.","cn":"好老师一次解释一级台阶，而不是整段楼梯。"}],"abstract":[{"en":"An explanation always chooses a level: it can name a cause, a mechanism, or a meaning, but not all three at once.","cn":"解释总要选择层次：可以命名原因、机制或含义，但不能同时三者都做。"},{"en":"What counts as a good explanation depends on who is asking and what would satisfy them.","cn":"什么算好的解释，取决于谁在问，以及什么能让他们满意。"},{"en":"Every explanation hides as much as it shows, because it must leave something unmentioned to stay clear.","cn":"每种解释在显示的同时也在隐藏，因为为了保持清楚，它必须留下一些东西不提。"}]},"examples":[{"en":"The report offered no explanation for the missing files.","cn":"报告对文件缺失没有给出任何解释。"},{"en":"A good explanation of gravity can be given without a single equation.","cn":"不用一个方程也能给出对引力的好解释。"},{"en":"Her explanation of the poem changed how the class read the last line.","cn":"她对这首诗的阐释改变了全班对最后一行的读法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一死泼类内神”——把问题“泼”开、摊平，里面的神就显出来：explanation 解释、说明。","word":"explanation"},"root":"源自拉丁 explanare（ex-‘向外’+ planus‘平的’，即‘摊平、使清楚’）与 explanatio；核心是“把缠乱的事情摊平，让人看清来龙去脉”。","sensesIntro":{"en":"Eight senses of explanation, one move: flatten something tangled until its parts can be seen. What is flattened may be a mechanism, an event, a behaviour, a text, or a whole subject.","cn":"explanation 的八个义项共用一个动作：把缠乱的东西摊平，直到各部分可见。被摊平的可以是机制、事件、行为、文本或整个学科。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tangled thread being smoothed flat across a table.","cn":"核心意象：一团缠线被在桌面上一点点捋平。"},"chain":["LATIN PLANUS = FLAT, CLEAR","EX- + PLANARE = TO FLATTEN OUT","EXPLANATIO = A CLEAR SETTING FORTH","ENGLISH EXPLANATION = AN ACCOUNT THAT MAKES CLEAR","A CAUSE, MECHANISM, OR MEANING IS SUPPLIED","ANY STATEMENT THAT REMOVES CONFUSION"],"branches":[{"senses":"01 · 05","en":"THE CLEARING ACT: a general clarification and a classroom exposition both flatten a subject for a listener.","cn":"澄清动作：一般说明与课堂讲解都为听者把主题摊平。"},{"senses":"02 · 07","en":"THE CAUSE: the stated reason and the natural cause both answer why something happened.","cn":"原因：陈述的理由与自然成因都在回答‘为什么发生’。"},{"senses":"03","en":"THE DEFENCE: an account offered to a judging audience must be acceptable as well as true.","cn":"辩护：说给评判者听的说法，除了真实还必须可被接受。"},{"senses":"04","en":"THE MECHANISM: scientific explanation must specify how the result could be produced.","cn":"机制：科学解释必须说明结果如何可能被产生。"},{"senses":"06 · 08","en":"THE TEXT AND THE NOTE: explaining language means translating signs, whether in a glossary or a legend.","cn":"文本与注解：解释语言就是翻译符号，无论是在词表还是图例中。"}]},"affixes":{"intro":{"en":"Explanation is ex- plus plan- plus -ation. The family includes explain, explanatory, explainable, and the negative inexplicable. Note that explicate belongs to a different root, plicare, to fold.","cn":"explanation 是 ex- 加 plan- 加 -ation。词族包括 explain、explanatory、explainable 与否定形式 inexplicable。注意 explicate 属于另一个词根 plicare‘折叠’。"},"latinIntro":{"en":"The Latin chain is planus, explanare, explanatio. The root planus means flat and also yields plain and plane; it is not the same as plicare, to fold.","cn":"拉丁链条是 planus、explanare、explanatio。词根 planus 意为平的，也产生 plain 与 plane；它与 plicare‘折叠’不同。"},"items":[{"word":"explain","structure":"ex- + planare (verb)","meaning":"to make clear or give a reason","meaningCN":"解释；说明；给出原因","example":"He explained the rule in one sentence.","exampleCN":"他用一句话解释了这个规则。"},{"word":"explanation","structure":"explan- + -ation (action noun)","meaning":"a statement that makes something clear","meaningCN":"使某事清楚的说明","example":"Her explanation was shorter than the question.","exampleCN":"她的解释比问题还短。"},{"word":"explanatory","structure":"explanation + -ory (function adjective)","meaning":"serving to explain","meaningCN":"解释性的；说明用的","example":"The diagram has an explanatory caption.","exampleCN":"这张图有一段说明性图注。"},{"word":"explainable","structure":"explain + -able (capability adjective)","meaning":"able to be explained","meaningCN":"可解释的","example":"The difference is explainable by age.","exampleCN":"这一差异可以用年龄来解释。"},{"word":"inexplicable","structure":"in- + explicable (not explainable)","meaning":"impossible to explain","meaningCN":"无法解释的","example":"The loss of pressure was inexplicable.","exampleCN":"压力下降无法解释。"},{"word":"explicate","structure":"ex- + plicare (fold) + -ate; different root from explain","meaning":"to unfold the meaning of a text in detail","meaningCN":"详细阐释文本含义（词根 plicare‘折叠’，与 explain 不同）","example":"The seminar explicated the opening paragraph.","exampleCN":"研讨课详细阐释了开头一段。"},{"word":"explicable","structure":"explic- + -able (from plicare)","meaning":"able to be accounted for","meaningCN":"可说明的；可解释的（词根为 plicare）","example":"The error is explicable by a faulty sensor.","exampleCN":"这个错误可由传感器故障说明。"},{"word":"plain","structure":"Latin planus (flat) via French","meaning":"simple, clear, or a flat area of land","meaningCN":"朴素的；清楚的；平原（源自 planus‘平’）","example":"The instructions were written in plain language.","exampleCN":"说明是用平实语言写的。"},{"word":"plane","structure":"Latin planum (flat surface)","meaning":"a flat surface, or an aircraft wing form","meaningCN":"平面；飞机（源自‘平坦表面’）","example":"The two lines lie in the same plane.","exampleCN":"这两条线位于同一平面。"},{"word":"planar","structure":"plan- + -ar (relational adjective)","meaning":"flat; lying in one plane","meaningCN":"平面的；位于同一平面的","example":"The molecule is almost planar.","exampleCN":"这个分子几乎是平面的。"}],"latinEntries":[{"word":"planus","structure":"Latin adjective","meaning":"flat, level, clear","meaningCN":"平的；平坦的；清楚的"},{"word":"explanare","structure":"ex- + planare (flatten)","meaning":"to flatten out, make clear","meaningCN":"摊平；使清楚"},{"word":"explanatio","structure":"explanat- + -io (action noun)","meaning":"a clear setting forth","meaningCN":"清楚的陈述；阐释"}]}},{"word":"explanatory","ipa_uk":"/ɪkˈsplænətəri/","ipa_us":"/ɪkˈsplænətɔːri/","definition_zh":"解释性的；说明性的；注释性的","definition_en":"intended to explain or make something clear","core_image":"一段正文旁边挂着一条细线，连到页边的小注；小注不推进故事，只负责把正文照亮。","scene":"图表下面有一行说明，指出虚线代表预测值。Under the chart an explanatory note says the dashed line stands for forecast values and the solid line for measured ones.","sceneCN":"这里 explanatory 是「用于说明、帮助理解的」（第 1、2 个义项）；句意：图表下面有一行说明，指出虚线代表预测值，实线代表实测值。","pos":[{"tag":"adj.","zh":"解释性的；说明性的；注释性的"}],"collocations":[{"phrase":"explanatory note","zh":"解释性注释"},{"phrase":"explanatory text","zh":"说明文字"},{"phrase":"explanatory variable","zh":"解释变量"},{"phrase":"explanatory power","zh":"解释力"},{"phrase":"explanatory statement","zh":"说明性陈述"},{"phrase":"for explanatory purposes","zh":"出于说明目的"}],"forms":[{"label":"原级（形容词）","form":"explanatory"},{"label":"比较级（用 more）","form":"more explanatory"},{"label":"最高级（用 most）","form":"most explanatory"},{"label":"副词形式","form":"explanatorily"}],"derivatives":[{"word":"explain","pos":"v.","zh":"解释；说明"},{"word":"explanation","pos":"n.","zh":"解释；说明"},{"word":"explanatorily","pos":"adv.","zh":"以解释方式"},{"word":"inexplicable","pos":"adj.","zh":"无法解释的"}],"senses":[{"no":"01","title":"Serving to explain","titleCN":"解释性的：功能就是让人明白","definition":"intended to explain something or make it easier to understand","definitionCN":"旨在解释某事或使其更易理解","example":"The manual opens with an explanatory section on safety.","exampleCN":"手册开头是一段关于安全的说明。","why":"The suffix -ory marks function. An explanatory thing does not do the action itself; it exists in order to help someone else understand.","whyCN":"后缀 -ory 标记功能。explanatory 的东西本身不执行解释动作；它的存在是为了帮助别人理解。"},{"no":"02","title":"Accompanying text","titleCN":"说明文字的：附在图表或正文旁","definition":"describing text or labels attached to a chart, diagram, or document to clarify it","definitionCN":"形容附在图表、示意图或文件上以澄清内容的文字或标签","example":"An explanatory caption identifies the two curves.","exampleCN":"一段说明性图注标明了两条曲线。","why":"The text sits beside the object and serves it. The figure carries the data; the explanatory caption carries the reading instructions.","whyCN":"文字坐在对象旁边并为它服务。图承载数据，说明性图注承载阅读说明。"},{"no":"03","title":"Clarifying a misunderstanding","titleCN":"澄清性的：专门消除某个误解","definition":"intended to remove a specific confusion or ambiguity","definitionCN":"旨在消除特定困惑或歧义","example":"The minister added an explanatory sentence after the backlash.","exampleCN":"在舆论反弹后，部长补了一句澄清性的话。","why":"Here the function is repair: something was misread, and the explanatory statement is aimed at that exact misreading.","whyCN":"这里的功能是修补：某处被误读了，而说明性语句正对准那处误读。"},{"no":"04","title":"Note-style annotation","titleCN":"注释性的：页边或脚注里的小说明","definition":"in the style of a note that explains a term, reference, or context","definitionCN":"以注释方式解释术语、引用或背景的","example":"The explanatory notes take up more pages than the poem.","exampleCN":"注释部分比诗本身占的页数还多。","why":"An annotation is explanation in a minor key: it stays outside the main text so that the main text can keep its own voice.","whyCN":"注解是低调的解释：它留在正文之外，好让正文保持自己的声音。"},{"no":"05","title":"Statistical explanatory variable","titleCN":"解释变量的：用来解释结果差异","definition":"in statistics, describing a variable used to account for variation in an outcome","definitionCN":"统计学中形容用来解释结果差异的变量","example":"Age was the strongest explanatory variable in the model.","exampleCN":"年龄是模型中解释力最强的变量。","why":"A model asks which input accounts for the output. The explanatory variable is the candidate cause; the response variable is what needs explaining.","whyCN":"模型问哪个输入解释了输出。解释变量是候选原因；响应变量是待解释的结果。"},{"no":"06","title":"Explaining a cause","titleCN":"说明原因的：回答“为什么”","definition":"offered in order to give the cause or reason for something","definitionCN":"为给出某事的原因或理由而提供的","example":"The report is explanatory rather than critical.","exampleCN":"这份报告重在说明原因，而非批评。","why":"This sense overlaps with causal explanation: the text is not judging the event but accounting for how it came about.","whyCN":"这个义项与因果解释重叠：文本不评判事件，而是说明它如何发生。"},{"no":"07","title":"Teaching exposition","titleCN":"教学讲解的：为学习者铺路","definition":"describing material designed to teach or walk a learner through a subject","definitionCN":"形容为教学或带学习者理解某主题而设计的材料","example":"The course begins with explanatory videos before any problem sets.","exampleCN":"课程先放讲解视频，再给习题。","why":"Here the audience is a learner, so the explanation is sequenced: each part prepares the next, rather than simply reporting a fact.","whyCN":"这里受众是学习者，因此解释是有顺序的：每一部分为下一部分铺路，而不是单纯报告事实。"},{"no":"08","title":"Justifying","titleCN":"辩解性的：为自己的行为作说明","definition":"offered as a defence or justification of an action","definitionCN":"作为对某一行动的辩护或正当化而提出的","example":"His explanatory letter did not satisfy the regulator.","exampleCN":"他的说明信没有让监管者满意。","why":"When the explanation is addressed to a judge, explanatory becomes defensive: it explains in order to excuse.","whyCN":"当解释是说给评判者听时，explanatory 就带上辩护色彩：解释是为了开脱。"}],"etymology":{"intro":{"en":"Explanatory is explain plus -atory, the Latin suffix of function (-atorius). It is recorded in English from the 17c, shortly after explanation.","cn":"explanatory 是 explain 加 -atory，即拉丁功能后缀 -atorius。英语记录始于 17 世纪，略晚于 explanation。"},"items":[{"era":"LATIN planus","en":"Flat or clear. The root gives plain, plane, and the verb planare, to flatten. The metaphor of clearing a surface runs through the whole family.","cn":"平的、清楚的。词根给出 plain、plane 与动词 planare‘弄平’。‘清理表面’的比喻贯穿整个词族。"},{"era":"LATIN explanare","en":"To flatten out and hence to make clear. The verb is the base of explain and explanation, with no folding imagery involved.","cn":"摊平，因而‘使清楚’。该动词是 explain 与 explanation 的词基，其中没有‘折叠’意象。"},{"era":"LATIN explanatorius","en":"A later adjective meaning serving to explain. Latin -atorius marks function, as in declaratory or preparatory.","cn":"较晚的形容词，意为‘起解释作用的’。拉丁 -atorius 标记功能，如 declaratory、preparatory。"},{"era":"LATIN -atorius","en":"The suffix builds adjectives of purpose or capacity from agent nouns. English -atory does the same: explanatory, obligatory, introductory.","cn":"该后缀从施动名词构成表示目的或能力的形容词。英语 -atory 同样如此：explanatory、obligatory、introductory。"},{"era":"ENGLISH 17c","en":"Explanatory enters English in the 17c as a learned adjective for notes, prefaces, and statements that serve explanation.","cn":"explanatory 在 17 世纪进入英语，作为学术形容词，用于注释、序言与说明性陈述。"},{"era":"MODERN ENGLISH","en":"Statistics added explanatory variable in the 20c. The adjective shifted from text to models without losing its function: something that accounts for something else.","cn":"统计学在 20 世纪加入 explanatory variable。形容词从文本转向模型，但功能义未变：为另一事物提供说明。"}]},"similar":{"note":{"en":"The first group is the explain family; the second compares adjectives for text that clarifies, illustrates, or defends.","cn":"第一组是 explain 词族；第二组比较用于澄清、图解或辩护的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"explanation","ipa":"/ˌekspləˈneɪʃn/","tag":"noun","definition":"the account that makes something clear. Explanatory describes what serves that function.","definitionCN":"使某事清楚的说明；explanatory 描述起该功能的东西。"},{"word":"explain","ipa":"/ɪkˈspleɪn/","tag":"verb","definition":"to make clear. The adjective does not perform the act; it labels material designed for it.","definitionCN":"使清楚；形容词不执行动作，只标记为此设计的材料。"},{"word":"explainable","ipa":"/ɪkˈspleɪnəbl/","tag":"capability adjective","definition":"able to be explained. It describes the object's status, not the text's function.","definitionCN":"可解释的；描述对象的状态，而非文本的功能。"},{"word":"inexplicable","ipa":"/ˌɪnɪkˈsplɪkəbl/","tag":"negative adjective","definition":"not able to be explained. Note that it belongs to the plicare root in form, though it is felt as the opposite of explainable.","definitionCN":"无法解释的。注意其形式属 plicare 词根，但在语感上是 explainable 的反义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"descriptive","ipa":"/dɪˈskrɪptɪv/","tag":"says what","definition":"saying what something is like without explaining why. It is the opposite of explanatory in research writing.","definitionCN":"说明某物是什么样，而不解释为什么；在研究写作中与 explanatory 相对。"},{"word":"illustrative","ipa":"/ˈɪləstrətɪv/","tag":"shows by example","definition":"serving to make something clear by example or picture. It explains by showing rather than by stating reasons.","definitionCN":"通过例子或图像使清楚；以展示而非陈述原因来解释。"},{"word":"interpretive","ipa":"/ɪnˈtɜːprətɪv/","tag":"offers a reading","definition":"offering an interpretation of meaning. It explains what something means, not why it happened.","definitionCN":"提供含义解读；解释‘意味着什么’，而非‘为什么发生’。"},{"word":"expository","ipa":"/ɪkˈspɒzətəri/","tag":"sets out a subject","definition":"intended to set out information or a subject systematically. It is broader than explanatory and less tied to causes.","definitionCN":"旨在系统陈述信息或主题；比 explanatory 更宽，且不那么绑定原因。"},{"word":"justificatory","ipa":"/ˈdʒʌstɪfɪkətəri/","tag":"defends","definition":"serving to justify. It is explanatory text with the added aim of defending an action.","definitionCN":"起辩护作用的；是带‘为行动辩护’目的的说明文字。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: explain plus -atory, a suffix of function. The word labels material whose job is to make something clear.","cn":"只用真实成分：explain 加 -atory，功能后缀。这个词标记‘职责是使某事清楚’的材料。"},"normal":[{"en":"Explain plus -atory: material whose job is explanation.","cn":"explain 加 -atory：职责就是解释的材料。"},{"en":"An explanatory caption is a footnote that stands beside the picture.","cn":"说明性图注就是站在图片旁边的脚注。"},{"en":"An explanatory variable is the input asked to account for the output.","cn":"解释变量就是被要求为输出负责的输入。"},{"en":"Explanatory notes stay outside the poem so the poem can speak.","cn":"注释留在诗外，好让诗自己说话。"},{"en":"An explanatory letter is an explanation wearing a tie: it explains to excuse.","cn":"说明信是打了领带的解释：它解释是为了开脱。"}],"abstract":[{"en":"Explanatory material is always secondary; it exists to serve something it did not create.","cn":"说明性材料永远是次要的；它存在是为了服务它未曾创造的东西。"},{"en":"The more explanatory a model, the more it must admit what it cannot account for.","cn":"一个模型越有解释力，就越必须承认它解释不了什么。"},{"en":"Every explanatory note is a small admission that the main text could not carry the reader alone.","cn":"每条说明性注释都是一次小承认：正文无法独自把读者带到终点。"}]},"examples":[{"en":"The appendix is purely explanatory and contains no new data.","cn":"附录纯粹是说明性的，不含新数据。"},{"en":"An explanatory paragraph before the table defines every abbreviation.","cn":"表格前的一段说明定义了每个缩写。"},{"en":"The model's explanatory power fell sharply once the new variable was added.","cn":"加入新变量后，模型的解释力急剧下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一死泼类内，拖瑞”——把内情泼开、拖出来给人看：explanatory 解释性的。","word":"explanatory"},"root":"由 explain 加 -atory（拉丁 -atorius，功能后缀）构成；explain 源自拉丁 explanare（ex-‘向外’+ planus‘平’）；核心是“以说明为功能、帮助他人理解”。","sensesIntro":{"en":"Eight senses of explanatory, one function: the thing exists to make another thing clear. It may be a caption, a note, a sentence of repair, a model variable, a causal account, a lesson, or a defence.","cn":"explanatory 的八个义项共有一个功能：该物存在是为了让另一物清楚。它可以是图注、注释、修补性句子、模型变量、因果说明、课程或辩护。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin line from the main text to a marginal note that lights it up.","cn":"核心意象：一条细线从正文连到页边小注，小注把正文照亮。"},"chain":["LATIN PLANUS = FLAT, CLEAR","EXPLANARE = TO MAKE CLEAR","EXPLANATIO = AN EXPLANATION","EXPLANATORIUS = SERVING TO EXPLAIN","ENGLISH EXPLANATORY = DESIGNED FOR CLARITY","ANY MATERIAL WHOSE FUNCTION IS TO CLARIFY"],"branches":[{"senses":"01 · 07","en":"THE TEACHING FUNCTION: a manual section and a course video both sequence understanding for a learner.","cn":"教学功能：手册章节与课程视频都为学习者安排理解顺序。"},{"senses":"02 · 04","en":"THE MARGINAL FUNCTION: captions and notes sit beside the main object and serve it.","cn":"页边功能：图注与注释坐在主对象旁边并为它服务。"},{"senses":"03","en":"THE REPAIR FUNCTION: a clarifying sentence targets one specific misreading.","cn":"修补功能：澄清性句子对准一处特定误读。"},{"senses":"05 · 06","en":"THE CAUSAL FUNCTION: a model variable and a causal account both explain why an outcome occurred.","cn":"因果功能：模型变量与因果说明都解释结果为何发生。"},{"senses":"08","en":"THE DEFENSIVE FUNCTION: explanatory text addressed to a judge becomes justification.","cn":"辩护功能：说给评判者听的说明文字变成正当化。"}]},"affixes":{"intro":{"en":"Explanatory is explain plus -atory. The -atory suffix marks purpose or function, as in obligatory and introductory; it is not the same as the -able of explainable.","cn":"explanatory 是 explain 加 -atory。-atory 标记目的或功能，如 obligatory、introductory；它与 explainable 的 -able 不同。"},"latinIntro":{"en":"The base is planus, explanare, and the later adjective explanatorius. The -atorius suffix is a real Latin functional ending, not an English invention.","cn":"词基是 planus、explanare，以及较晚的形容词 explanatorius。-atorius 是真实的拉丁功能词尾，不是英语自造。"},"items":[{"word":"explain","structure":"ex- + planare (verb)","meaning":"to make clear","meaningCN":"解释；说明","example":"She explained the delay in two sentences.","exampleCN":"她用两句话解释了延误。"},{"word":"explanation","structure":"explan- + -ation","meaning":"an account that clarifies","meaningCN":"解释；说明","example":"The explanation filled a whole page.","exampleCN":"这项解释占满了一页。"},{"word":"explanatory","structure":"explain + -atory (function adjective)","meaning":"serving to explain","meaningCN":"解释性的；说明用的","example":"The legend is explanatory only.","exampleCN":"图例只起说明作用。"},{"word":"explanatorily","structure":"explanatory + -ly","meaning":"in an explanatory manner","meaningCN":"以解释方式","example":"The passage is used explanatorily, not evidentially.","exampleCN":"这段文字是作说明用，而非作证据用。"},{"word":"explainable","structure":"explain + -able","meaning":"able to be explained","meaningCN":"可解释的","example":"The gap is explainable by sampling error.","exampleCN":"这一差距可由抽样误差解释。"},{"word":"inexplicable","structure":"in- + (ex)plicable","meaning":"unable to be explained","meaningCN":"无法解释的","example":"The signal remains inexplicable.","exampleCN":"这个信号仍无法解释。"},{"word":"explicable","structure":"ex- + plicare (fold) + -able","meaning":"able to be accounted for","meaningCN":"可说明的（词根为 plicare‘折叠’）","example":"The failure is explicable by fatigue.","exampleCN":"这次失败可由疲劳说明。"},{"word":"explicate","structure":"ex- + plicare + -ate","meaning":"to unfold a text's meaning","meaningCN":"详细阐释（词根为 plicare‘折叠’）","example":"He explicated the difficult stanza.","exampleCN":"他详细阐释了那节难懂的诗。"},{"word":"plain","structure":"Latin planus","meaning":"clear or flat","meaningCN":"清楚的；平的","example":"The rules were stated in plain words.","exampleCN":"规则用平实的话写明。"},{"word":"plane","structure":"Latin planum","meaning":"a flat surface","meaningCN":"平面","example":"The cut lies in a single plane.","exampleCN":"切口位于同一平面内。"}],"latinEntries":[{"word":"planus","structure":"Latin adjective","meaning":"flat, clear","meaningCN":"平的；清楚的"},{"word":"explanare","structure":"ex- + planare","meaning":"to make clear","meaningCN":"使清楚"},{"word":"explanatorius","structure":"explanat- + -orius (function adjective)","meaning":"serving to explain","meaningCN":"起解释作用的"}]}},{"word":"exploration","ipa_uk":"/ˌekspləˈreɪʃn/","ipa_us":"/ˌeksplɔːˈreɪʃən/","definition_zh":"探索；勘探；探究；考察；探查","definition_en":"the act of travelling through or investigating an unknown area, subject, or system","core_image":"一束手电光在黑暗洞穴里向前扫，光圈之外仍是未画上地图的空白。","scene":"探测器着陆后，团队把第一批地形数据称为探索，而不是测绘。After the lander touches down the team calls the first terrain data exploration rather than mapping, because nobody knows what will turn up.","sceneCN":"这里 exploration 是「对未知区域的探索」（第 1、3 个义项）；句意：探测器着陆后，团队把第一批地形数据称为探索而不是测绘，因为还不知道会发现什么。","pos":[{"tag":"n.","zh":"探索；勘探；探究；考察；（医学）探查"}],"collocations":[{"phrase":"space exploration","zh":"太空探索"},{"phrase":"oil exploration","zh":"石油勘探"},{"phrase":"a process of exploration","zh":"一个探索过程"},{"phrase":"exploration of the deep sea","zh":"深海探索"},{"phrase":"exploration into","zh":"对……的探究"},{"phrase":"exploratory surgery","zh":"探查性手术"}],"forms":[{"label":"复数（名词）","form":"explorations"}],"derivatives":[{"word":"explore","pos":"v.","zh":"探索；勘探；探究"},{"word":"explorer","pos":"n.","zh":"探索者；探险家"},{"word":"exploratory","pos":"adj.","zh":"探索性的；探查的"},{"word":"unexplored","pos":"adj.","zh":"未探索的；未勘探的"}],"senses":[{"no":"01","title":"Travel into the unknown","titleCN":"探索：走进没有地图的地方","definition":"the act of travelling through an unknown region to find out what is there","definitionCN":"穿越未知地区以查明那里有什么的行为","example":"The exploration of the upper river took three seasons.","exampleCN":"对上游河流的探索花了三个季节。","why":"The word begins with space: someone moves into ground where no account yet exists, and the account is made by moving.","whyCN":"这个词从空间开始：有人走进尚无记录的地方，而记录是靠行走做出来的。"},{"no":"02","title":"Investigation of a subject","titleCN":"探究：把未知的问题一点点打开","definition":"the systematic investigation of a subject, question, or idea","definitionCN":"对某主题、问题或观念的系统探究","example":"Her exploration of the archive changed the accepted chronology.","exampleCN":"她对档案的探究改变了公认的年表。","why":"The unknown here is intellectual rather than geographical. The explorer still moves without a map, but the terrain is made of records and questions.","whyCN":"这里的未知是智识性的，而非地理性的。探索者仍在地图之外移动，但地形由记录与问题构成。"},{"no":"03","title":"Space exploration","titleCN":"太空探索：把探测器送到未知环境","definition":"the investigation of space by probes, robots, or crewed missions","definitionCN":"通过探测器、机器人或载人任务对太空进行考察","example":"Space exploration has mapped the surface of every planet.","exampleCN":"太空探索已绘制了每颗行星的表面。","why":"The traveller is a machine and the report comes back as data. The unknown is extreme, so the exploration is designed before it is lived.","whyCN":"旅行者是机器，报告以数据返回。未知极端到必须先设计探索，再‘经历’它。"},{"no":"04","title":"Surgical exploration","titleCN":"医学探查：打开身体以查明情况","definition":"a medical procedure in which a body area is examined, often surgically, to find the cause of symptoms","definitionCN":"为查明症状原因而对身体某部位进行检查、常为手术性的程序","example":"The surgeon performed an exploration of the abdomen.","exampleCN":"外科医生对腹腔进行了探查。","why":"The unknown is inside the body. Exploration is justified when imaging cannot answer the question, so seeing directly becomes the test.","whyCN":"未知在身体内部。当影像无法回答问题时，探查就有理由：直接看见成为检验。"},{"no":"05","title":"Resource exploration","titleCN":"资源勘探：寻找可开采的矿藏","definition":"the search for mineral, oil, gas, or water resources underground","definitionCN":"在地下寻找矿产、石油、天然气或水资源","example":"Oil exploration in the basin began with seismic surveys.","exampleCN":"该盆地的石油勘探从地震勘测开始。","why":"Here the unknown is what lies below, and the goal is not knowledge but a find. Exploration ends when a resource is located, not when the map is complete.","whyCN":"这里未知在地下，目标不是知识而是发现。勘探在找到资源时结束，而不是在地图画完时结束。"},{"no":"06","title":"Reconnaissance","titleCN":"侦察：先派一小队去看路","definition":"a preliminary examination of an area or situation, especially for military purposes","definitionCN":"对地区或情况的初步查看，尤指军事目的","example":"A patrol carried out an exploration of the valley before the advance.","exampleCN":"推进之前，一支巡逻队对山谷进行了侦察。","why":"Exploration can be a small, cautious move made before a larger one. The information gathered is meant to guide action, not to satisfy curiosity.","whyCN":"探索可以是在大行动之前的小心试探。收集的信息是为了指导行动，而不是满足好奇。"},{"no":"07","title":"Data exploration","titleCN":"数据探索：先看分布再建模型","definition":"the preliminary examination of a dataset to find patterns, anomalies, and structure","definitionCN":"对数据集进行初步考察，以发现模式、异常与结构","example":"Data exploration revealed a cluster nobody had expected.","exampleCN":"数据探索揭示了一个没人预料到的聚类。","why":"Statistics borrowed the word for looking before formal testing: the analyst moves through the data without a fixed hypothesis, letting structure appear.","whyCN":"统计学借用这个词来表示‘正式检验之前的查看’：分析者不带固定假设地在数据中移动，让结构自己显现。"},{"no":"08","title":"Artistic or intellectual exploration","titleCN":"艺术与思想探索：不预设结论地试","definition":"the open-ended testing of forms, ideas, or materials without a fixed outcome","definitionCN":"对形式、观念或材料进行无固定结果的开放尝试","example":"The album is an exploration of silence as a musical material.","exampleCN":"这张专辑把静默当作音乐材料进行探索。","why":"The final sense removes the map entirely: the work is the record of a search whose destination was not known in advance.","whyCN":"最后一个义项完全去掉地图：作品就是一次搜索的记录，而终点事先并不知晓。"}],"etymology":{"intro":{"en":"Exploration is from Latin exploratio, from explorare, to investigate. The deeper link to plorare, to cry out, is a hunting hypothesis and should be marked as uncertain.","cn":"exploration 来自拉丁 exploratio，源头 explorare‘调查’。更深层与 plorare‘呼喊’的联系是一种狩猎假说，应标为“来源不确定”。"},"items":[{"era":"LATIN explorare","en":"To investigate, examine, or search out. The verb is attested, but its internal analysis is disputed: it may contain ex- plus a root related to calling or crying out.","cn":"调查、检查、搜寻。该动词有文献可证，但其内部结构有争议：可能含 ex- 加一个与‘呼喊’有关的词根。"},{"era":"LATIN plorare","en":"To cry out or wail. Some sources connect explorare with the shouts of hunters flushing game; others reject the link. Treat the hunting image as a plausible reconstruction, not a fact.","cn":"呼喊、哭喊。一些来源把 explorare 联系到猎人把猎物惊起时的喊声；另一些否认。应把狩猎意象视为合理重构，而非事实。"},{"era":"LATIN exploratio","en":"An investigation or a searching out. In military writing it could mean reconnaissance, the small move made before a large one.","cn":"调查或搜寻。在军事文献中可指侦察，即大行动之前的小动作。"},{"era":"FRENCH exploration","en":"French passed the noun to English. The geographical sense travelled with the age of voyages.","cn":"法语把名词传给英语。地理义随航海时代一起来。"},{"era":"ENGLISH 16c","en":"English exploration appears in the 16c, the century of ocean voyages. It first described travel to regions absent from European maps.","cn":"英语 exploration 在 16 世纪出现，那是远洋航行的世纪。它最初描述前往欧洲地图上没有的地区。"},{"era":"MODERN ENGLISH","en":"The 19c-20c extended exploration to science, medicine, statistics, and art. Each field keeps the same condition: the territory is unknown before the move.","cn":"19 至 20 世纪，exploration 扩展到科学、医学、统计与艺术。每个领域都保留同一条件：在行动之前，领域是未知的。"}]},"similar":{"note":{"en":"The first group is the explore family; the second compares journeys or inquiries into the unknown, each with a different aim.","cn":"第一组是 explore 词族；第二组比较进入未知的旅程或探究，各自目标不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"explore","ipa":"/ɪkˈsplɔː/","tag":"verb","definition":"to travel through or investigate an unknown area. It is the action behind exploration.","definitionCN":"穿越或调查未知区域；是 exploration 背后的动作。"},{"word":"explorer","ipa":"/ɪkˈsplɔːrə/","tag":"person noun","definition":"a person who explores. The word carries a history of voyages and claims.","definitionCN":"探索者；探险家；带有一段航行与声索的历史。"},{"word":"exploratory","ipa":"/ɪkˈsplɒrətəri/","tag":"adjective","definition":"done in order to find out something. It describes the purpose of a study or procedure.","definitionCN":"为查明某事而做的；描述研究或程序的目的。"},{"word":"unexplored","ipa":"/ˌʌnɪkˈsplɔːd/","tag":"negative adjective","definition":"not yet examined or travelled through. It names the territory before exploration.","definitionCN":"尚未被考察或穿越的；命名探索之前的领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"expedition","ipa":"/ˌekspəˈdɪʃn/","tag":"organized journey","definition":"an organized journey with a particular purpose. It is a single mission, while exploration can be the whole activity.","definitionCN":"有特定目的的组织化旅程；是单次任务，而 exploration 可以是整体活动。"},{"word":"investigation","ipa":"/ɪnˌvestɪˈɡeɪʃn/","tag":"formal inquiry","definition":"a systematic inquiry into facts, often official. It usually has a question to answer, not a blank map.","definitionCN":"对事实的系统调查，常为官方性的；通常有明确问题，而不是空白地图。"},{"word":"survey","ipa":"/ˈsɜːveɪ/","tag":"systematic look","definition":"a detailed examination of an area or a group. It is more structured and less open-ended than exploration.","definitionCN":"对地区或群体的详细考察；比 exploration 更有结构、更少开放性。"},{"word":"reconnaissance","ipa":"/rɪˈkɒnɪsns/","tag":"military look","definition":"a preliminary examination of an area for military purposes. It is exploration reduced to information for action.","definitionCN":"为军事目的对地区进行的初步查看；是压缩成‘行动信息’的 exploration。"},{"word":"search","ipa":"/sɜːtʃ/","tag":"looking for a target","definition":"an attempt to find something specific. It assumes the object is known; exploration assumes it is not.","definitionCN":"寻找特定目标；预设目标已知，而 exploration 预设目标未知。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ex- out plus explorare, to search out. The hunting-cry link to plorare is a plausible reconstruction and is marked as uncertain.","cn":"只用真实成分：ex-‘向外’加 explorare‘搜寻’。与 plorare‘呼喊’的狩猎联系是合理重构，标为来源不确定。"},"normal":[{"en":"Ex- out, explorare search out: exploration is searching outward.","cn":"ex- 向外，explorare 搜寻：exploration 就是向外搜寻。"},{"en":"A torch in a cave is the simplest picture of exploration.","cn":"洞穴里的一束手电光，就是 exploration 最简单的画面。"},{"en":"Space exploration sends a machine where a person cannot yet go.","cn":"太空探索把人还不能去的地方交给机器。"},{"en":"Surgical exploration looks inside because imaging has stopped answering.","cn":"医学探查往里面看，是因为影像已经回答不了。"},{"en":"Data exploration looks before it tests.","cn":"数据探索先看，再检验。"}],"abstract":[{"en":"Exploration is defined by the absence of a map, not by distance.","cn":"探索由‘没有地图’定义，而不是由距离定义。"},{"en":"Every exploration produces a map, and every map quietly ends the exploration it records.","cn":"每次探索都产出一张地图，而每张地图都在悄悄结束它所记录的那次探索。"},{"en":"Somebody always pays for the blank space on the map, and it is rarely the one drawing it.","cn":"地图上的空白总要有人付出代价，而付代价的很少是画图的人。"}]},"examples":[{"en":"The exploration of the cave system revealed a river no map had shown.","cn":"对洞穴系统的探索发现了一条地图上没有的河。"},{"en":"Her exploration of the topic began with a single footnote.","cn":"她对这个课题的探究始自一条脚注。"},{"en":"The company halted exploration when the price of oil fell.","cn":"油价下跌后，公司停止了勘探。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一克死，泼了泪神”——探索到绝境，一克希望死了，泪水泼向神：exploration 探索、勘探。","word":"exploration"},"root":"源自拉丁 explorare（调查、搜寻）与 exploratio；更深的 plorare‘呼喊’联系属狩猎假说，来源不确定。核心是“在没有地图的地方向外搜寻”。","sensesIntro":{"en":"Eight senses of exploration, one condition: the territory is unknown before the move. The territory may be a continent, an archive, a planet, an abdomen, a rock layer, an enemy valley, a dataset, or a medium.","cn":"exploration 的八个义项共有一个条件：行动之前领域未知。领域可以是大陆、档案、行星、腹腔、岩层、敌方山谷、数据集或某种媒介。"},"semanticMap":{"core":{"en":"CORE IMAGE: a torch beam moving through a dark cave, beyond it an unmapped blank.","cn":"核心意象：手电光在黑暗洞穴中移动，光圈之外是未画地图的空白。"},"chain":["LATIN EXPLORARE = TO SEARCH OUT","EXPLORATIO = AN INVESTIGATION","ENGLISH EXPLORATION = TRAVEL INTO THE UNKNOWN","NO MAP EXISTS YET","THE MOVEMENT ITSELF MAKES THE MAP","ANY OPEN-ENDED SEARCH"],"branches":[{"senses":"01 · 02","en":"GEOGRAPHICAL AND INTELLECTUAL TERRAIN: a river and an archive are both entered without a complete account.","cn":"地理与智识地形：河流与档案都是在没有完整记录时进入的。"},{"senses":"03 · 05","en":"DISTANT AND SUBSURFACE UNKNOWN: space and oil lie beyond ordinary reach, so instruments lead.","cn":"远方与地下的未知：太空与石油超出日常触及，因此由仪器带路。"},{"senses":"04","en":"THE BODY'S INTERIOR: surgery explores when imaging can no longer answer.","cn":"身体内部：影像无法回答时，手术去探查。"},{"senses":"06","en":"THE SMALL MOVE BEFORE THE LARGE: reconnaissance gathers information for action.","cn":"大行动前的小动作：侦察为行动收集信息。"},{"senses":"07 · 08","en":"THE OPEN SEARCH: data and art are explored without a fixed hypothesis or destination.","cn":"开放式搜寻：数据与艺术在没有固定假设或终点的情况下被探索。"}]},"affixes":{"intro":{"en":"Exploration is explor- plus -ation. The family includes explore, explorer, exploratory, explorative, and unexplored. Note that exploit is not from explorare; it comes through explicare, to unfold.","cn":"exploration 是 explor- 加 -ation。词族包括 explore、explorer、exploratory、explorative 与 unexplored。注意 exploit 不来自 explorare，而经 explicare‘展开’而来。"},"latinIntro":{"en":"The attested forms are explorare and exploratio. The link to plorare, to cry out, is a reconstruction from hunting practice and is marked as uncertain, not proven.","cn":"可证形式是 explorare 与 exploratio。与 plorare‘呼喊’的联系是从狩猎实践做出的重构，标为来源不确定，而非已证。"},"items":[{"word":"explore","structure":"Latin explorare (search out)","meaning":"to travel through or investigate the unknown","meaningCN":"探索；勘探；探究","example":"They explored the valley for two days.","exampleCN":"他们用了两天探索这个山谷。"},{"word":"exploration","structure":"explor- + -ation (action noun)","meaning":"the act of exploring","meaningCN":"探索；勘探；探究","example":"The exploration found no trace of the camp.","exampleCN":"这次探索没有发现营地的痕迹。"},{"word":"exploratory","structure":"explor- + -atory (function adjective)","meaning":"done in order to find out","meaningCN":"探索性的；探查用的","example":"They ran an exploratory analysis first.","exampleCN":"他们先做了一项探索性分析。"},{"word":"explorer","structure":"explore + -er (agent noun)","meaning":"one who explores","meaningCN":"探索者；探险家","example":"The explorer kept a careful journal.","exampleCN":"探险家仔细记了日志。"},{"word":"unexplored","structure":"un- + explored (negative participle)","meaning":"not yet explored","meaningCN":"未探索的；未勘探的","example":"The ridge remains unexplored.","exampleCN":"那道山脊仍未被人探索。"},{"word":"explorative","structure":"explor- + -ative (adjective)","meaning":"relating to exploration","meaningCN":"探索性的","example":"The study is explorative rather than confirmatory.","exampleCN":"这项研究是探索性的，而非确认性的。"},{"word":"exploratorily","structure":"exploratory + -ly","meaning":"in an exploratory manner","meaningCN":"以探索方式","example":"The sample was tested exploratorily.","exampleCN":"样本被以探索方式测试。"},{"word":"explorational","structure":"exploration + -al","meaning":"relating to exploration","meaningCN":"与探索有关的","example":"The agency set an explorational target.","exampleCN":"该机构设定了一个勘探目标。"},{"word":"exploit","structure":"Old French esploit < Latin explicare (unfold); not from explorare","meaning":"to use a resource, often unfairly","meaningCN":"开发利用；剥削（经 explicare‘展开’，与 explorare 不同源）","example":"The company exploited the mineral deposit.","exampleCN":"公司开发了这处矿床。"},{"word":"exploitation","structure":"exploit + -ation; not from explorare","meaning":"the use or unfair use of a resource or person","meaningCN":"开发利用；剥削（与 exploration 不同源，需区分）","example":"The report documented labour exploitation.","exampleCN":"报告记录了劳工剥削。"}],"latinEntries":[{"word":"explorare","structure":"Latin verb","meaning":"to investigate, search out","meaningCN":"调查；搜寻"},{"word":"exploratio","structure":"explorat- + -io (action noun)","meaning":"an investigation, reconnaissance","meaningCN":"调查；侦察"},{"word":"plorare","structure":"Latin verb (link reconstructed)","meaning":"to cry out, wail; possibly the source of explorare","meaningCN":"呼喊；哭喊（与 explorare 的联系属重构，来源不确定）"}]}}]);
